BEGIN;

-- 1) 既存111問（asked/terms/think/vs/optは既にある）に point/why_asked/kid/eg を非破壊マージ
UPDATE public.questions q
SET explanation_data = q.explanation_data || v.value
FROM jsonb_each('{"m4q01": {"point": "既存プロジェクトを丸ごと組織を跨いで移したいなら、リソースを作り直さずprojects.moveで移動し、請求先だけ付け替える。", "why_asked": "買収・組織再編のシナリオはACEで頻出。IaCツールで作り直す発想に流れやすいが、既存リソースを保持したまま最小労力で移すという要件を見落とすと不正解を選びやすい。", "kid": "プロジェクトはそのまま持って行けるので、組織の移動先を指定して、支払い元を変えるだけでよい。", "eg": "会社の支店(プロジェクト)を親会社(組織)ごと別のグループ会社に移すとき、支店の設備を一つずつ運び出す必要はなく、住所変更届と支払い口座の変更届を出すだけで済むのに似ている。"}, "m4q05": {"point": "トラフィックを受けながら容量を落とさず更新したいならmaxUnavailable=0(先に減らさない)、maxSurge≥1(先に増やす)にする。", "why_asked": "maxSurgeとmaxUnavailableの数値の意味を取り違えると設定を逆にしてしまう。本番稼働中の可用性維持がACEの重要テーマなので頻出する。", "kid": "新しいインスタンスを先に足してから古いのを消せば、使える台数が一度も減らない。", "eg": "エレベーターの点検で、1台を止める前に代わりの仮設エレベーターを先に用意してから古いのを止めれば、利用者が使える台数が一度も減らないのと同じ考え方。"}, "m4q07": {"point": "請求先へのリンクだけ触らせたいならBilling Account User(＋Project Billing Manager)。プロジェクト自体の操作権限は含めない。", "why_asked": "IAMの最小権限設計はACEの中心テーマ。『請求』と『プロジェクトリソース操作』を同じ権限だと誤解しやすく、Ownerのような広いロールを安易に選んでしまいやすい。", "kid": "お金の紐付けだけできる係と、部屋(プロジェクト)を作れるだけの係を、別々の小さな権限に分けて渡す。", "eg": "会社の経理担当には『どの銀行口座から支払うか』を決める権限だけを渡し、社内の備品を発注する権限は営業担当に渡す、というように役割ごとに権限を切り分けるのに似ている。"}, "m4q18": {"point": "GCP外(オンプレミス)からAPI認証するならメタデータサーバーが使えないので、サービスアカウントキーファイルを持たせるしかない。", "why_asked": "メタデータサーバーによる自動認証はGCP内のVM限定という制約を理解しているかを問う。オンプレやマルチクラウドからの認証方法はACEで頻出のパターン。", "kid": "GCPの外にいるアプリは自動ではログインできないので、鍵ファイルを持たせて自己申告してもらう必要がある。", "eg": "社内ネットワークに繋がっているパソコンは社員証をかざすだけで自動的に本人確認されるが、自宅から会社のシステムに入るときは事前に発行されたパスワードやトークンを自分で入力しないといけないのと同じ。"}, "m4q21": {"point": "Windows VMにRDPでログインしたいなら、gcloud compute reset-windows-passwordでその場限りのログイン情報を発行する。", "why_asked": "LinuxのSSH認証(公開鍵)とWindowsのRDP認証(ユーザー名・パスワード)の仕組みの違いを理解しているかを問う。SSHキーの知識をそのままWindowsに当てはめてしまう誤りが起きやすい。", "kid": "WindowsのVMにはSSHキーではなく、専用コマンドでその場で作るパスワードを使ってログインする。", "eg": "賃貸マンションの入居時に、以前住んでいた部屋の合鍵は使えず、管理会社にその場で新しい鍵を発行してもらう必要があるのと似ている。"}, "m4q22": {"point": "特定の1台だけにSSHさせたいならOS LoginをONにし、インスタンスレベルでcompute.osLoginロールをそのグループに付与する。", "why_asked": "SSHキーの手動管理とOS LoginによるIAM連動管理の違いを理解しているか、また権限の付与レベル(プロジェクト全体かインスタンス単位か)を正しく絞れるかを問う。", "kid": "鍵を配って回るのではなく、IAMの権限でこの1台だけに入れるよう設定する。", "eg": "オフィスの特定の会議室だけに入れるICカードを、来客リストに沿って発行するシステムを導入すれば、鍵を1本ずつ手渡しして回収する手間がなくなるのと同じ。"}, "m4q26": {"point": "GKEでHTTPSの公開URLを外部公開したいならKubernetes Ingressを使う。ServiceだけではTLS終端やルーティングの一元管理ができない。", "why_asked": "GKEの外部公開手段(NodePort/LoadBalancer Service/Ingress)の使い分けはACEの頻出テーマ。IngressがServiceの一種ではなく、複数サービスをまとめて1つのロードバランサで公開する仕組みだという点を誤解しやすい。", "kid": "複数のアプリをまとめて1つの窓口(ロードバランサ)でHTTPS公開したいときはIngressを使う。", "eg": "大きなビルに複数のテナント店舗があるとき、店ごとに別々の出入口を作るのではなく、ビルの正面受付(Ingress)を1つ作ってそこから各店に案内する方が管理しやすいのと同じ。"}, "m4q28": {"point": "プロジェクト全体を読み取り専用で見せたいだけならプリミティブロールのProject Viewer(roles/viewer)で足りる。", "why_asked": "『読み取り専用』という要件に対して、既製のプリミティブロールで済むところをわざわざカスタムロールや個別リソースごとのViewerを組み立ててしまう、過剰実装の誤りを見抜けるかを問う。", "kid": "見るだけでいい人には、GCPが最初から用意している『見るだけ』ロールをそのまま渡せばよい。", "eg": "会社見学に来た人に、鍵をわざわざ作らせるのではなく、あらかじめ用意されている『見学者用の入館証』を渡すだけで済むのと同じ。"}, "m4q31": {"point": "組織が既にG Suite(Google Workspace)を使っているなら、そのアカウントをそのままIAMポリシーに追加すればよく、Cloud Identityの追加設定は不要。", "why_asked": "Cloud IdentityはG Suiteを持たない組織向けの仕組みという条件を混同しやすい。既にGoogleアカウント基盤がある場合の最短経路を選べるかを問う。", "kid": "会社のGoogleアカウントはもう『Googleアカウント』そのものなので、追加の変換や仕組み無しでIAMにそのまま登録できる。", "eg": "会社の社員証がすでに全国共通の身分証として使える場合、新しい身分証を別に発行する必要はなく、今持っている社員証をそのまま提示すればよいのと同じ。"}, "m4q34": {"point": "『いつリソースが作成・変更されたか』を調べたいなら、常時有効なAdmin Activityログ(Configurationカテゴリ)をリソースタイプで絞って見る。", "why_asked": "Admin Activity(設定変更の記録・常時有効)とData Access(データの読み書きの記録・デフォルト無効)の違いを混同しやすい。監査ログの種類を正しく使い分けられるかがACEで問われる。", "kid": "『いつ作られたか』を知りたいときは、設定変更を記録している方のログを見る。データの中身を読んだ記録とは別物。", "eg": "マンションの管理記録に『入居者が増えた記録』と『エレベーターの利用記録』の2種類があるとき、いつ新しい住人(サービスアカウント)が入居したかを知りたいなら前者を見るのと同じ。"}, "m4q36": {"point": "特定の1プロジェクトだけに予算アラートを設定したいなら、Billing Account Administratorが請求先アカウント側でそのプロジェクトを対象に予算を作る。", "why_asked": "予算(Budget)はプロジェクトの設定ではなく請求先アカウント側の機能だという点、そしてProject OwnerではBillingコンソールを操作できないという権限の境界線を理解しているかを問う。", "kid": "予算を決められるのはプロジェクトの担当者ではなく、お財布(請求先アカウント)を管理している人。", "eg": "家計の中で子供部屋の電気代だけ上限を決めたいとき、決めるのは子供本人ではなく家計全体を管理する親であり、しかもその設定は家計簿(請求先アカウント)側で行うのと同じ。"}, "m4q37": {"point": "必要なvCPU数がはっきり分かっているオンプレアプリの移行なら、最初からそのvCPU数に合うマシンタイプ(n1-standard-96)を指定して作る。", "why_asked": "マシンタイプのファミリー(standard/highcpu/highmem)ごとのメモリ比率の違いと、後からvCPU数を変えるには停止が必要という制約を理解しているかを問う。デフォルトから始めて調整する発想は非効率だと見抜けるか。", "kid": "必要な性能が最初から分かっているなら、遠回りせずその性能のマシンをいきなり選ぶ。", "eg": "4人家族の引っ越しで必要な部屋数が最初から分かっているなら、1Kの部屋を借りてから後で広い部屋に住み替えるより、最初から4人分の部屋がある物件を契約する方が手間がないのと同じ。"}, "m4q40": {"point": "単一地域縛り＋直近高頻度→年1回程度のアクセスパターンなら、Regional Storageに置いて30日後にColdlineへ自動移行するライフサイクルルールを組む。", "why_asked": "ストレージクラスの『地理的制約』と『アクセス頻度に応じたコスト最適化』は別軸の話であることを理解し、両方の要件を同時に満たす組み合わせを選べるかを問う。Nearline/Coldlineのアクセス頻度の目安を混同しやすい。", "kid": "最初はよく使うのですぐ取り出せる場所に置き、使わなくなったら自動で一番安い保管場所に移す。", "eg": "引っ越し直後によく使う荷物は手元に置いておき、使わなくなった季節物は自動的にトランクルームの一番奥(一番安い区画)へ移すタイマーをセットしておくのと同じ。"}, "m4q42": {"point": "PodがPending(未配置)のままの原因を調べたいならkubectl describe podのEventsを見る。Deployment/Serviceはその原因を持っていない。", "why_asked": "Kubernetesのトラブルシューティングでどのオブジェクトの単位で情報を見るべきかを理解しているかを問う。ログ(logs)はコンテナ起動後の情報であり、起動前のスケジューリング問題には使えないという区別が特に狙われる。", "kid": "まだ席に着けていないPodの理由は、Pod自身の詳細情報を見ないと分からない。", "eg": "飛行機に搭乗できていない乗客がいるとき、その理由は搭乗ゲートの案内板や運航スケジュール全体ではなく、その乗客個人の予約記録を確認しないと分からないのと同じ。"}, "m4q47": {"point": "マルチテナントでPod間の分離を最大化したいならGKEサンドボックス(gVisor)。runtimeClassName: gvisorをPod仕様に指定する。", "why_asked": "通常のコンテナ分離(Linux namespace)では不十分な、より強固な実行時分離の仕組みを知っているかを問う。Binary Authorizationのようなデプロイ時制御と実行時分離を混同しやすい。", "kid": "普段のコンテナよりもっと厚い壁で、他人のプログラムと自分のプログラムを隔てる仕組みを使う。", "eg": "相部屋の宿泊施設で、普通の仕切りカーテンの部屋ではなく、壁と鍵付きドアでしっかり区切られた個室タイプの部屋を選んで、他の宿泊者の物音や視線を完全に遮断するようなもの。"}, "m4q48": {"point": "サポートのアクセスリクエストを承認する権限は、個人にではなくグループにroles/accessapproval.approverを付与する。", "why_asked": "Access Approvalという機能自体の存在に加え、Googleが推奨する『権限は個人でなくグループに付与する』というIAM運用のベストプラクティスが組み合わさって問われる。", "kid": "承認する係の権限は、特定の1人ではなくチーム全体に渡しておく。人が入れ替わっても設定し直さずに済む。", "eg": "会社の代表印を押す権限を特定の1人だけに与えると、その人が異動するたびに引き継ぎ作業が発生するが、『承認担当チーム』というグループに権限を渡しておけば、メンバーの入れ替えだけで済むのと同じ。"}, "m5q01": {"point": "異なるプロジェクト間でプライベートIP同士を直接通信させたいなら、VPCピアリングか共有VPCのどちらかで実現できる。", "why_asked": "プロジェクトを跨いだネットワーク接続の選択肢(ピアリング・共有VPC・Interconnect・NAT)を整理して理解しているかを問う。目的の違うサービス(Cloud NAT等)を紛れ込ませて選ばせる典型パターン。", "kid": "別々のプロジェクトのVMを直接つなぐ方法は、廊下でつなぐか、最初から同じ建物にするかの2通りがある。", "eg": "隣り合う2つの家をつなぐ方法として、庭に渡り廊下を作る方法と、そもそも最初から二世帯住宅として1つの建物にまとめる方法の2通りがあるのと同じ。"}, "m5q10": {"point": "GKEのPodからGCP APIにキーファイルなしでアクセスしたいならWorkload Identityで、KubernetesのSAとIAMのSAを紐づける。", "why_asked": "サービスアカウントキーの管理リスクを避ける『キーレス認証』はACE全体の重要テーマで、GKE文脈での標準解がWorkload Identityであることを知っているかを問う。ノードSAに広い権限を持たせる誤答が特に紛らわしい。", "kid": "Podごとに専用の身分証を持たせて、鍵ファイルなしで自動的に本人確認してもらう仕組みを使う。", "eg": "会社の中で部署ごとに専用のICカードを発行しておけば、紙の許可証(キーファイル)をいちいち持ち歩かなくても、カードをかざすだけでその部署の権限で入退室できるのと同じ。"}, "m5q11": {"point": "組織内の新規バケットすべてに公開アクセス禁止を自動適用したいなら、Organization Policyのconstraints/storage.publicAccessPreventionを組織レベルで強制する。", "why_asked": "IAM(誰が何をできるか)ではなく、リソースの設定自体を制限する組織ポリシーという別の統制手段を理解しているかを問う。手動運用やIAMのカスタムロールでは適用漏れが起きるという弱点を見抜けるか。", "kid": "『公開設定は禁止』というルールを組織全体に一括でかけておけば、新しく作るバケットにも自動的にかかる。", "eg": "マンション全体の管理規約で『ベランダに物を置くの禁止』を決めておけば、新しく入居してきた部屋にも自動的にそのルールが適用され、部屋ごとに個別に注意して回る必要がないのと同じ。"}, "m5q22": {"point": "メトリクスの閾値超えでSlackに通知したいならCloud Monitoringのアラートポリシー＋Notification Channel(Webhook)を使う。", "why_asked": "メトリクスベースの通知は最短でCloud Monitoringのアラート機能を使うべきところを、ログ経由やポーリングなど遠回りな構成を選んでしまわないかを問う。", "kid": "しきい値を超えたら自動で警報が鳴って、その警報の届け先としてSlackを設定しておく。", "eg": "家の水道メーターに『使用量がここを超えたら自動でスマホに通知が来る』設定をしておけば、毎日メーターを見に行ったり、複雑な仕組みを別に作ったりする必要がないのと同じ。"}, "m5q31": {"point": "複数プロジェクトに同じ操作を繰り返すスクリプトを組みたいならgcloud configurations(構成)を切り替えながらgcloudコマンドを実行する。", "why_asked": "gcloudの構成(configuration)機能を知らないと、プロジェクトごとにSSHしたり手動確認したりする非効率な方法を選んでしまう。CLIの運用効率化はACEで実務スキルとして問われる。", "kid": "プロジェクトごとの設定をあらかじめ登録しておいて、スクリプトの中で切り替えながら同じコマンドを繰り返し実行する。", "eg": "複数の支店を担当する営業が、支店ごとの資料一式をあらかじめフォルダ分けしておけば、訪問のたびに必要な資料だけ取り出して使えるのと同じで、いちいち一から資料を作り直さなくて済む。"}, "m5q37": {"point": "既存クラスタを維持しつつ一部チームだけGPUを使わせたいなら、GPU対応ノードプールを追加してnodeSelectorでMLチームのPodだけをそこに配置する。", "why_asked": "ノードプールの追加とnodeSelectorによるスケジューリング制御という、GKEでワークロードを分離する標準パターンを理解しているかを問う。既存ノードのマシンタイプを後から変更できないという制約も狙われる。", "kid": "クラスタの中にGPU専用の一角を作って、GPUが必要な仕事だけそこに割り振る。", "eg": "工場の一角にだけ特殊な機械を追加で導入し、その機械を使う作業だけをそこに割り当てれば、工場全体を作り替えたり、他の作業員にまで特殊機械を使わせたりせずに済むのと同じ。"}, "m5q38": {"point": "一定期間オブジェクトを誰にも変更・削除させたくないならCloud StorageのRetention Policyで保持期間を設定する(Lockedにすれば管理者でも解除不可)。", "why_asked": "IAMでの権限剥奪(管理者なら戻せてしまう)と、Retention Policyによる真のimmutability(変更不可能性)の違いを理解しているかを問う。コンプライアンス要件の定番パターン。", "kid": "『この期間は誰も触れない』という設定を、権限とは別にオブジェクト自体にかけておく。", "eg": "契約書を金庫に入れて、社長でさえ一定期間は開けられないようタイムロックをかけておくイメージ。鍵(権限)を取り上げるだけでは、後で鍵を作り直されてしまうので不十分。"}, "m5q39": {"point": "ログを長期保存しつつBigQueryでSQL分析したいならログシンクでBigQueryデータセットに自動エクスポートする。", "why_asked": "Cloud Logging単体での長期保存はコストが高くなるという弱点と、シンクによる自動転送という標準アーキテクチャを理解しているかを問う。", "kid": "溜まったログを自動的にBigQueryへ送る設定をしておけば、安く長期保存しつつSQLで分析できる。", "eg": "毎日の日記を手元のノートに溜め込み続けるとかさばって場所を取るので、定期的にスキャンしてクラウドのデータベースに自動保存し、あとで検索しやすくしておくのと同じ。"}, "m5q42": {"point": "ユーザーごとに1日のクエリ処理データ量に上限をかけてコストを抑えたいなら、BigQueryのCustom Quota(カスタムコスト管理)を設定する。", "why_asked": "BigQueryのオンデマンド課金は処理データ量に比例するため、アクセス権限(IAMロール)の変更とコスト制御はまったく別の手段だと理解しているかを問う。", "kid": "使いすぎを防ぎたいときは、アクセスを止めるのではなく、1日に処理できるデータ量そのものに上限を設定する。", "eg": "会社の複合機で『1人あたり1日に使える用紙は何枚まで』と印刷枚数の上限を設定しておけば、複合機自体を使えなくすることなく使いすぎだけを防げるのと同じ。"}, "m5q43": {"point": "別VPCにある2つのGKEクラスタのPod同士をプライベートIPで繋ぎたいならVPCピアリングを設定し、Pod CIDRが重複していないか確認する。", "why_asked": "GKEのPodには通常のサブネットIPとは別にPod CIDRがあり、ピアリング時にはそちらも重複してはいけないという、GKE特有の注意点を理解しているかを問う。", "kid": "2つのクラスタのネットワークを直接つなぐには、Podに割り当てられた住所の範囲が重ならないことを先に確認してから橋渡しする。", "eg": "2つの町を1つの道路網に繋げるとき、それぞれの町の住所の番地(Pod CIDR)が偶然同じ体系だと混乱するので、繋ぐ前に番地が被っていないか確認しておく必要があるのと同じ。"}, "m5q45": {"point": "複数環境で同じ構成を差異なく再現し、変更履歴も残したいならIaC(Terraform等)でリソースをコード化しバージョン管理する。", "why_asked": "手作業での環境構築は設定差異(configuration drift)を生みやすいという弱点と、コード化による再現性・レビュー可能性がIaCの本質的な価値であることを理解しているかを問う。", "kid": "手作業で3つの環境を作ると少しずつズレていくので、設計図をコードにしておいて、同じ設計図から3つとも作る。", "eg": "同じ設計図(コード)を使って3棟の家を建てれば寸分違わず同じ仕上がりになるが、職人の感覚だけで3回家を建てると、細部が毎回微妙に違ってしまうのと同じ。"}, "m5q46": {"point": "ローリングアップデート中に不具合が出て前バージョンに戻したいなら、rolling-action start-updateで旧テンプレートを指定して同じ仕組みで巻き戻す。", "why_asked": "ロールバックも新規のローリングアップデートと同じコマンド・仕組みで実行できるという発想を知っているかを問う。MIGごと作り直すような過剰な対応を選ばないよう注意させる狙いもある。", "kid": "『新しいバージョンに更新する』のと同じ操作を、今度は『古いバージョンに戻す』向きで実行するだけでよい。", "eg": "商品の入れ替えを間違えたとき、店をたたんで作り直すのではなく、同じ入れ替え作業の手順をもう一度、今度は元の商品で行えば早く元に戻せるのと同じ。"}, "m5q47": {"point": "静的コンテンツの世界規模でのレイテンシを下げたいならCloud CDNのCACHE_ALL_STATICと適切なCache-Controlヘッダーの組み合わせでエッジにしっかりキャッシュさせる。", "why_asked": "CDNの効果を最大化するには、単にCDNを有効にするだけでなくキャッシュモードとヘッダー設定を正しく組み合わせる必要があるという実務知識を問う。オリジン側のストレージ設定(Multi-Regional)とCDNキャッシュの効果を混同しやすい。", "kid": "世界中どこからでも速く表示させたいなら、各地の中継拠点にコンテンツをしっかりコピーさせておく設定をする。", "eg": "全国チェーンの店舗に人気商品を事前に配送して在庫を置いておけば、本社の倉庫までいちいち取りに行かなくても近くの店ですぐ買えるようになるのと同じ。"}, "m6q01": {"point": "特権SAを一時的に借用してコマンドを実行させたいならキーは配らず、roles/iam.serviceAccountTokenCreatorを付与して短期トークンで借用させる。", "why_asked": "サービスアカウントの『借用(impersonation)』という概念と、それに必要な最小権限のロールを正しく選べるかを問う。SA自体の管理ロール(Admin)や広すぎるOwnerと混同しやすい。", "kid": "鍵そのものを渡すのではなく、必要なときだけ一時的に『その権限になりすませる』許可だけを渡す。", "eg": "上司が部下に金庫の鍵を渡す代わりに、必要なときだけ本人確認をした上でその場限りの入室証を発行してくれる仕組みに近い。誰がいつ入ったかも記録に残る。"}, "m6q02": {"point": "期限付きでアクセスを付与し期限後は自動で切れるようにしたいならIAM Conditionsで有効期限の条件式をロール付与に付ける。", "why_asked": "期限管理を人の手による剥奪作業に頼らず、IAM Conditionsという標準機能で自動化できることを知っているかを問う。手動運用やカスタムスクリプトは過剰実装だと見抜けるか。", "kid": "権限そのものに『いつまで有効か』を設定しておけば、期限が来たら人が何もしなくても自動的にアクセスできなくなる。", "eg": "会議室の予約システムで来客用の入館証に自動で有効期限を設定しておけば、会議が終わった時間を過ぎると自動的に使えなくなり、受付でいちいち回収する必要がないのと同じ。"}, "m6q03": {"point": "SAをVMにアタッチして起動させたいエンジニアには、そのSAに対するroles/iam.serviceAccountUserとcompute.instances.create権限を渡す。", "why_asked": "『SAを使ってリソースを動かす(User)』権限と『SAになりすます(TokenCreator)』権限、『SAを管理する(Admin/KeyAdmin)』権限は目的が異なる別のロールだと区別できるかを問う。", "kid": "VMに社員証(SA)を持たせて働かせるための許可であって、SA自体を管理したりなりすましたりする許可ではない。", "eg": "会社の配送車にドライバー用の身分証を積んで走らせる許可と、その身分証を発行・管理する許可は別の権限であるのと同じで、運転する人には前者だけあればよい。"}, "m6q04": {"point": "ユーザー管理のSAキーのローテーション漏れが問題ならキーレス認証(Workload Identity・借用・アタッチ済みSA)への移行が根本対策で、残るキーだけ定期ローテーションする。", "why_asked": "SAキーという長期秘密情報そのものを減らすのがGoogleの根本方針であることを理解しているかを問う。『キーの管理を簡素化する』ような対症療法(統合・別手段への安易な依存)との違いを見抜けるか。", "kid": "一番安全なのは、そもそも鍵を配らなくて済む仕組みに切り替えること。残った鍵だけ定期的に交換する。", "eg": "家の合鍵をたくさん配って紛失リスクが高まっているなら、合鍵を配るのをやめてスマートロックの一時的な暗証番号方式に切り替えるのが根本的な対策で、合鍵を1本にまとめるのは解決にならないのと同じ。"}, "m6q05": {"point": "フォルダ配下の全プロジェクト(将来追加分も含む)に一括で閲覧権限を渡したいならフォルダレベルでroles/viewerを付与する。継承で自動的に配下へ及ぶ。", "why_asked": "IAMポリシーが上位(組織・フォルダ)から下位(プロジェクト)へ継承されるという仕組みを理解し、必要以上に広い組織レベルでも、逐一手間がかかる個別付与でもない、ちょうどよいスコープを選べるかを問う。", "kid": "ひとまとまりのグループ(フォルダ)にまとめて権限を渡せば、その中の全部屋(プロジェクト)に自動的に効き、新しい部屋が増えても改めて設定し直さなくてよい。", "eg": "学年全体(フォルダ)に『図書室利用証』を発行しておけば、新しいクラス(プロジェクト)が増えても自動的に利用証が有効になり、クラスごとに毎回発行し直す必要がないのと同じ。"}, "m6q06": {"point": "AWSのIAMロールからキーファイルなしでGCPに認証させたいならWorkload Identity FederationでAWSのIDをGCPのSAにマッピングする。", "why_asked": "外部クラウドのIDをそのまま信頼してGCPにアクセスさせる仕組み(Federation)と、SAキーをどこかに保管して使い回す方法との根本的な違い(前者はキー自体が存在しない)を理解しているかを問う。", "kid": "AWS側の身分証をそのままGCP側でも信用してもらえるように、事前に信頼関係を結んでおく。鍵ファイルを一切用意しなくてよい。", "eg": "提携している海外の大学の学生証を、そのまま自分の大学の図書館でも使えるように事前に提携協定を結んでおけば、別途新しい学生証を発行してもらう必要がないのと同じ。"}, "m6q07": {"point": "新規VMも含めて外部IPの割り当てを組織全体で禁止したいなら組織ポリシーのconstraints/compute.vmExternalIpAccessを設定する。", "why_asked": "ファイアウォール(トラフィック制御)と組織ポリシー(リソースの設定自体を制限)は防御のレイヤーが違うという点を理解しているかを問う。外部IPを完全に『割り当てさせない』ことと『通信を止める』ことの違いが特に狙われる。", "kid": "『そもそも外部IPを付けさせない』というルールを組織全体に強制しておけば、後から誰が作っても外部IPは付かない。", "eg": "会社の規則で『社用パソコンに個人のUSBメモリを挿すことを禁止する』と決めておけば、あとから誰が新しいパソコンを持ち込んでも自動的にその規則が適用されるのと同じで、都度注意して回る必要がない。"}, "m6q08": {"point": "稼働スペックが3年確定しているならプリエンプティブルでもSUD任せでもなく、確約利用割引(CUD)を3年契約で購入するのが最大の割引になる。", "why_asked": "常時稼働が確定しているワークロードに対する最適な割引制度の選び方を問う。中断されうるプリエンプティブル/Spotは本番の常時稼働要件に合わないという制約と、自動適用されるSUDよりCUDの方が割引率が高いという序列を理解しているかがカギ。", "kid": "使う量と期間があらかじめ確定しているなら、その分をまとめて契約してしまう方が一番安くなる。", "eg": "3年間同じジムに通うと決まっているなら、毎回の都度払いよりも3年分の年間パスをまとめて契約した方が総額は安くなるのと同じ。"}, "m6q09": {"point": "vCPUとメモリの必要量が事前定義タイプの固定比率（standard=1:4など）に合わず余りが出るなら、カスタムマシンタイプで必要な分だけ指定する。", "why_asked": "実務のコスト最適化で頻出のパターン。standard/highmem/highcpuの比率を覚えているだけでは、要件がその比率からズレたときに『とりあえず一段階上のタイプ』を選んで余剰コストを払ってしまう。カスタムマシンタイプの存在を知っているかがACEで問われる。", "kid": "GCPの標準的なマシンタイプはvCPUとメモリの比率が固定されているため、6vCPU・20GBのような半端な要件だとメモリが余って割高になる。カスタムマシンタイプならvCPUとメモリを別々に指定でき、無駄なく必要な分だけ確保できる。", "eg": "食べ放題で決まったコース料理が出てくると余ってしまうように、standardタイプは決まった比率でメモリが余ってしまう。カスタムマシンタイプなら、必要な量だけ自分で皿に取り分けられるイメージ。"}, "m6q10": {"point": "物理ホストの専有（コンプライアンス要件やBYOLライセンス）が必要なら、Sole-tenant nodeを使う。", "why_asked": "BYOLライセンス（物理コア・ソケット単位のライセンス）は共有テナントでは要件を満たせないことがある。コンプライアンス要件やライセンス持ち込みの文脈でSole-tenant nodeを選べるかがACEで問われる。", "kid": "Windows Serverなど持ち込みライセンスの中には、物理的に自社専用のハードウェアで動かすことが条件になっているものがある。Sole-tenant nodeを使うと、その物理ホストを他の顧客と共有せずに専有できる。", "eg": "マンションの1室（共有テナント）を借りるのではなく、一棟丸ごと借りる（専有ノード）ようなもの。壁の向こうに他の入居者がいないことが保証される。"}, "m6q11": {"point": "VM起動のたびに標準イメージのまま自動で初期設定したいなら、メタデータのstartup-scriptを使う。", "why_asked": "カスタムイメージ作成という『似て非なる正解』と混同しやすい。頻繁に変わる軽い初期化にはstartup-scriptの方が向くという判断基準がACEで問われる。", "kid": "VMが起動するたびに自動で実行されるスクリプトをメタデータとして登録しておくと、標準イメージのままでもパッケージのインストールなどの初期設定を自動化できる。", "eg": "新人が出社した日に必ず配られる『初日にやることリスト』のようなもの。人（VM）自体は毎回同じでも、リストに従って自動で準備が整う。"}, "m6q12": {"point": "VMを別リージョンへ『そのまま移す』機能はないので、スナップショット→イメージ→新リージョンでVM作成という手順を踏む。", "why_asked": "GCPにVMをそのままドラッグして移動するような機能は存在しない、という消去法の知識が問われる。実務でもリージョン移行はこの手順が標準になる。", "kid": "ディスクの内容をスナップショットとして複製し、それを元にイメージを作れば、そのイメージから別リージョンで同じ構成のVMを新規作成できる。", "eg": "家（VM）ごと持ち上げて別の土地に運ぶのではなく、設計図と写真（スナップショット→イメージ）を持って新しい土地に建て直すイメージ。"}, "m6q13": {"point": "単一ゾーン障害への耐性と自動再作成を最小の運用負荷で両立したいなら、複数ゾーンにまたがるリージョナルMIG＋自動修復を使う。", "why_asked": "ゾーナルMIGとリージョナルMIGの違いを正確に区別できるかが問われる。『MIGだから高可用』と思い込むと、単一ゾーンに閉じたゾーナルMIGを選んでしまう罠がある。", "kid": "リージョナルMIGはインスタンスを複数ゾーンに自動で分散配置するので、1つのゾーンが丸ごと落ちても他のゾーンで動き続けられる。自動修復を有効にすれば、故障したインスタンスも自動で作り直される。", "eg": "1つの支店に全社員を集めるのではなく、複数の支店に分けて配置しておけば、1支店が停電しても会社全体は止まらない。"}, "m6q14": {"point": "ノード管理の運用負荷を最小化し、Pod単位の課金にしたいなら、GKE Autopilotを選ぶ。", "why_asked": "StandardとAutopilotの使い分けはACEの頻出テーマ。小規模チームや運用リソースが限られる場面で、どちらを選ぶべきかが問われる。", "kid": "Autopilotモードでは、ノードの用意・パッチ適用・スケーリングをすべてGoogleが自動で行ってくれるので、利用者はノードを一切意識しなくてよい。課金もPodが実際に使ったリソース分だけになる。", "eg": "マイカー（Standard、自分で運転も整備もする）ではなく、タクシー（Autopilot、運転も整備も任せて乗った分だけ払う）を選ぶようなもの。"}, "m6q15": {"point": "計画的な中断（ノードアップグレード等）でPodが同時に大量停止するのを防ぎたいなら、PodDisruptionBudgetで最低稼働Pod数を保証する。", "why_asked": "自動アップグレードを無効化するという安易な対処に流れがちだが、それはセキュリティパッチを受けられなくなるため非推奨。PDBという正しい対処法を知っているかが問われる。", "kid": "PodDisruptionBudgetで『最低でもこれだけのPodは動かし続ける』というルールを決めておくと、ノードアップグレードのような計画的な中断が起きても、Kubernetesはそのルールを守りながら順番にPodを退避させる。", "eg": "レジを一斉に全部閉めて掃除すると客が困るので、『最低2台は開けたまま』というルールを決めて順番に掃除するようなもの。"}, "m6q16": {"point": "機密情報（パスワード等）をコードやイメージに埋め込まずPodに渡したいなら、Kubernetes Secretを使う。", "why_asked": "ConfigMapとの混同がねらわれやすい。ConfigMapは非機密設定用であり、機密情報を入れるべきではないという区別がACEで問われる。", "kid": "SecretはKubernetesが機密情報専用に用意しているオブジェクトで、環境変数やファイルとしてPodに安全に渡せる。よく似たConfigMapは非機密の設定値用で、パスワードなどを入れる場所ではない。", "eg": "掲示板（ConfigMap）に貼り出すのは『本日のメニュー』のような公開情報で、貴重品（パスワード）は金庫（Secret）にしまうもの、という使い分け。"}, "m6q17": {"point": "複数チームで1クラスタを共有しつつチームごとにリソース上限を設けたいなら、Namespaceで分けてResourceQuotaを設定する。", "why_asked": "クラスタ自体をチーム数だけ分けるという過剰な解決策に流れがちだが、Namespaceという論理的な仕切りで十分という判断がACEで問われる。", "kid": "NamespaceはKubernetesクラスタの中を論理的に区切る仕組みで、その単位ごとにResourceQuotaでCPU・メモリの上限を設定できる。これにより1チームの使いすぎが他チームに影響しないようにできる。", "eg": "1つの電気メーター（クラスタ）を部屋ごと（Namespace）に分けて、各部屋にブレーカー容量（ResourceQuota）を割り当てるイメージ。"}, "m6q18": {"point": "GKE Standardでノード数自体を負荷に応じて自動増減させコストを抑えたいなら、Cluster Autoscalerを有効にする。", "why_asked": "HorizontalPodAutoscaler（Pod数調整）と混同しやすい。Pod数を増やしてもノードが足りなければPodはスケジュールされないため、両者の役割の違いを理解しているかが問われる。", "kid": "Cluster Autoscalerは、Podをスケジュールする場所が足りなくなるとノードを自動で追加し、逆に不要になったノードは自動で減らしてくれる。HPAはPodの数を調整するだけでノード自体は増減しない。", "eg": "レストランの客席数（ノード）を客の入りに応じて増減させるのがCluster Autoscaler。ホールスタッフ（Pod）の人数を調整するHPAとは役割が違う。"}, "m6q19": {"point": "アカウント不要で期限付きの一時アクセスを与えたいなら、署名付きURL（Signed URL）を発行する。", "why_asked": "『バケットを公開する』という過剰な選択肢に流れがちだが、非公開のまま一時的なアクセスだけを許可できる仕組みを知っているかが問われる。", "kid": "署名付きURLは、あらかじめ決めた有効期限だけ有効な特別なURL。そのURLを知っている人はGoogleアカウントがなくてもアクセスでき、期限が切れると自動的に使えなくなる。", "eg": "1回限り・時間限定の入場券を渡すようなもの。建物全体（バケット）を開放しなくても、その券を持つ人だけが期限内に入れる。"}, "m6q20": {"point": "誤った上書き・削除から元に戻せるようにしたいなら、オブジェクトバージョニングを有効にする。", "why_asked": "保持ポリシー（削除禁止）との違いが混同されやすい。保持ポリシーは『消させない』機能であって、過去の状態に戻す機能ではないという区別が問われる。", "kid": "バージョニングを有効にすると、オブジェクトが上書きや削除されても以前の内容が『非現行バージョン』として残るので、後から元の状態に復元できる。", "eg": "文書の変更履歴を残しておけば、間違えて上書きしても前のバージョンに戻せるのと同じ。"}, "m6q21": {"point": "暗号鍵のローテーション・無効化を自社でコントロールしたいなら、Cloud KMSでCMEKを設定する。", "why_asked": "デフォルト暗号でも常にデータは暗号化されているため、『暗号化されているかどうか』ではなく『鍵を誰が管理しているか』がポイントだと理解しているかが問われる。", "kid": "GCSは何もしなくても自動的にデータを暗号化しているが、その鍵はGoogleが管理している。CMEKを使うと、Cloud KMSで自社が作った鍵で暗号化でき、鍵を無効化すればデータに誰もアクセスできなくなる、という制御権を自社が持てる。", "eg": "ホテルの貸金庫（デフォルト鍵）はホテル側も合鍵を持っているが、自分の南京錠（CMEK）を付け替えれば、鍵を管理する権限は自分に移る。"}, "m6q22": {"point": "他クラウド（S3等）からGCSへの定期・オンライン転送をスケジュール実行したいなら、Storage Transfer Serviceを使う。", "why_asked": "Transfer Applianceとの使い分けが問われる頻出ポイント。回線が十分でオンライン転送が現実的な容量（この例では50TB）なら、物理輸送は不要という判断基準を持っているかがカギ。", "kid": "Storage Transfer Serviceは、S3や他のクラウド・オンプレミスからGCSへデータを転送するマネージドサービスで、スケジュールを組んで定期的に自動転送できる。", "eg": "引越し業者に定期便を頼んでおけば、指定した日にいつも決まった荷物を自動で運んでくれるようなもの。"}, "m6q23": {"point": "回線が細くオンライン転送では非現実的な時間がかかる超大容量データなら、Transfer Applianceで物理輸送する。", "why_asked": "Storage Transfer Serviceとの使い分けが問われる。データ量と回線帯域の両方を見て、オンラインかオフライン（物理）かを判断できるかがカギ。", "kid": "Transfer Applianceは、Googleから借りる物理ストレージ機器にデータを書き込み、それをGoogleに配送してGCSへアップロードしてもらう仕組み。ネットワーク回線を使わずに済むので、回線が細くても大容量データを短期間で移行できる。", "eg": "細い水道管でプールいっぱいの水を送るより、タンクローリーで運んだ方が速いのと同じ発想。"}, "m6q24": {"point": "外部IPを持たないVMからインバウンドを公開せずにアウトバウンド接続だけ許可したいなら、Cloud NATを構成する。", "why_asked": "『外部IPを付与する』という直感的だが要件（インバウンド非公開）に反する選択肢に誘導されやすい。NATがインバウンドを一切許可しないという性質の理解が問われる。", "kid": "Cloud NATは、外部IPを持たないVMが共有のNATゲートウェイ経由でインターネットへ通信できるようにする仕組み。外部からVMへ直接アクセスすることはできないので、インバウンドは公開されない。", "eg": "オフィスの各席に外線番号（外部IP）を引かなくても、代表番号（Cloud NAT）から外に電話をかけられる。ただし外から各席に直接かけることはできない。"}, "m6q25": {"point": "VMの再作成でもIPを変えたくないなら、静的外部IPアドレスを予約して割り当てる。", "why_asked": "デフォルトで割り当てられるエフェメラルIPは変動しうるため、DNS登録などIPの固定が必要な場面で正しい機能を選べるかが問われる。", "kid": "エフェメラルIPはVMに自動で割り当てられる一時的なIPで、VMを止めたり作り直したりすると変わることがある。静的外部IPは予約して確保しておくもので、VMを再作成しても同じIPを使い続けられる。", "eg": "機種変更のたびに電話番号が変わっては困るので、自分の番号として確保しておく（静的IP）のと同じ。"}, "m6q26": {"point": "VPC内部限定でカスタムドメイン名を名前解決したいなら、Cloud DNSのプライベートゾーンを作りVPCに紐付ける。", "why_asked": "パブリックゾーンとの混同がねらわれる。プライベートゾーンは紐付けたVPC内でのみ有効で、インターネットには公開されないという性質が問われる。", "kid": "Cloud DNSのプライベートゾーンは、指定したVPCネットワークの中だけで有効なDNSゾーン。社外には一切公開されないので、内部専用のドメイン名を安全に名前解決できる。", "eg": "社内だけで通じる内線電話帳を作るようなもの。社外の人がその番号にかけても繋がらない。"}, "m6q29": {"point": "イベント発生時（GCSへのアップロード等）だけ動く軽量処理をサーバー管理なしで実行したいなら、GCSイベントトリガーのCloud Functionsを使う。", "why_asked": "常時稼働のVMやGKEという過剰な選択肢に流れやすい。軽量・イベント駆動な処理にはサーバーレス関数が最も運用負荷が低いという判断が問われる。", "kid": "Cloud Functionsは、GCSへのファイルアップロードなど特定のイベントをきっかけに自動実行されるサーバーレスの関数サービス。サーバーを用意・管理する必要がない。", "eg": "郵便受けに手紙が届いた瞬間だけ自動で動く開封担当のようなもの。普段は誰も常駐していない。"}, "m6q30": {"point": "コールドスタートによるレイテンシの揺れを抑えたいなら、Cloud Runのmin-instancesを1以上に設定する。", "why_asked": "サーバーレスは『使った分だけ』が魅力だが、ゼロスケールとレイテンシの安定はトレードオフになるという実務上の勘所が問われる。", "kid": "Cloud Runはアクセスがないとインスタンス数をゼロまで減らせるが、次のリクエストが来たときに起動し直すため遅延（コールドスタート）が発生する。min-instancesを1以上にしておくと、常に待機中のインスタンスが残るのでこの遅延を避けられる。", "eg": "店を完全に閉めてしまうと開店準備に時間がかかるので、いつも1人だけ店番を残しておけばすぐに対応できるのと同じ。"}, "m6q31": {"point": "決まった時刻にHTTPエンドポイントを叩くだけの処理をサーバーレスで実行したいなら、Cloud Schedulerでcronジョブを組む。", "why_asked": "VMでcrontabを動かすという古典的な発想に流れやすいが、そのためだけにVMを常時起動するのはコストと管理の無駄という判断が問われる。", "kid": "Cloud Schedulerは、指定したスケジュール（cron形式）でHTTPエンドポイントなどを自動的に呼び出してくれるマネージドサービス。サーバーを一切用意する必要がない。", "eg": "目覚まし時計をセットしておけば、毎晩決まった時刻に自動で担当を起こしてくれるのと同じ。"}, "m6q32": {"point": "ユーザー視点で外部からサイトが実際に生きているかを定期監視したいなら、Cloud Monitoringのアップタイムチェックを設定する。", "why_asked": "CPU使用率などの内部メトリクス監視と、外部からの到達性監視（外形監視）は別物だという区別が問われる。VMは元気でもネットワーク経路の問題で外から繋がらないケースもある。", "kid": "アップタイムチェックは、世界各地のGoogleのロケーションから実際にサイトへアクセスしてみて、応答があるかを定期的に確認する機能。落ちていれば通知を送れる。", "eg": "覆面調査員が実際に世界各地から店に足を運んで、開いているか確かめて回るようなもの。体温（CPU使用率）を測るのとは別の視点。"}, "m6q33": {"point": "特定のログの出現回数を時系列で数えて急増を検知したいなら、ログベースの指標を作成しアラートポリシーを設定する。", "why_asked": "目視やBigQueryへの手動クエリという非現実的な選択肢に流れやすい。ログの内容そのものをメトリクス化してMonitoringのアラートに繋げるという発想が問われる。", "kid": "ログベースの指標は、特定の条件（例：『PaymentFailed』という文字列を含むログ）に一致したログの件数を自動でカウントし、時系列のメトリクスに変換する機能。これにCloud Monitoringのアラートポリシーを組み合わせれば、急増時に自動で通知できる。", "eg": "特定のキーワードが書類に出た回数を自動でカウントしてくれる集計器を設置し、回数が跳ね上がったら警報を鳴らすイメージ。"}, "m6q34": {"point": "アプリのエラー・例外を自動収集してグルーピングし件数を把握したいなら、Error Reportingを使う。", "why_asked": "Cloud Trace（レイテンシ分析）・Cloud Profiler（リソース使用分析）という似た系統の監視サービスとの役割の切り分けが問われる。", "kid": "Error Reportingは、アプリで発生した例外やエラーを自動的に集めて、同じ種類のエラーごとにグループ化し、件数や発生状況を一覧で見せてくれるサービス。", "eg": "クレームを内容ごとに自動で仕分けて集計してくれる窓口のようなもの。速度を測るTrace、体力を測るProfilerとは見ている対象が違う。"}, "m6q35": {"point": "Cloud Loggingのデフォルト30日を超えて長期保持したいなら、ログバケットの保持期間を延長するだけでよい。", "why_asked": "『Cloud Loggingでは長期保持できない』という誤った思い込みがねらわれる。保持期間は最大3650日まで設定変更できるという事実知識が問われる。", "kid": "Cloud Loggingがログを保存する場所であるログバケットには保持期間という設定があり、デフォルトの30日から最大3650日（10年）まで自由に延長できる。手動でのダウンロード保管などは不要。", "eg": "書類棚に貼ってある『保管期限30日』というラベルを、そのまま『400日』に貼り替えるだけで済むようなもの。"}, "m6q36": {"point": "複数サービスを横断する1リクエストの中でどこが遅いかを特定したいなら、Cloud Traceで分散トレースを見る。", "why_asked": "ログ全文検索でも似た調査はできそうに見えるが、時間内訳を横断的に可視化する専用の仕組み（分散トレース）を知っているかが問われる。", "kid": "Cloud Traceは、1つのリクエストが複数のサービスをまたいで処理される際、それぞれの区間にどれだけ時間がかかったかを自動で収集・可視化してくれる分散トレーシングサービス。", "eg": "宅配便が複数の配送センターを経由するとき、追跡番号でどのセンターに荷物が滞留していたかを特定するようなもの。"}, "m6q43": {"point": "Workerがオンプレ等GCPの外にあり自分のペースでメッセージを取得したいなら、Pullサブスクリプションを使う。", "why_asked": "Pushはサブスクライバー側に公開エンドポイントが必要という制約があり、オンプレのファイアウォール内のWorkerには不向き。PullとPushの適材適所が問われる。", "kid": "Pullサブスクリプションは、コンシューマー（Worker）側が自分から能動的にPub/Subへメッセージを取りに行く方式。処理ペースを自分で制御でき、外部に公開エンドポイントを用意する必要もない。", "eg": "郵便を自分で郵便局まで取りに行く（Pull）か、自宅まで配達してもらう（Push）かの違い。オンプレのWorkerは自宅（公開エンドポイント）を持てないので、取りに行く方式が向く。"}, "m6q44": {"point": "複数ステップの依存関係・リトライ・スケジュールを含むパイプラインをオーケストレーションしたいなら、Cloud Composer（マネージドAirflow）を使う。", "why_asked": "Cloud Schedulerは『時刻になったら1回起動する』だけで、ステップ間の依存関係やリトライまでは管理できない。単なるcronサービスとワークフローオーケストレーションの違いが問われる。", "kid": "Cloud Composerは、Apache AirflowをGoogleが管理してくれるサービス。『抽出が終わってから変換、変換が終わってからロード』のようなステップ間の依存関係（DAG）を定義し、スケジュール実行や失敗時のリトライまで面倒を見てくれる。", "eg": "料理の手順表に沿って『下ごしらえ→加熱→盛り付け』の順番を管理し、失敗したら自動でやり直す司令塔のようなもの。"}, "m6q45": {"point": "ローカルに何もインストールせずブラウザからgcloud等をすぐ使いたいなら、Cloud Shellを使う。", "why_asked": "実務でも試験対策でも頻出のツール。手元の環境構築に時間をかけず、GCPの標準ツール群がプリインストールされた環境がある、という知識が問われる。", "kid": "Cloud Shellは、ブラウザから使えるマネージドのシェル環境で、gcloud・kubectl・gitなどの主要ツールが最初から入っている。VMを立てたりローカルにSDKをインストールしたりする手間がない。", "eg": "出張先で自分のパソコンがなくても、道具一式が揃った作業デスクがすぐ借りられるようなもの。"}, "m6q46": {"point": "複数チーム・環境のコストを後から分解して把握したいなら、リソースにラベル（team・env等）を付けて請求データを分析する。", "why_asked": "リソース名に手がかりを入れて目視で読み取るという非効率な運用に流れがちだが、ラベルというメタデータ機能で機械的に集計できるという知識が問われる。", "kid": "ラベルはリソースに付けられるkey-value形式のタグ。team:salesやenv:prodのようにラベルを付けておくと、請求データをそのラベルごとに自動で集計・分解できる。", "eg": "荷物に宛先タグを付けておけば、あとから『この部署宛はいくら』と機械的に仕分け集計できるのと同じ。"}, "m6q47": {"point": "vCPU割り当て（Quota）の上限に達してエラーになったら、IAM/Quotasページから引き上げをリクエストする。", "why_asked": "割り当ては変更不可能な壁だと誤解しやすいが、正式な申請プロセスで引き上げられるという実務知識が問われる。", "kid": "Quotaはリージョンごと・サービスごとに設けられた使用上限で、意図しない暴走課金などを防ぐ安全装置。上限に達しても、コンソールのQuotasページから引き上げをリクエストして承認されれば上限を上げられる。", "eg": "クレジットカードの利用限度額に達したら、カード会社に限度額の引き上げを申請できるのと同じ。"}, "m6q50": {"point": "プリエンプティブルVMは最大24時間で必ず終了するが、Spot VMには実行時間の上限がない、という点が両者の違い。どちらもいつでもプリエンプトされうる点は共通。", "why_asked": "『Spot VMはプリエンプトされない』『どちらも同じ』といった誤解が選択肢に紛れ込みやすい。新旧の割引VMの違いを正確に区別できるかが問われる。", "kid": "プリエンプティブルVMは旧来の割引VMで、最大24時間で必ず終了し、それより前でも需要次第でプリエンプト（強制停止）されうる。Spot VMは新しい割引VMで、実行時間の上限はないが、こちらも需要次第でいつでもプリエンプトされうる点は変わらない。", "eg": "どちらも『空席（余った容量）を格安で使わせてもらう』仕組みで、満席になれば降ろされる点は同じ。違いは、プリエンプティブルには最長24時間という時間制限があり、Spotにはその制限がないという点。"}, "m7q01": {"point": "正規のIAM権限を持つ内部ユーザーによるデータ持ち出し（exfiltration）を防ぎたいなら、VPC Service Controlsでサービス境界を作る。", "why_asked": "IAMだけではアクセスの可否は制御できても、許可されたユーザーが境界外へデータを持ち出すこと自体は防げないという、IAMとVPC Service Controlsの役割の違いが問われる。", "kid": "VPC Service Controlsは、BigQueryやCloud Storageなどのサービスを『サービス境界』という論理的な壁で囲む機能。境界の中にいるリソースは、正当なIAM権限があっても境界の外へデータを持ち出す操作がブロックされる。", "eg": "金庫の鍵（IAM）を持っていても、建物の外に荷物を持ち出せないよう出口に検問（VPC Service Controls）を置くようなもの。"}, "m7q02": {"point": "他の場所で広い権限（editor等）が付与されていても特定操作だけは絶対に禁止したいなら、IAM拒否ポリシー（Deny policy）を使う。", "why_asked": "許可（allow）ポリシーだけで権限設計をしていると『継承で意図せず強い権限が付与される』ケースを防げない。拒否ポリシーが許可より優先して評価されるという評価順序の理解が問われる。", "kid": "Deny policyは、特定の相手に特定の操作を明示的に禁止するポリシー。GCPのIAM評価では許可（allow）より拒否（deny）が優先されるため、他の場所でどれだけ広い権限が付与されていても、拒否された操作だけはできなくなる。", "eg": "フリーパス（editorロール）を持っていても、特定のドアにだけ『立入禁止』の張り紙（deny policy）があれば、そこだけは通れないのと同じ。"}, "m7q03": {"point": "あるユーザーが特定リソースにアクセスできる/できない理由を、効いているロールや継承まで含めて調べたいなら、Policy Troubleshooterを使う。", "why_asked": "IAMの権限は組織・フォルダ・プロジェクトの階層から継承されるため、『なぜこの権限が効いているのか』を手作業で追うのは非現実的。専用の診断ツールがあることを知っているかが問われる。", "kid": "Policy Troubleshooterは、調べたいプリンシパル・リソース・権限を指定すると、アクセスが許可されるか拒否されるか、そしてどのロールバインディングやどの階層がその結果に効いているかを説明してくれる診断ツール。", "eg": "なぜこのドアを通れる/通れないのかを、持っている通行証と組織の階層をたどって説明してくれる調査員のようなもの。"}, "m7q04": {"point": "過去に付与した広めの権限を、実際の使用状況に基づいて安全に削減したいなら、IAM Recommenderの提案を使う。", "why_asked": "一律降格や勘に頼った権限剥奪は、必要な権限まで誤って外してしまう事故につながる。実際の利用ログに基づく安全な最小権限化の手段を知っているかが問われる。", "kid": "IAM Recommenderは、過去（例えば90日間）の実際の権限使用状況を分析し、『この権限は使われていないので、より狭いロールに変更できます』という提案を自動で出してくれる機能。", "eg": "使っていない合鍵を、実際の利用履歴を見て自動でリストアップしてくれるアシスタントのようなもの。当てずっぽうで鍵を取り上げるより安全。"}, "m7q05": {"point": "特定の1つのバケットにだけ権限を絞りたいなら、IAM Conditionsでリソース名の条件を付けてロールを付与する。", "why_asked": "プロジェクトレベルでロールを付与すると全リソースに効いてしまう。ロールの適用範囲そのものを条件式で絞り込めるIAM Conditionsの存在と使い方が問われる。", "kid": "IAM Conditionsは、ロールの付与に条件式（例：resource.name.startsWith(''project-logs-'')）を追加できる機能。この条件に一致するリソースにだけ権限が効くので、プロジェクト全体に権限を広げずに済む。", "eg": "通行証に『project-logs-で始まる部屋限定』という但し書きを付けるようなもの。他の部屋にはその通行証は使えない。"}, "m7q06": {"point": "「正しいIAMロールを持つユーザーでも社外からは拒否したい」に反応したら、Access Context Managerのアクセスレベル（コンテキストアウェアアクセス）。", "why_asked": "IAMは「誰か」を制限する仕組みで、「どこから」は制限できないと誤解しやすい。認証（誰か）と経路制限（どこから）を別レイヤーとして混同しないことがACEで問われる。VPCファイアウォールはネットワーク層の制御でコンソール/APIアクセスには効かない点も紛らわしい。", "kid": "誰であるか（IAM）が正しいだけでなく、どこからアクセスしているか（IP範囲）も条件にできる仕組みが必要、という話。それを実現するのがAccess Context Managerのアクセスレベル。", "eg": "会員証（IAMロール）は本物でも、店舗の受付でお客様が「今どこから来られましたか」を確認され、対象エリア外からの来店だと入店をお断りされる、というイメージ。"}, "m7q07": {"point": "「発行だけさせたい、管理はさせたくない」に反応したら、事前定義ロールの中から用途にぴったり合うものを選ぶ＝pubsub.publisher。", "why_asked": "editorやownerのような基本ロールを安易に付与しがちだが、ACEは最小権限の原則を体現する事前定義ロール選びを重視する。publisherとadmin（管理操作まで含む）の範囲の違いを混同しやすい。", "kid": "メッセージを送る権限だけを渡したいので、トピック削除やサブスクリプション管理までできる広いロールではなく、発行専用の狭いロールを選ぶという話。", "eg": "アルバイトに「レジに商品を並べる作業だけ」を頼むとき、店舗の経営権限（admin）や全店舗のオーナー権限（owner）まで渡さない、というイメージ。"}, "m7q08": {"point": "「複数ディスク・メタデータ・マシンタイプごと丸ごと複製・バックアップしたい」に反応したら、マシンイメージ。ブートディスクだけのスナップショットでは情報が足りない。", "why_asked": "スナップショットとマシンイメージの違いは頻出の混同ポイント。スナップショットは個々のディスクの一時点コピーであり、VM全体の構成（マシンタイプ・メタデータ・複数ディスクの組み合わせ）までは保持しない点を理解しているかが問われる。", "kid": "VMを丸ごと（複数ディスク＋設定込み）で複製・バックアップしたいなら、ディスク単位のコピーであるスナップショットではなく、VM全体の構成を保持するマシンイメージを使う、という話。", "eg": "引っ越しで、部屋1つだけの写真（スナップショット）では家具の配置や配線までは再現できないが、家全体の設計図（マシンイメージ）があれば同じ家をそっくり再現できる、というイメージ。"}, "m7q09": {"point": "「トランザクションの多いDBで高IOPS・低レイテンシ、コストより性能」に反応したら、SSD永続ディスク（pd-ssd）。", "why_asked": "pd-standard（HDD）・pd-ssd・ローカルSSDの使い分けは頻出。特にローカルSSDは高速だが非永続で、VM停止・削除でデータが消える点をDB用途の選択肢として混同しやすい。", "kid": "データベースのように頻繁に細かく読み書きする用途では、遅いHDDベースのディスクではなく、速いSSDベースの永続ディスクを選ぶという話。", "eg": "頻繁に本を出し入れする図書館の棚は、探すのに時間がかかる奥の倉庫（HDD）ではなく、すぐ取り出せる手前のガラス棚（SSD）にする、というイメージ。"}, "m7q10": {"point": "「ダウンタイム最小でディスク容量を増やしたい」に反応したら、永続ディスクのオンライン拡張＋OS側のファイルシステム拡張。削除・作り直しは不要。", "why_asked": "永続ディスクは稼働中に拡張できる一方で縮小はできないという非対称な仕様を知らないと、不要な再作成やダウンタイムを選んでしまう。この「増やせるが減らせない」制約自体がよく問われる。", "kid": "ディスクは動かしたまま容量を増やせるので、いったん削除して大きいディスクを作り直す必要はない、という話。ただし後から容量を減らすことはできない。", "eg": "使いながら容量を追加できる伸縮性のある収納ボックスのようなもの。中身を出さずにサイズを大きくできるが、小さくすることはできない、というイメージ。"}, "m7q11": {"point": "「特定ゾーンで必要な台数を確実に確保したい、在庫切れで起動できない事態を避けたい」に反応したら、予約（Reservation）。", "why_asked": "プリエンプティブルVMは安価だが中断される前提のため、容量保証の要件とは正反対になる。予約はゾーンの容量そのものを事前確保する仕組みだと理解しているかが問われる。", "kid": "必要なときに確実にVMを起動できるように、あらかじめそのゾーンの容量を確保しておく、という話。", "eg": "人気のレストランに当日ふらっと訪れると満席で入れないことがあるが、事前に席を予約しておけば当日確実に座れる、というイメージ。"}, "m7q12": {"point": "「処理中（メモリ上）のデータも暗号化された状態に保ちたい」に反応したら、Confidential VM。", "why_asked": "GCPは標準で保存時・転送時のデータを暗号化するが、使用中（メモリで処理されている最中）のデータはその対象外という点は見落としやすい。3つの状態（at-rest／in-transit／in-use）の区別が問われる。", "kid": "ディスクに保存されているときや通信中のデータは標準で暗号化されるが、メモリ上でまさに処理されている最中のデータまで守るには、専用の仕組み（Confidential VM）が要る、という話。", "eg": "金庫に入っているとき（保存時）や輸送中（転送時）は安全でも、机の上で中身を数えている最中（処理中）は無防備になりがち。その処理中の瞬間まで覆いをかけて守るイメージ。"}, "m7q13": {"point": "「起動時のルートキット・ブートレベルの改ざんを検証・監視したい」に反応したら、Shielded VM（セキュアブート・vTPM・整合性監視）。", "why_asked": "ファイアウォールやアンチウイルスといった一般的なセキュリティ対策と、ブートの完全性検証はレイヤーが異なる。ACEでは「どの層を守る対策か」を混同しないことが問われる。", "kid": "OSが起動する一番最初の段階が改ざんされていないかをチェックし、怪しければ検知する仕組み、という話。ネットワークやアプリの対策とは別の、もっと根っこの層を守る。", "eg": "建物のセキュリティで、出入口の警備（ファイアウォール）や各部屋の見回り（アンチウイルス）とは別に、建物の土台そのものに夜中に細工されていないかをチェックする専門の検査官を置く、というイメージ。"}, "m7q14": {"point": "「基盤メンテナンス中もVMを止めたくない」に反応したら、ホストメンテナンスポリシーをライブマイグレーション（MIGRATE）に設定。", "why_asked": "TERMINATEとMIGRATEの設定を混同しやすい。またプリエンプティブルVMはMIGRATE設定にできず、メンテナンス時は必ず停止（中断）される点も要注意。", "kid": "Googleが物理サーバーの点検をするとき、VMを止めずに別のサーバーへそっと移してくれる設定にしておく、という話。", "eg": "ビルの改修工事の間、住人を無理に退去させず、別の部屋へそっと引っ越しさせて生活を続けさせる、というイメージ。"}, "m7q15": {"point": "「署名・承認された信頼できるイメージだけをデプロイ許可し、未承認イメージはブロックしたい」に反応したら、Binary Authorization。", "why_asked": "レジストリを非公開にすること（誰がイメージを取得できるか）と、Binary Authorization（デプロイ時に何を許可するか）は別レイヤーの制御であり、混同しやすい。", "kid": "デプロイしようとしているコンテナイメージが、あらかじめ検証・署名された信頼できるものかどうかを、デプロイの入口でチェックして未承認のものを弾く仕組み、という話。", "eg": "工場の搬入口で、検品済みの認証シールが貼られた部品しか中に入れてもらえないルールを敷くイメージ。人の目視チェック任せだと見落としが出る。"}, "m7q16": {"point": "「同一クラスタ内で特定NamespaceのPodだけ特定Podに通信でき、それ以外は遮断したい」に反応したら、NetworkPolicy。", "why_asked": "PodのIPは動的に変わるため、IPベースのVPCファイアウォールはPod間通信の制御に向かない。Kubernetesネイティブな制御手段を選べるかが問われる。", "kid": "Podの世界の中で「どのグループがどのグループと話せるか」をラベルで指定するルール、という話。何も設定しなければ全Pod間の通信は最初から自由に通ってしまう。", "eg": "オフィスの中で、特定の部署の人だけが特定の部屋に入れる入退室ルールを設けるイメージ。建物の外に立つ守衛（VPCファイアウォール）では、部屋ごとの細かい出入り制御はできない。"}, "m7q17": {"point": "「本番で頻繁な最新版より安定性重視」に反応したら、リリースチャンネルをStable（安定版）に設定。", "why_asked": "Rapid／Regular／Stableの検証度合いの違いを理解しないと、本番に不向きなRapidを選んでしまう。安定性の話とアップグレード放置（セキュリティリスク）の話を混同しないことも問われる。", "kid": "新しいバージョンほど世に出て日が浅く検証が薄い一方、古いバージョンほど十分にテストされている、という関係を踏まえて、本番では一番検証された安定版を選ぶ、という話。", "eg": "出たばかりの新製品（Rapid）はまだ不具合が見つかっていないだけかもしれないが、長く使われて評判の固まった定番品（Stable）なら安心して使える、というイメージ。"}, "m7q18": {"point": "「特定ノードを特定ワークロード専用にし、一般Podを排除したい」に反応したら、taint（ノード側の忌避マーク）＋toleration（Pod側の許容設定）。", "why_asked": "何も指定しなければスケジューラは空きリソースのあるノードに自由にPodを配置するため、高価なGPUノードを専用化するには明示的な排他制御が必要という点が問われる。", "kid": "ノードに「特別な許可がないと入れません」という札を立てておき、専用にしたいPodにだけその許可を持たせる仕組み、という話。", "eg": "立入禁止の札（taint）を貼った部屋に、特別な通行証（toleration）を持つ人だけが入れるようにする、というイメージ。"}, "m7q19": {"point": "「自動アップグレード・メンテナンスを深夜帯だけに実施したい」に反応したら、メンテナンスウィンドウを深夜帯に設定。", "why_asked": "アップグレードを止めることと、実施の時間帯をずらすことは別問題。前者はセキュリティ更新を逃すリスクを生むが、後者は業務影響を減らしつつ更新も受けられる点の区別が問われる。", "kid": "アップグレード自体は止めず、実施してよい時間帯だけを指定する、という話。", "eg": "店の改装工事を、営業時間中ではなく客の少ない深夜に行うよう時間指定するイメージ。工事自体をやめるわけではない。"}, "m7q20": {"point": "「各レプリカに安定したネットワークIDと専用の永続ストレージが必要」に反応したら、StatefulSet＋PersistentVolumeClaim。", "why_asked": "Deploymentはステートレス前提でPodが使い捨て・入れ替え可能なため、分散DBのように「どのPodがどのデータを持つか」が重要なワークロードには不向きという区別が問われる。", "kid": "分散データベースのように、各レプリカが自分専用のデータと自分だけの安定した名前を持ち続ける必要があるアプリには、専用のリソース（StatefulSet）を使う、という話。", "eg": "自由席（Deployment）は毎回どこに座ってもよいが、指定席（StatefulSet）は毎回同じ座席番号と自分専用の荷物置き場が必要、というイメージ。"}, "m7q21": {"point": "「オブジェクト単位のACLではなくIAMに一本化してシンプルかつ安全に」に反応したら、均一なバケットレベルアクセス（UBLA）。", "why_asked": "古いACLベースの管理とIAMベースの管理が併存すると権限の見通しが悪くなり、意図しない公開などの事故のもとになる。GCPが推奨する一本化の方向性を理解しているかが問われる。", "kid": "オブジェクトごとにバラバラの権限をつけるのをやめて、バケット全体をIAMだけで管理できるようにする設定、という話。", "eg": "部屋ごとに違う鍵（ACL）を配って管理するのをやめ、建物全体を1つの入退室システム（IAM）で統一管理するようにするイメージ。"}, "m7q22": {"point": "「リージョン障害時のデータ損失（RPO）を最小化したい低RPOの地理冗長」に反応したら、デュアルリージョン＋ターボレプリケーション。", "why_asked": "単一リージョンバケットはそのリージョンが使えなくなるとデータにアクセスできなくなるリスクがある。地理冗長構成の中でも、RPOを短縮する追加機能（ターボレプリケーション）の存在を知っているかが問われる。", "kid": "2つの離れた場所に同時にデータを持たせ、しかもその複製をできるだけ速く行うことで、片方が被災してもデータの取りこぼしを最小限にする、という話。", "eg": "大事な書類を1箇所の金庫に保管するだけでなく、離れた場所の金庫にもすぐコピーを届けておけば、片方が被災してももう片方に最新の書類が残っている、というイメージ。"}, "m7q23": {"point": "「アクセス頻度が予測しづらい、ライフサイクル設計の手間を省いて自動最適化したい」に反応したら、Autoclass。", "why_asked": "ライフサイクルルールは条件を手動で設計・維持する必要があるが、アクセスパターンが読めない場合はその設計自体が難しい。Autoclassが実際のアクセス状況を見て自動でクラス遷移を行う点との違いが問われる。", "kid": "よく使われているか、あまり使われていないかをシステム自身が判断して、ストレージクラスを自動で移動させてくれる機能、という話。", "eg": "よく手に取る商品は手前の棚に、あまり売れない商品は奥の倉庫に、店員が売れ行きを見ながら自動的に並べ替えてくれる、というイメージ。"}, "m7q24": {"point": "「ダウンロード費用を利用する側（リクエスター）に負担させたい」に反応したら、Requester Pays。", "why_asked": "何も設定しないとegress（データ転送）費用はバケット所有者が負担し続ける。公開データセットを大勢に配布する場面で、費用負担先を変えられる機能を知っているかが問われる。", "kid": "データを見に来た人・ダウンロードする人に、その分の送料を負担してもらう設定、という話。", "eg": "資料を届けるときの送料を、送る側ではなく受け取る側に払ってもらうようにするイメージ。大勢に配る場合、提供側の費用を抑えられる。"}, "m7q25": {"point": "「大量の小さいファイルをできるだけ高速にアップロードしたい」に反応したら、並列転送（gcloud storage cp／gsutil -m）。", "why_asked": "1件ずつ順番に送る方式は、ファイル数が多いほど所要時間がほぼ線形に伸びてしまう。並列化によって同時に複数の転送を行い、全体の時間を短縮できる仕組みを知っているかが問われる。", "kid": "ファイルを1つずつ順番に送るのではなく、同時にいくつも並行して送ることで、全体の時間を短くする、という話。", "eg": "大量の荷物を1人で1つずつ運ぶより、何人かで同時に手分けして運んだ方が早く終わる、というイメージ。"}, "m7q26": {"point": "「レイテンシより料金優先、専用バックボーンを使わない安価な経路にしたい」に反応したら、ネットワークサービスティアのStandard Tier。", "why_asked": "Premium Tierがデフォルトのため、コスト重視の要件が出たときに意図的にStandard Tierへ切り替える必要があると気づけるかが問われる。CDNの有効/無効や外部IPの設定とティア選択を混同しないことも重要。", "kid": "Googleの専用の高速な道（バックボーン）を通る高品質だが割高な経路（Premium）と、一般のインターネット経由で安いが品質の劣る経路（Standard）のどちらを使うか選べる、という話。", "eg": "荷物を速くて高い専用便で送るか、時間はかかるが安い普通便で送るかを選ぶイメージ。速さより値段を優先するなら普通便を選ぶ。"}, "m7q28": {"point": "「組織全体で、各プロジェクトに依存せず基本ルールを一元的に強制したい」に反応したら、階層型ファイアウォールポリシーを組織/フォルダレベルで適用。", "why_asked": "各プロジェクトごとにVPCファイアウォールを個別設定する方式は、設定のばらつきや設定漏れが起きやすい。組織階層の上位で一括強制できる仕組みを知っているかが問われる。", "kid": "各プロジェクトに1つずつルールを設定して回るのではなく、組織やフォルダという上位のレベルで1回ルールを決めれば、配下の全プロジェクトに自動的に効くようにする、という話。", "eg": "会社の規則を各支店にそれぞれ個別に伝えて回るのではなく、本社が決めた規則が全支店に自動的に適用される仕組みを作る、というイメージ。"}, "m7q29": {"point": "「特定の宛先IPレンジ宛だけをアプライアンスVM経由にしたい」に反応したら、カスタム静的ルート＋次ホップにアプライアンスVMを指定。", "why_asked": "経路制御はデフォルトルートの削除やDNS設定と混同されやすいが、実際には宛先IPレンジと次ホップを指定するルーティングの機能で実現する、という点が問われる。", "kid": "特定の行き先へ向かう通信だけ、決まった中継地点（アプライアンスVM）を必ず通るように道順を指定する、という話。", "eg": "特定の届け先への荷物だけ、必ず検問所を通るルートをあらかじめ地図に書き込んでおく、というイメージ。"}, "m7q30": {"point": "「VPC内部限定でHTTP(S)を負荷分散、外部には公開しない」に反応したら、内部HTTP(S)ロードバランサ（リージョナル内部ALB）。", "why_asked": "外部HTTP(S)ロードバランサはインターネットに公開されるため、内部限定の要件とは正反対になる。ロードバランサの種類（L4/L7、内部/外部）を混同しないことが問われる。", "kid": "マイクロサービス同士の通信をVPCの中だけで振り分けたいので、外部に公開されないタイプの負荷分散を使う、という話。", "eg": "社内便の仕分けを、社外の人からも見える窓口ではなく、社内専用の仕分け係に任せる、というイメージ。"}, "m7q32": {"point": "「多様なイベントソースを統一的に受け取ってCloud Runを起動したい」に反応したら、Eventarc。", "why_asked": "イベントソースごとに個別のポーリングや連携を作ると管理が煩雑になる。多様なイベントを標準形式（CloudEvents）で統一的にルーティングする仕組みを知っているかが問われる。", "kid": "いろいろな場所から届くイベントの通知を、1つの窓口が受け取ってCloud Runに渡してくれる、という話。", "eg": "いろいろな部署からの連絡を、それぞれ別々の担当者が個別に対応するのではなく、共通の受付が一括で受けて担当に振り分ける、というイメージ。"}, "m7q35": {"point": "「1インスタンス1リクエストでコストが高い、複数リクエストを同時処理させたい」に反応したら、同時実行数（concurrency）を引き上げる。", "why_asked": "concurrencyの意味（1インスタンスが同時に処理できるリクエスト数）を理解していないと、逆に値を下げてしまいインスタンス数を増やす方向に動いてしまう。値を上げると同じトラフィックを少ないインスタンスで処理できコストが下がる、という因果が問われる。", "kid": "1台の窓口に1人しか対応させないと窓口の数を増やすしかなくなるので、1台で複数人を同時に対応できるようにして窓口の数を減らす、という話。", "eg": "1台のレジで1人ずつしか会計できないと行列が伸びてレジを増やすしかないが、1台で複数人を同時に処理できれば必要なレジの台数が減る、というイメージ。"}, "m7q36": {"point": "「急なトラフィックで大量起動、下流DBへの過負荷を防ぎたい」に反応したら、最大インスタンス数（max instances）を設定。", "why_asked": "最小インスタンス数（待機用の下限）と最大インスタンス数（上限のスロットリング）を混同しやすい。上限を設定しないと無制限にインスタンスが増え、下流リソースを壊しうる点が問われる。", "kid": "関数が同時に起動できる数に天井を決めておくことで、後ろにあるデータベースが処理しきれなくなるのを防ぐ、という話。", "eg": "レジを無制限に増やして客をどんどん通すと、裏の在庫係（データベース）がさばき切れなくなるので、レジの台数に上限を決めておく、というイメージ。"}, "m7q37": {"point": "「デバッグログが大量で取り込みコストが高い、不要ログを削りたい」に反応したら、ログルーターの除外フィルタ（exclusion filter）。", "why_asked": "全ログを長期保存し続けるとコストが増える一方、ログを完全に止めると障害調査ができなくなる。両極端を避け、不要な部分だけを取り込み時点で除外する調整弁の存在が問われる。", "kid": "全部のログをいったん受け取ってから捨てるのではなく、最初から要らない種類のログは受け取らないようにして、取り込みコスト自体を減らす、という話。", "eg": "郵便受けに届くチラシを全部保管すると場所も費用もかかるので、要らない種類のチラシは最初から受け取らないようにする、というイメージ。"}, "m7q38": {"point": "「組織配下の全プロジェクトのログを、個別設定なしに1箇所へ集約したい」に反応したら、集約シンク（aggregated sink）を組織/フォルダレベルで作成。", "why_asked": "各プロジェクトごとにシンクを設定する方式は、新規プロジェクトが増えるたびに設定漏れが起きうる。上位階層で1回設定すれば配下全体（新規プロジェクト含む）に自動的に効く点が問われる。", "kid": "各プロジェクトを回ってログの転送設定をするのではなく、組織やフォルダという上のレベルで1回だけ設定すれば、配下の全プロジェクトのログがまとめて集まる、という話。", "eg": "各支店の日報を1件ずつ集配してもらうよう頼んで回るのではなく、本社が「配下の支店全部の日報を自動で集める」ルールを1回作っておく、というイメージ。"}, "m7q39": {"point": "「可用性目標に対して継続測定し、消費しすぎたらアラートしたい」に反応したら、Cloud MonitoringのSLO機能でエラーバジェットのバーンレートアラート。", "why_asked": "死活監視（アップタイムチェック）は「動いているか止まっているか」しか見ないが、SLOは目標に対する信頼性の余裕（エラーバジェット）を管理する点で役割が異なる。この違いを混同しないことが問われる。", "kid": "「これくらいまでは失敗してもよい」という許容量（エラーバジェット）を決めておき、その使われ方が速すぎたら警報を出す仕組み、という話。単に動いているかどうかだけを見る監視とは違う。", "eg": "お小遣いの使える上限を決めておき、使うペースが速すぎたら「このままだと今月中に使い切ってしまう」と警告してくれる家計簿アプリのようなイメージ。"}, "m7q40": {"point": "「どの関数がCPU・メモリを消費しているか本番で継続的に把握したい」に反応したら、Cloud Profiler。", "why_asked": "Cloud Trace（レイテンシ・分散トレース）、Error Reporting（エラー集約）、アップタイムチェック（死活監視）と役割の異なる複数のCloud Monitoring系サービスの中から、リソース消費の特定という目的に合うものを選べるかが問われる。", "kid": "アプリのどの処理が多くのCPUやメモリを使っているかを、動かしたまま継続的に記録・可視化してくれる仕組み、という話。", "eg": "体のどの部分が疲れやすいかを、日々の健康診断で継続的に記録して把握するようなイメージ。遅さを見る検査（Trace）やエラーを見る検査（Error Reporting）とは違う項目を見ている。"}, "m7q41": {"point": "「監査ログをほぼリアルタイムで外部SIEMへストリーミング連携したい」に反応したら、ログシンクの宛先をPub/Subにする。", "why_asked": "BigQueryへのエクスポートはクエリ分析向けでバッチ的な扱いになりやすく、リアルタイム性が求められるセキュリティ監視の要件には合わない。宛先の種類ごとの向き不向きが問われる。", "kid": "ログが発生した瞬間にすぐ配信できる仕組み（Pub/Sub）を経由させることで、外部のセキュリティ監視システムがほぼ即座に受け取れるようにする、という話。", "eg": "ニュースを翌日の新聞（BigQueryのバッチ処理）で知るのではなく、生放送（Pub/Sub）でその場で受け取るようなイメージ。"}, "m7q45": {"point": "「同一エンティティのメッセージを送信順に受信させたい」に反応したら、順序指定キー（ordering key）＋サブスクリプションの順序保証を有効化。", "why_asked": "Pub/Subは基本的にメッセージの配信順序を保証しない分散メッセージングサービスであるため、順序が必要な場面では明示的にこの仕組みを使う必要がある、という前提を理解しているかが問われる。", "kid": "同じ相手宛てのメッセージに通し番号のようなキーを付けておくと、その相手宛てのメッセージだけは送った順番どおりに届く、という話。", "eg": "同じ人に送る何通もの手紙に通し番号を振っておけば、その人への手紙だけは順番どおりに届けてもらえる、というイメージ。"}, "m7q46": {"point": "「同じメッセージが何度失敗しても再配信され続けてシステムを圧迫」に反応したら、デッドレタートピック。", "why_asked": "何度処理しても失敗するメッセージ（毒メッセージ）を放置すると再配信が延々と続き、システムのリソースを消費し続ける。規定回数の失敗で別の場所へ退避させる仕組みを知っているかが問われる。", "kid": "何度処理しても失敗するメッセージを、いつまでも配り直すのではなく、別の保管場所に移して他の正常な処理を邪魔しないようにする、という話。", "eg": "何度届けても受け取ってもらえない荷物を、配達員がいつまでも持ち歩くのではなく、専用の保留棚に置いて次の配達に進む、というイメージ。"}, "m7q47": {"point": "「同じ構成のパイプラインを、開発環境やコードなしに運用担当がパラメータ指定で繰り返し起動したい」に反応したら、Dataflowテンプレート。", "why_asked": "毎回開発者がコードからデプロイする運用は属人化しやすい。パイプラインをパッケージ化してパラメータだけで再利用できる仕組みを知っているかが問われる。", "kid": "パイプラインの中身をあらかじめ完成させて型（テンプレート）にしておけば、開発の知識がない人でも数値や設定を入れるだけで同じ処理を繰り返し実行できる、という話。", "eg": "料理のレシピをキット化しておけば、シェフがいなくてもスタッフが材料を入れるだけで同じ料理を作れる、というイメージ。"}, "m7q49": {"point": "「コマンドラインでプロジェクト作成し、既存の請求先に紐付けてすぐ使えるようにしたい」に反応したら、gcloud projects create → gcloud billing projects linkの2手順。", "why_asked": "プロジェクトを作成しただけでは請求先アカウントに紐付いておらず、多くの有償リソースが作成できない。作成と請求リンクが別々のコマンド・別々の手順である点が問われる。", "kid": "新しい入れ物（プロジェクト）を作るコマンドと、その入れ物の支払い方法（請求先アカウント）を紐付けるコマンドの、2つを順番に実行する必要がある、という話。", "eg": "新しい部署を立ち上げても、経費の引き落とし口座を紐付けないと活動費が使えないのと同じで、プロジェクト作成のあとに請求先を紐付ける手順が要る、というイメージ。"}, "m7q50": {"point": "「コミットをきっかけにビルド・テスト・デプロイを自動実行、サーバー管理はしたくない」に反応したら、Cloud Buildのトリガー。", "why_asked": "自前でCIサーバーを構築・運用する選択肢と比べ、Cloud Buildはサーバー管理不要のマネージドサービスである点が問われる。BigQueryのような分析用サービスとの無関係な混同を避けられるかも見られる。", "kid": "コードをリポジトリに置いた（コミットした）瞬間に、ビルド・テスト・デプロイを自動でやってくれるサービスで、自分でサーバーを立てて管理する必要がない、という話。", "eg": "材料を置いた瞬間に組み立て・検査・出荷までを全自動でやってくれる工場のようなイメージ。自分で工場（CIサーバー）を建てて維持する手間がいらない。"}}'::jsonb) AS v(key, value)
WHERE q.source_ref = v.key
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'gcp-ace')
  AND q.explanation_data IS NOT NULL;

-- 2) explanation_dataがNULLだった57問に、9キーのフル構造を直接代入
--    (||マージはNULLを吸収するため使えない。question-authoring-gcp-aceスキルの注意通り)
UPDATE public.questions q
SET explanation_data = v.value
FROM (VALUES
  ('m2q11', '{"asked": "大量センサーからのストリーミングデータを、高可用かつ障害に強いデータレイクとして受け止めるには、どのサービスをどの順番で組み合わせるべきかを問うている。", "point": "ストリーミングの受け口はPub/Sub、変換はDataflow、生データの置き場はCloud Storageという3段構成なら正解。", "why_asked": "ACEでは「ストリーミング取り込み」と「バッチ転送」を扱うサービスの向き不向きを混同しやすい。Storage Transfer ServiceやDataprepの守備範囲を正しく知っているかが問われる。", "kid": "大量のセンサーから届く水（データ）を、まず貯水池（Pub/Sub）でいったん受け止めてあふれないようにし、そこから浄水場（Dataflow）で整えて、最終的に大きな倉庫（Cloud Storage）にしまうイメージ。", "eg": "工場のベルトコンベアに例えると、まず荷物を一時的に受け止めるバッファ台（Pub/Sub）があり、そこで仕分け・加工する作業員（Dataflow）を経て、完成品を倉庫（Cloud Storage）に運び込むという流れ。", "terms": [["Pub/Sub", "メッセージを一時的にためて配信するサービス。送信側と受信側の速度差を吸収するバッファの役割"], ["Dataflow", "データを受け取りながら変換・加工するストリーミング/バッチ処理サービス"], ["データレイク", "形式を問わず生データをそのまま貯めておく保管場所。Cloud Storageがよく使われる"], ["Storage Transfer Service", "既存のファイルをまとめて一括コピーするバッチ転送専用サービス。リアルタイムのストリーミングには使えない"]], "think": "「常時ストリーミングされてくる大量データを取りこぼさず受け止める」がまず最初の関門。ここで使うのがPub/Sub。Pub/Subはメッセージを一時的にためておけるので、送信側（センサー）が大量に送っても受信側の処理が追いつくまでバッファとして吸収でき、これが「回復性」の正体。次に、そのデータを実際にストレージへ書き込む変換処理が要る。ここを担うのがDataflowで、Pub/Subからデータを読み取りながらCloud Storageへ書き込む。最後に、データレイクは構造化・非構造化を問わず生データをそのまま置いておく場所である必要があるため、オブジェクトストレージであるCloud Storageが受け皿になる。この3段階（Pub/Sub→Dataflow→Cloud Storage）が揃って初めて「高可用・回復性の高いデータレイク」が成立する。", "vs": "Storage Transfer Serviceは、すでにあるファイルの集合をまとめてコピーするバッチ転送用で、センサーからのリアルタイムストリーミングは受け付けられない。BigQueryはデータレイクではなく分析用のデータウェアハウスなので、生データをそのまま置く用途には合わない。Bigtableは大量の書き込みに強いが、今回問われている「データレイク（生データの保管）」の文脈ではCloud Storageが標準の置き場になる。", "opt": ["正解。Pub/Subで受け止めてバッファリングし、Dataflowで変換してCloud Storageに書き込む、王道のストリーミング取り込み構成。", "Storage Transfer Serviceはバッチのファイルコピー専用で、Pub/Subからのストリーミングデータをリアルタイムで受け取ることはできない。", "Dataprep by Trifactaはノーコードのデータ前処理ツールであり、Bigtableへの書き込みパイプラインとしては不自然な組み合わせで、データレイクの生データ保管先としても不向き。", "Storage Transfer Serviceはストリーミングデータの受け口にはならず、DataflowとBigQueryの組み合わせもストリーミングの取り込み経路としては成立しない。"]}'::jsonb),
  ('m2q12', '{"asked": "サブネットのIPが足りなくなったとき、VMに使えるIPアドレスを増やすにはどうすればよいかを問うている。", "point": "CIDRのプレフィックス数字は小さいほど使えるIP数が多い。プライマリ範囲を拡張したいなら数字を小さくする方向に変更する。", "why_asked": "CIDR表記の「数字が大きい＝範囲が狭い」という感覚を逆に覚えている人が多く、拡張・縮小のどちら向きに変更すべきかで間違えやすい。またセカンダリIP範囲とプライマリIP範囲の用途の違いも狙われる。", "kid": "サブネットのIP範囲は「住所帳の大きさ」のようなもの。数字（/20など）が小さいほど住所帳のページが増えて、たくさんの住所（IP）を書き込める。", "eg": "マンションの部屋番号に例えると、/20は「小さいマンション」、/18は「もっと部屋数の多い大きいマンション」。部屋（VM）を増やしたいなら、大きいマンションに建て替える（/18に変更）必要がある。", "terms": [["CIDR", "IPアドレスの範囲を「/数字」で表す書き方。数字が小さいほど範囲（使えるIP数）は広い"], ["プライマリ内部IP範囲", "サブネット内のVMそのものに割り当てられる基本のIPアドレス範囲"], ["セカンダリIP範囲", "GKEのPodやServiceなど、VM本体とは別の用途向けに追加で確保するIP範囲（エイリアスIP）"]], "think": "サブネットのプライマリ範囲が枯渇しているので、まず「セカンダリIP範囲を足す」で解決するかを考える。セカンダリIP範囲はGKEのPodやServiceにエイリアスIPとして割り当てるための追加範囲であり、VM本体のプライマリIPの不足を補う用途ではないため、この案では解決しない。次に、プライマリ範囲そのものを広げる方法を考える。CIDRは/の後ろの数字が小さいほど広い範囲を表すので、/20（4096個）から数字を小さくして/18（16384個）に変更すればIP数は4倍に増える。逆に/22に変更すると数字が大きくなり範囲はさらに狭くなるため逆効果。GCPのサブネットのIP範囲は拡張はできるが縮小はできない制約があるため、/18への変更が唯一実行可能かつ目的に合う操作になる。", "vs": "セカンダリIP範囲はVM本体のIP不足の解決にはならず、あくまでPod/Service用の別枠。IP範囲の変更は「広げる」方向にしか行えず、「狭める」方向の変更（/20→/22）はそもそも実行できない。IPv6への変換はネットワーク構成の大掛かりな変更であり、今回の「サブネットのIP不足を素早く解消する」という目的には過剰かつ不要。", "opt": ["セカンダリIP範囲はGKEのPod/ServiceなどエイリアスIP用の追加範囲で、VM本体のプライマリIP不足を解決する手段にはならない。", "正解。CIDRは数字が小さいほど範囲が広い。/20から/18に変更することでプライマリ範囲のIP数を4倍に増やせる。", "/22は/20より数字が大きく、むしろ範囲が狭くなる方向の変更でIP不足を悪化させてしまう。", "IPv6への変換はネットワーク全体に影響する大掛かりな変更で、サブネットのIP不足という局所的な問題の解決策としては不釣り合い。"]}'::jsonb),
  ('m2q14', '{"asked": "オンプレミスの新しいファイルをCloud Storageへ自動的にアップロードし続けるには、どの仕組みを選ぶべきかを問うている。", "point": "定期的にファイルをまとめて同期し続けたいなら、gcloud storageコマンドの同期処理をcronで定期実行する方法が最短で確実。", "why_asked": "Pub/Subはメッセージング（イベント通知）のサービスであり、大容量ファイルそのものを運ぶ用途ではないことを混同しやすい。「自動化」と聞いてすぐPub/SubやCloud Functionsに飛びつく癖が狙われている。", "kid": "新しく届いた画像を、決まった時間ごとに「まとめて運ぶ配達係」を用意するイメージ。配達係の指示書がcronジョブ、実際に運ぶ道具がgcloud storageコマンド。", "eg": "郵便局の配達に例えると、荷物（画像ファイル）を一件ずつ知らせる伝言（Pub/Subのメッセージ）ではなく、決まった時間に集荷トラックが巡回して荷物をまとめて運ぶ（cronでの定期同期）方式。", "terms": [["gcloud storage", "Cloud Storageのバケットとファイルをコマンドラインで操作するツール。ローカルとバケットの同期（rsync相当）ができる"], ["cronジョブ", "決まった時刻・間隔でコマンドを自動実行する、Linuxの定期実行の仕組み"], ["Pub/Sub", "「何かが起きた」という通知（メッセージ）をやり取りする仕組みで、ファイルの中身そのものを転送する用途ではない"]], "think": "「新しい画像を自動アップロードする」という要件を満たすには、まずファイルの実体をオンプレからCloud Storageへ運ぶ手段が要る。Pub/Subはメッセージ（通知）をやり取りする仕組みであり、画像ファイルそのものの転送には向いていない。医療画像のような大容量ファイルを流す通り道としては不適切。一方gcloud storageコマンドはローカルフォルダとバケットの内容を同期でき、新しく増えたファイルだけを検知してアップロードする動きが作れる。これをcronで一定間隔ごとに自動実行すれば、人手を介さず「新しい画像が来たら自動でアップロード」が実現できる。コンソールからの手動アップロードは自動化の要件そのものに反するため候補から外れる。", "vs": "Pub/Subトピック＋Cloud Storageトリガーという仕組みは「Cloud Storageに何かアップロードされたら通知する」出口側の仕組みであり、今回のようにオンプレからCloud Storageへ入れる入口側の課題には使えない。Cloud Functionsとの組み合わせも同様に、ファイル転送そのものを担うサービスではない。", "opt": ["Pub/Subはメッセージ通知の仕組みで、医療画像のような大容量ファイルの転送手段としては不向き。", "正解。gcloud storageコマンドでの同期処理をcronで定期実行すれば、新しいファイルだけを自動でアップロードし続けられる。", "Pub/Subとの組み合わせは通知の仕組みであり、大容量画像ファイルを直接運ぶ経路にはならない。", "コンソールからの手動アップロードは人手が必要で、「自動アップロード」という要件を満たさない。"]}'::jsonb),
  ('m2q18', '{"asked": "ドメイン外のユーザーを排除しつつ今後同じ監査作業を発生させないためには、組織ポリシーと既存ユーザーへの対応をどう組み合わせるべきかを問うている。", "point": "組織ポリシーは「これから先」の新規操作にしか効かない。既存の違反ユーザーはポリシーを設定しただけでは消えず、事後的に手動で削除する必要がある。", "why_asked": "組織ポリシーが自動的に既存リソース・既存メンバーへ遡って適用されると誤解しやすい。ACEでは「ポリシーは未来の操作を制限するガードレールであり、過去の状態は変えない」という理解が繰り返し問われる。", "kid": "組織ポリシーは「これから先、ドメイン外の人を新しく入れないでね」という看板を立てるようなもの。すでに中に入っている人を勝手に追い出してはくれない。", "eg": "会社の受付に「今後は社員証がない人は入館禁止」という看板を立てても、すでに社内にいる部外者が自動的に追い出されるわけではなく、別途見回って退去してもらう必要があるのと同じ。", "terms": [["組織ポリシー", "組織・フォルダ・プロジェクト単位で「今後どんな操作を許可・禁止するか」を定めるガードレール。既存の状態には遡って作用しない"], ["ドメイン制限", "組織ポリシー(iam.allowedPolicyMemberDomains等)で、指定したドメイン以外のアカウントをIAMに追加できないようにする制限"]], "think": "目的は2つに分けられる。「今後、ドメイン外のユーザーが増えないようにする」ことと、「今すでにいるドメイン外のユーザーを消す」ことだ。前者は組織ポリシーでドメイン制限をかければ、以降の新規追加操作がブロックされるので実現できる。しかし組織ポリシーはこれから行われる操作にのみ適用される仕組みであり、ポリシーを設定した瞬間に過去からいるユーザーが自動的に削除されることはない。したがって、既にドメイン外として見つかっているユーザーについては、ポリシー設定とは別に、事後的に（手動またはスクリプトで）洗い出して削除する作業が必要になる。「ポリシー設定」と「既存違反の事後削除」という2段構えでなければ、今回の「削除し、かつ今後の監査を不要にしたい」という要件は満たせない。", "vs": "「自動的に削除する」という案は、組織ポリシーにそのような自動削除の仕組みは存在しないため誤り。Cloud Schedulerで定期的にスキャン・削除する方法は動くには動くが、組織ポリシーで今後の発生自体を防げるなら継続的な監視ジョブを維持する手間は不要になり、より遠回り。", "opt": ["Cloud Schedulerでの定期スキャン方式は動作はするが、組織ポリシーで今後の発生自体を防げれば継続的な監視の手間は不要になる、より遠回りな方法。", "対象がプロジェクトかリソースかの違いだけで、定期スキャン方式である点は同じく遠回り。", "組織ポリシーには既存の違反ユーザーを自動的に削除する機能はなく、ポリシーは今後の新規操作にしか効かない。", "正解。組織ポリシーでドメイン制限をかけて今後の追加を防ぎつつ、既にいる違反ユーザーは事後的に手動で削除する2段構えが必要。"]}'::jsonb),
  ('m2q2', '{"asked": "複数のプロジェクトにまたがって「米国内でしかリソースを作れない」という制限を一括でかけるには、どの仕組みをどう組み合わせるべきかを問うている。", "point": "場所の制限は組織ポリシーの仕事。複数プロジェクトへまとめて適用したいならフォルダにまとめてポリシーを継承させる。", "why_asked": "「アクセス制限」と聞くとIAMを連想しがちだが、IAMは「誰が何をできるか」の制御であり「どこに作れるか」という場所の制御はできない。この住み分けの理解がACEで繰り返し狙われる。", "kid": "どこにリソースを置いていいかを決める看板は組織ポリシー、誰が何をしていいかを決める名簿はIAM。今回は「置き場所」の話なので看板（組織ポリシー）の出番。", "eg": "会社の備品を「日本国内の倉庫にしか置いてはいけない」と決めるルールは、社員の権限表（IAM）ではなく、会社全体の運用規定（組織ポリシー）に書くもの。複数の部署（プロジェクト）にまとめて適用したいなら、それらをまとめる部門（フォルダ）単位で規定を出す。", "terms": [["組織ポリシー", "リソースの作成場所や振る舞いに制約をかけるガードレール。IAMとは別の仕組みで「どこに」「どのように」を制御する"], ["IAM", "「誰が」「何に対して」「何をできるか」という権限を制御する仕組み。場所の制限はできない"], ["フォルダ", "複数のプロジェクトをまとめるGCPの階層単位。フォルダにポリシーを設定すると配下の全プロジェクトに継承される"]], "think": "まず制限したい対象が「場所」であることに注目する。GCPでは「どこにリソースを作れるか」を制御するのはIAMではなく組織ポリシー（resourceLocations制約）の役割であり、IAMはあくまで「誰が何をできるか」という権限の制御にとどまる。したがってIAMポリシーで場所を制限するという発想自体が成立しない。次に「複数の開発プロジェクトに一括で」という要件を考えると、プロジェクトを1つずつポリシー設定するのは手間がかかる。GCPの階層構造では、フォルダに設定したポリシーは配下の全プロジェクトに自動的に継承されるため、対象プロジェクトをまとめてフォルダに入れ、そのフォルダに米国ロケーション制限の組織ポリシーを設定すれば、1回の設定で全プロジェクトに反映できる。", "vs": "IAMポリシーは「誰が」「何を」操作できるかを制御するものであり、「どこに」作成できるかという場所の制約はそもそもIAMの機能に存在しない。組織全体を新規に作る案も的外れで、既存のプロジェクトをまとめる単位として必要なのは組織ではなくフォルダ。", "opt": ["正解。フォルダに開発プロジェクトをまとめ、米国ロケーションを制限する組織ポリシーをフォルダに設定すれば、配下の全プロジェクトに一括で継承される。", "組織を新たに作る必要はなく、また場所の制限はIAMポリシーでは行えない機能。", "IAMには「どこに作成できるか」という場所を制限する機能自体が存在しない。", "IAMには場所を制限する機能がなく、対象をロールに適用しても「どこに」の制御にはならない。"]}'::jsonb),
  ('m2q21', '{"asked": "Google Workspaceをすでに使っている組織が、複雑さやセキュリティ上の問題を増やさずに10倍の人数までスケールするには、ユーザー管理をどう設計すべきかを問うている。", "point": "すでにGoogle Workspaceを使っているならCloud Identityの基盤も揃っている。ユーザーをグループにまとめてロールを付与しMFAを適用する設計にしておけば、人数が増えてもグループにメンバーを追加するだけで済む。", "why_asked": "「大規模化」と聞くとActive Directoryや外部IdPとのフェデレーションといった大掛かりな仕組みを連想しがちだが、Google Workspace利用中であればすでにCloud Identityが土台として使えるため、それらは過剰であるという判断力が問われる。", "kid": "Google Workspaceを使っているということは、すでにGoogleが人を管理する仕組み（Cloud Identity）が入っているということ。人が増えても、その仕組みの「グループ」というまとめ役に人を放り込むだけで済む。", "eg": "クラス名簿に例えると、生徒（ユーザー）が増えるたびに先生（管理者）が一人ずつ座席や持ち物を設定し直すのではなく、あらかじめ「1年1組」というグループを作っておき、新入生をそのグループに入れるだけで既存のルールが自動的に適用される仕組み。", "terms": [["Cloud Identity", "Googleがユーザーアカウント・グループ・MFAなどを一元管理する基盤。Google Workspace利用時は標準で含まれている"], ["グループ", "複数のユーザーをまとめる単位。ロールをグループに付与すれば、メンバー追加だけで権限が行き渡る"], ["MFA(多要素認証)", "パスワードに加えてもう1つの確認手段（スマホの通知など）を求める、なりすまし対策の認証方式"], ["IDフェデレーション", "自社の外部IDプロバイダ（Active DirectoryやOktaなど）の認証結果をGoogleにそのまま信頼させて使う仕組み"]], "think": "すでにGoogle Workspaceを使っているという前提が最大のヒントになる。Google Workspaceの利用者はCloud Identityというユーザー・グループ管理基盤をすでに持っているため、新たに別の仕組みを導入する必要がない。人数が100人から1000人に増える場面で複雑さを増やさないためには、1人ずつ個別に権限設定するのではなく、あらかじめ役割ごとのグループを作ってそこにロールを付与しておき、新しいユーザーはそのグループに追加するだけで済む設計にしておくのが鍵になる。これなら人数が何倍に増えても管理の手間はほとんど増えない。セキュリティ面でも、Cloud Identityの機能でMFAを組織全体に一律適用しておけば、新規ユーザーにも自動的に同じ保護がかかる。すでにある基盤をそのまま使い切るのが「複雑さを増やさない」答えになる。", "vs": "Active Directoryへの移行やGoogle Workspaceとのフェデレーションは、社内に既に別のID基盤がある場合に使う仕組みであり、Google Workspace単体で完結している今回の状況には不要な複雑さを持ち込む。サードパーティIdPとのフェデレーションも同様で、外部の認証基盤を持たない前提では的外れ。", "opt": ["Active Directoryへの移行はすでにあるGoogle Workspaceの基盤を使わずに新しい複雑さを持ち込むことになり、要件の「複雑さを増やさない」に反する。", "正解。すでにあるCloud Identityでユーザーをグループに編成してロールを付与し、MFAを組織全体に適用しておけば、人数が増えてもグループへの追加だけで済む。", "IDフェデレーションは外部のIDプロバイダとGoogleの認証を連携させる仕組みで、外部IdPを持たずGoogle Workspaceだけで完結している今回の状況には不要。", "サードパーティIdPを新たに導入する話であり、既存のGoogle Workspace基盤だけで完結できる今回の要件には過剰で不要な複雑さを増やす。"]}'::jsonb),
  ('m2q23', '{"asked": "マネージドインスタンスグループで新しいインスタンスの作成が失敗したとき、原因の切り分けと解決の手順をどう進めるべきかを問うている。", "point": "インスタンステンプレートは中身を直接編集できない。作成失敗の典型原因は同名の永続ディスクが残っていることなので、正しい構文の新テンプレートを作りつつ、残っている同名ディスクを削除する。", "why_asked": "「テンプレートを修正すればいい」と考えて既存テンプレートを直接編集しようとする誤りや、テンプレート削除の可否（使用中は削除できない）を知らないと間違えやすい、実務でも遭遇するトラブルシューティングの定番パターン。", "kid": "インスタンステンプレートは一度作ったら中身を書き換えられない「印刷済みの型紙」のようなもの。間違いがあったら新しい型紙を作り直す。ディスクの名前がぶつかっていると新しいインスタンスが作れないので、ぶつかっている古いディスクは片付ける。", "eg": "同じ名前の郵便受けがすでに設置されているアパートに、新しく同じ名前の郵便受けを取り付けようとしても取り付けられないのと同じで、インスタンス名と同じ名前の永続ディスクがすでに存在していると、新しいVMがそのディスクを新規作成できずに失敗する。", "terms": [["インスタンステンプレート", "VMの構成（マシンタイプ・ディスク・ネットワークなど）をまとめた設計図。作成後は中身を編集できず、変更したい場合は新規作成して差し替える"], ["マネージドインスタンスグループ(MIG)", "同じテンプレートから複数のVMを自動的に作成・管理する仕組み"], ["永続ディスク", "VMに接続するストレージ。インスタンス名と同名のディスクがすでに存在すると、そのインスタンスの新規作成が失敗することがある"]], "think": "まず「テンプレートに問題がある」という前提を疑う必要がある。インスタンステンプレートは作成後に内容を直接編集できない仕様なので、既存テンプレートの構文を直そうとする対応はそもそも実行できない。正しい対応は、正しい構文で新しいテンプレートを作成することになる。次に、テンプレートの構文が正しくても作成が失敗するもう一つの典型原因として、インスタンス名と同じ名前の永続ディスクがすでに存在しているケースがある。GCPでは新規インスタンス作成時にブートディスクを新規作成しようとするため、同名ディスクが残っていると衝突して失敗する。したがって、新テンプレートの作成と合わせて、衝突している同名の永続ディスクを削除しておく必要がある。また、MIGが参照中の既存テンプレートはそもそも削除できない制約があるため、「先にテンプレートを削除してから作り直す」という手順は実行不可能。", "vs": "テンプレートの構文だけを確認して同名ディスクの削除に触れない対応では、ディスク名の衝突という典型原因を見落とす。逆にautoDeleteの設定だけでは、すでに存在している同名ディスクの衝突は解消されない。使用中のテンプレートを削除しようとする案は、MIGが参照している間はテンプレートを削除できないため実行できない。", "opt": ["正解。有効な構文の新テンプレートを作成しつつ、衝突の原因になっている同名の永続ディスクを削除すれば、作成失敗を解消できる。", "名前が重複しないよう新テンプレート内で気をつけるだけでは、すでに存在している同名ディスクとの衝突は解消されない。", "autoDeleteの設定はインスタンス削除時の挙動を変えるだけで、すでに残っている同名ディスクとの衝突を今すぐ解消する手段にはならない。", "MIGが参照中のテンプレートは削除できないため、先にテンプレートを削除するという手順自体が実行できない。"]}'::jsonb),
  ('m2q26', '{"asked": "一部のVM終了を許容できるフォールトトレラントなバッチ処理で、コストを大幅に下げるにはどのVM購入オプションを選び、どう検証してから導入すべきかを問うている。", "point": "「フォールトトレラント＝一部終了してもよい」ならスポットVMが最大の割引を狙える選択肢。ただし本番投入前に模擬メンテナンスイベントで中断への耐性を検証してから使う。", "why_asked": "スポットVM（旧プリエンプティブルVM）はいつでも強制終了されうる制約があるため、「終了されても困らない処理」にしか使えない。ACEでは、この適性の見極めと、事前の中断耐性テストの重要性が問われる。", "kid": "スポットVMは「いつ席を譲ってと言われるか分からない代わりに、すごく安い座席」のようなもの。荷物（バッチ処理）が「席を譲られても大丈夫」な作りになっているか、本番前に一度リハーサル（模擬メンテナンスイベント）で試しておく。", "eg": "飛行機のスタンバイチケットに例えると、正規料金の席（通常VM）より大幅に安い代わりに、満席になれば途中で席を譲らないといけない（スポットVMの強制終了）。荷物が多少遅れても平気な人（フォールトトレラントな処理）にはお得な選択肢。", "terms": [["スポットVM", "通常より大幅に安い（最大91%オフ）代わりに、Googleの都合でいつでも強制終了されうるVM。以前はプリエンプティブルVMと呼ばれていた"], ["フォールトトレラント", "一部の処理が中断・失敗しても、全体としては問題なく完遂できる（やり直しがきく）性質"], ["模擬メンテナンスイベント", "VMが強制終了されたときに実際にどう振る舞うかを、本番導入前に意図的に発生させて確認するテスト"]], "think": "コストを下げたいという要件に対し、まずVMの購入オプションの選択肢を考える。スポットVMは通常のVMより大幅に安い代わり、Googleの都合でいつ終了されるか分からないという制約がある。今回のバッチ処理は「一部のVM終了を許容できるフォールトトレラントな処理」という条件が明示されているため、この制約があっても業務に支障が出ない、つまりスポットVMの適性がある処理だと判断できる。ただし「大丈夫なはず」という推測だけで本番導入するのはリスクがあるため、実際に強制終了が起きたときの挙動を模擬メンテナンスイベントで事前に発生させ、想定通り処理が中断・再開できることを検証してから、初めて本番でスポットVMを使う。VMの世代を変える（N1からN2など）だけの対応は、性能や単価の微調整にしかならず、スポットVMほどの大幅なコスト削減にはつながらない。", "vs": "通常のN2スタンダードVMを使う案は、フォールトトレラントという条件を活かしきれておらず、コスト削減の余地を残したままになる。MIGでのテストは、今回問われている「VM終了への耐性そのもの」の検証にはならない。N1への変更のみを検討する案は、世代変更程度の限定的な効果しか見込めない。", "opt": ["正解。模擬メンテナンスイベントで中断への耐性を事前検証し、問題なければフォールトトレラントな処理の適性を活かしてスポットVMに切り替える。", "スポットVMへの切り替えを含んでおらず、通常のN2スタンダードVMのままでは大幅なコスト削減が得られない。", "MIGでのテストは今回問われているVM終了時の中断耐性の検証にはならず、目的に合わない検証方法。", "VMの世代（N1）を変えるだけでは限定的な効果しかなく、フォールトトレラントな処理という条件を活かした大幅なコスト削減にはならない。"]}'::jsonb),
  ('m2q29', '{"asked": "VMのディスクに書き込まれているアプリのログを使って問題を診断するには、どんな準備をしてからどこでログを確認すべきかを問うている。", "point": "ディスク上のログはOps Agentを入れない限りCloud Loggingには届かない。まずエージェントを導入してから、Cloud Loggingで確認する順番になる。", "why_asked": "「ログを見る＝とりあえずCloud Loggingを開く」という発想に飛びつきやすいが、VM上のログはデフォルトでは自動送信されないという前提の理解が抜けていると引っかかる。", "kid": "VMの中にあるログは、そのままではGoogleの管理画面（Cloud Logging）には届かない。届けるための「配達係」（Ops Agent）をVMに入れて初めて、外から見えるようになる。", "eg": "会社の金庫（VMのディスク）にしまってある書類を、本社のデータベース（Cloud Logging）で確認したいなら、まず金庫から書類を取り出して本社に送る配送係（Ops Agent）を雇う必要がある。配送係がいないまま本社のデータベースだけ見ても、そこには何も届いていない。", "terms": [["Ops Agent", "VMにインストールする監視・ログ収集エージェント。VM内のログやメトリクスをCloud Logging/Cloud Monitoringに送信する"], ["Cloud Logging", "GCP全体のログを集約して検索・分析できるサービス。VM内のディスクに直接アクセスするわけではなく、送られてきたログを表示する"], ["シリアルコンソール", "VMの起動時のコンソール出力を確認する仕組み。アプリケーションが独自にディスクへ書いているログの確認には使えない"]], "think": "診断したいログは「アプリがVMのディスクに書き込んでいるログ」であり、Cloud Loggingが自動的に持っている情報ではない。Cloud Loggingは、送られてきたログを集約して表示するサービスであって、VMの中を勝手に覗きに行く仕組みではないため、何もインストールしていない状態でCloud Loggingを開いても、このアプリのログは表示されない。ディスク上のログをCloud Loggingに送るには、VMにOps Agentという収集エージェントを導入し、どのファイルを監視して送るかを設定する必要がある。この設定を済ませて初めて、Cloud Loggingでログが検索・確認できるようになる。順番としては「①Ops Agentの導入・設定→②Cloud Loggingで確認」であり、①を飛ばして②だけ行っても意味がない。", "vs": "シリアルコンソールで確認できるのはVMの起動時の出力であり、アプリが独自にディスクへ書いているログとは別物なので、今回の診断には使えない。ヘルスチェックのしきい値設定は、VMの正常・異常を判定する監視の仕組みであり、ログの内容そのものを確認する手段ではない。", "opt": ["Ops Agentを導入していない状態では、ディスク上のアプリログはCloud Loggingに送られておらず、開いても何も表示されない。", "ヘルスチェックのしきい値はVMの正常判定を行う仕組みであり、ログの内容を確認してエラー原因を診断する手段にはならない。", "シリアルコンソールで見られるのはVM起動時の出力であり、アプリが独自にディスクへ書いているログとは別物。", "正解。Ops Agentをインストール・構成して初めて、ディスク上のログがCloud Loggingに送られ、そこで確認・診断できるようになる。"]}'::jsonb),
  ('m2q30', '{"asked": "新しいプロジェクトで必要な機能だけを有効化するとき、Googleが推奨するAPIの有効化方法はどれかを問うている。", "point": "使う予定のあるAPIだけを個別に有効化するのが最小権限の原則にかなった正しいやり方。", "why_asked": "「面倒だから全部有効化しておこう」という発想は攻撃対象領域（アタックサーフェス）を不必要に広げるため、ACEでは最小権限の考え方をAPI有効化の場面でも適用できるかが問われる。", "kid": "使う道具だけを工具箱から出しておくイメージ。使わない道具まで全部出しっぱなしにしておくと、誰かに勝手に使われたり、うっかり事故が起きたりするリスクが増える。", "eg": "家の合鍵に例えると、必要な部屋の鍵（使うAPI）だけを渡すのが安全で、家中すべての部屋の合鍵（全API）をとりあえず渡しておくのは、使わない部屋まで誰かに侵入されるリスクを増やすだけ。", "terms": [["API", "GCPの各サービス（Compute EngineやCloud Storageなど）を使うために有効化しておく必要がある機能の窓口"], ["最小権限の原則", "必要な範囲だけにアクセス・機能を限定し、不要な権限や機能は持たせないというセキュリティの基本方針"], ["cloudresourcemanager API", "プロジェクトやフォルダなどのリソース階層そのものを操作するためのAPI。個々のサービス機能を有効化するものではない"]], "think": "今回必要なのは、インスタンス作成（Compute Engine）、FW設定（Compute Engineのネットワーク機能に含まれる）、Cloud Storageへの保存（Cloud Storage）の3つであり、これらはcompute APIとstorage APIの2つでカバーできる。Googleが推奨する運用は、使う予定のあるAPIだけを個別に有効化する最小権限の考え方であり、使わないAPIまで有効化しておくことは、想定していない機能が使える状態を作ってしまい、セキュリティ上の攻撃対象領域を不必要に広げることになる。したがって全APIを一括で有効化する方法や、コンソールから全部有効化する方法は避けるべきで、compute APIとstorage APIをピンポイントで有効化するのが正しい。", "vs": "cloudresourcemanager APIはプロジェクトやフォルダといったリソース階層を操作するためのAPIであり、これを有効化しても個々のサービス（Compute EngineやCloud Storage）が自動的に使えるようになるわけではない。gcloud init --projectはプロジェクトの初期設定コマンドであり、API有効化の手段ではない。", "opt": ["cloudresourcemanager APIはリソース階層を操作するためのAPIで、これを有効にしても個別のサービス機能が自動的に使えるようになるわけではない。", "正解。必要なcompute APIとstorage APIだけを個別に有効化するのが、最小権限の原則にかなった推奨されるやり方。", "全てのGoogle Cloud APIを有効化する方法は、使わない機能まで有効にしてしまい、不要な攻撃対象領域を増やすため推奨されない。", "gcloud init --projectはプロジェクトの初期設定を行うコマンドであり、個々のサービスのAPIを有効化する手段ではない。"]}'::jsonb),
  ('m2q31', '{"asked": "すでにDockerイメージを持っているアプリを、インフラの管理をせずに人気に応じて自動スケールさせるには、どのサービスにどう配置すべきかを問うている。", "point": "Dockerイメージがあり、インフラ管理なしで自動スケールしたいならCloud Runが最適。イメージの保存先はArtifact Registry。", "why_asked": "GKE Standardも自動スケールできるがノード管理（インフラ管理）が発生するため、「インフラを管理したくない」という条件を見落とすとGKEを選んでしまう。ACEではサーバーレスとコンテナオーケストレーションの住み分けが問われる。", "kid": "自分で車（インフラ）を運転・整備したくないなら、タクシー（Cloud Run）を呼べばいい。GKEは自分で車を持って整備しながら走る方式に近い。", "eg": "引っ越しに例えると、Cloud Runは「荷物（コンテナ）を渡すだけで運搬会社が全部やってくれる」宅配サービス、GKE Standardは「トラック（Node）を自分で借りて運転もする」レンタカー方式。インフラを管理したくないなら宅配サービスを選ぶ。", "terms": [["Cloud Run", "Dockerコンテナを渡すだけで、サーバーの管理なしに自動スケールしながら動かせるサーバーレスサービス"], ["Artifact Registry", "Dockerイメージなどのコンテナイメージを保存しておく、GCPの公式な保管庫"], ["GKE Standard", "Kubernetesクラスタを使うサービス。自動スケールもできるが、Node（VM）自体の管理がユーザー側に残る"]], "think": "「インフラを管理したくない」という条件が最大の分かれ目になる。GKE Standardはコンテナのオーケストレーションを自動化してくれるが、クラスタを構成するNode（VM）自体の管理はユーザー側の責任として残るため、完全にインフラから解放されるわけではない。一方Cloud Runは、Dockerイメージを渡すだけでGoogleがサーバーの起動・スケール・停止をすべて管理してくれるサーバーレスサービスで、リクエスト数（人気）に応じて自動的にインスタンス数を増減してくれる。すでにDockerイメージを作成済みという前提とも噛み合う。またDockerイメージの保存場所として使うのはArtifact Registryであり、Cloud Storageはオブジェクトの保管庫であってコンテナイメージ専用の管理機能を持たないため、イメージの保存先としては適さない。", "vs": "GKE Standardは自動スケールできる点では要件に近いが、Node管理というインフラ管理が残るため「インフラを管理したくない」という条件を満たさない。Cloud Storageはコンテナイメージ専用の保存場所ではなく、Dockerイメージの保管にはArtifact Registryを使うのが正しい。", "opt": ["インスタンステンプレートとMIGによる構成は、VMそのものの管理が必要になり「インフラを管理したくない」という条件に反する。", "GKE Standardは自動スケールできるが、Node（VM）の管理という形でインフラ管理が残ってしまう。", "Cloud StorageはDockerイメージの保存場所として想定されておらず、コンテナイメージの保管にはArtifact Registryを使うのが正しい。", "正解。DockerイメージをArtifact Registryに保存し、Cloud Runにデプロイすれば、インフラ管理なしで人気に応じた自動スケールが実現できる。"]}'::jsonb),
  ('m2q32b', '{"asked": "ゾーン障害が起きても業務停止時間なくデータをすぐに使える状態にしておくには、どんな永続ディスクをどう構成しておくべきかを問うている。", "point": "「即座に使える」ならリージョナル永続ディスクを使い、障害発生時に別ゾーンのVMへそのままアタッチする構成が正解。スナップショットからの復元は時間がかかるので「即座」には合わない。", "why_asked": "スナップショットは「バックアップして後で復元する」仕組みであり、復元には時間がかかる。「即座に利用可能」という要件の重みを見落として、スナップショットで十分だと判断してしまう誤りが典型的に狙われる。", "kid": "リージョナル永続ディスクは、あらかじめ2つの離れた場所（ゾーン）に自動でコピーを持っておくディスク。片方が壊れても、もう片方がすでに用意されているので、すぐに使い始められる。", "eg": "大事な書類を1部しか持たない（ゾーン永続ディスク）のではなく、あらかじめ別の建物にも同じ書類のコピーを常備しておく（リージョナル永続ディスク）イメージ。片方の建物が火事になっても、もう片方の建物からすぐ書類を取り出せる。写真（スナップショット）だけ撮っておいて後で現像する方式だと、いざという時に時間がかかる。", "terms": [["ゾーン永続ディスク", "1つのゾーンにのみ存在するディスク。そのゾーンが障害になるとディスクごと使えなくなる"], ["リージョナル永続ディスク", "同一リージョン内の2つのゾーンへ自動的に同期複製されるディスク。片方のゾーンが障害でももう片方がすぐ使える"], ["スナップショット", "ある時点のディスクの状態を保存したバックアップ。復元して新しいディスクを作るまでに時間がかかる"]], "think": "「ゾーン障害が起きてもデータが即座に利用可能」という要件から逆算すると、障害が起きてから何か作業をして復旧するのではなく、障害が起きる前からすでに別ゾーンにデータの実体が存在している状態を用意しておく必要がある。ゾーン永続ディスクは1つのゾーンにしか存在しないため、そのゾーンが障害になればディスクごと使えなくなり、スナップショットを取っていたとしても、そこから新しいディスクを復元する作業には時間がかかり「即座」の要件を満たせない。一方リージョナル永続ディスクは、同一リージョン内の2つのゾーンへリアルタイムに同期複製されており、片方のゾーンが障害になっても、もう片方のゾーンにはすでに最新のデータが存在している。したがって障害発生時にはそのディスクを別ゾーンのVMにアタッチするだけで、復元作業なしにすぐデータを使い始められる。", "vs": "スナップショットを絡める2つの案は、いずれも障害発生後に「復元する」という時間のかかる作業が挟まるため、「即座に利用可能」という要件を満たせない。ゾーン永続ディスクをそのまま別ゾーンでアタッチする案は、そもそもゾーン永続ディスクの実体が障害ゾーンに閉じ込められているため、別ゾーンで使えるようにはならない。", "opt": ["ゾーン永続ディスクはスナップショットを取っていても、障害後の復元作業に時間がかかり「即座」の要件を満たせない。", "ゾーン永続ディスクの実体は障害が起きたゾーンにしか存在しないため、別ゾーンでそのままアタッチすることはできない。", "リージョナル永続ディスクを使っていても、あえてスナップショットからの復元を挟む手順では、すでに複製済みのデータをそのまま使う場合より時間がかかり不要な遠回り。", "正解。リージョナル永続ディスクは2ゾーンに同期複製済みなので、障害時はそのまま別ゾーンのVMにアタッチするだけで即座にデータを使い始められる。"]}'::jsonb),
  ('m2q33', '{"asked": "DevOpsグループにCompute Engineだけの完全な管理権限を与え、他のリソースへの変更権限は持たせたくないとき、Googleが推奨するロールの組み合わせはどれかを問うている。", "point": "事前定義ロールを優先し、Compute Engine全体を管理させたいならroles/compute.admin、他リソースは閲覧だけでよいならroles/viewerを組み合わせる。", "why_asked": "「完全な制御」という言葉から、範囲の広いroles/editorのような基本ロールに飛びつきやすいが、それでは他リソースへの変更権限まで与えてしまう。事前定義ロールの粒度（compute.adminとinstanceAdminの違い）も狙われる。", "kid": "Compute Engineという1つの持ち場だけ全部お任せしたいなら、その持ち場専用の鍵（compute.admin）を渡し、他の持ち場は見るだけできる鍵（viewer）を渡す。全部の鍵（editor）を渡す必要はない。", "eg": "工場の一区画（Compute Engine）だけを任せたい職人に、その区画の作業道具一式（compute.admin）を渡し、他の区画は見学だけ許可する（viewer）イメージ。工場全体の合鍵（editor）を渡す必要はない。", "terms": [["roles/compute.admin", "Compute Engineに関するリソース（VM・ディスク・ネットワーク・ファイアウォールなど）を丸ごと管理できる事前定義ロール"], ["compute.instanceAdmin", "VMインスタンスの管理はできるが、ネットワークやファイアウォールなど他のCompute Engineリソースまでは含まれない、より狭い範囲のロール"], ["roles/viewer", "プロジェクト内のほぼ全リソースを閲覧のみできる基本ロール。変更・作成の権限は持たない"], ["roles/editor", "ほぼ全リソースを作成・変更できる、非常に広い権限を持つ基本ロール"]], "think": "「Compute Engineリソースの完全制御」という要件をまず分解すると、Compute Engineに含まれるのはVMだけでなく、ディスク・ネットワーク・ファイアウォールなども含む。compute.instanceAdminはVMの管理に限定されたロールで、ネットワークやFWの管理権限を含まないため「完全制御」には不足する。これに対しroles/compute.adminはCompute Engine関連のリソース全体を管理できる事前定義ロールであり、「完全制御」の要件にちょうど合う。一方「他のリソースの作成・更新権限は持たせたくない」という制約から、roles/editorのような全リソースに書き込みできる広い基本ロールは選べない。他リソースへの最低限のアクセス（閲覧程度）を残しつつ書き込み権限を与えないなら、roles/viewerが妥当。ロール選びの原則として、目的に合う事前定義ロールがあるならカスタムロールより優先して使うべきなので、フォルダレベルでカスタムロールを新たに作る必要もない。", "vs": "compute.instanceAdmin系の権限だけでは、ネットワークやFWを含むCompute Engine全体の完全制御には足りない。roles/editorは他リソースにまで変更権限が及んでしまい、「他リソースは持たせたくない」という制約に反する。カスタムロールをわざわざ作る案は、既に目的に合う事前定義ロール（compute.admin）が存在するため不要。", "opt": ["正解。roles/viewerで他リソースは閲覧のみに留めつつ、roles/compute.adminでCompute Engine全体の完全な管理権限を与える組み合わせが要件に合う。", "compute.instanceAdmin系の権限はVM管理に限定され、ネットワークやFWを含むCompute Engine全体の「完全制御」には不足する。", "目的に合う事前定義ロール（compute.admin）がすでに存在するため、フォルダレベルでカスタムロールを新規作成する必要はない。", "roles/editorは他リソースにまで変更権限が及んでしまい、「他リソースの権限は持たせたくない」という制約に反する。"]}'::jsonb),
  ('m2q34', '{"asked": "すでにDockerコンテナで動いているPythonのマイクロサービス群を、既存のCI/CDとDockerイメージをできるだけそのまま使ってサーバーレスに移行するには、どのサービスにどう配置すべきかを問うている。", "point": "Dockerコンテナをそのまま持ち込めるサーバーレスサービスはCloud Run。既存のCI/CDとDockerイメージは使い回し、環境が変わることで必要になる設定値やエンドポイントだけを更新する。", "why_asked": "Cloud FunctionsはFaaS（関数単体）であり、Dockerイメージをそのままデプロイする機能は存在しない。「サーバーレス＝Cloud Functions」という短絡的な連想を崩せるかが問われる。", "kid": "Cloud Runは「コンテナ（お弁当箱ごと）」を渡せばそのまま動かしてくれるサービス。Cloud Functionsは「中身のおかず（コードの断片）」だけを渡す仕組みで、お弁当箱ごとは受け取ってくれない。", "eg": "引っ越しに例えると、Cloud Runは今使っている家具（Dockerコンテナ）をそのままトラックで運んで新居に置いてくれるサービス。Cloud Functionsは家具を一度全部解体して部品（個別の関数）に分解しないと運べないサービスで、複雑な家具（マイクロサービス群）には向かない。", "terms": [["Cloud Run", "Dockerコンテナをそのまま受け取って、HTTPサーバーとして動かせるサーバーレスサービス"], ["Cloud Functions", "1つの関数（コードの断片）単位でデプロイするFaaS(Functions as a Service)。Dockerイメージをそのままデプロイする機能はない"], ["環境変数", "アプリの設定値（接続先URLなど）をコードに埋め込まず外部から渡す仕組み。移行先の環境が変わると値も更新が必要になる"]], "think": "すでにDockerコンテナで動いている複雑なマイクロサービス群を「最小限の変更」で移行したいという要件がまず前提になる。Cloud Functionsは1つの関数のコードだけを受け取って実行するFaaSであり、Dockerイメージをそのままデプロイする機能自体が存在しないため、コンテナ化された既存資産をそのまま持ち込めない。一方Cloud Runは、HTTPサーバーとして動くDockerコンテナをほぼそのまま受け取って動かせるサービスであり、既存のCI/CDパイプラインとDockerイメージをそのまま活用できる。ただし移行先の環境（IPアドレスやURLなど）は必ず変わるため、環境変数として注入している設定値やサービス間のエンドポイントは、新しい環境に合わせて更新する作業が必要になる。マイクロサービスを個別の関数に分解し直す案は、複雑な既存コードの書き直しが発生し「最小限の変更」という要件から外れる。", "vs": "Cloud Functionsを使う案は、Dockerイメージを直接デプロイする機能が存在しない点で技術的に成立しない。個別のCloud Functionsやコードベースの書き直しを伴う案は、複雑なマイクロサービス群を関数単位に分解し直す大掛かりな作業が必要になり「最小限の変更」に反する。またオンプレと全く同じ設定をそのまま使う想定も、環境が変わればIPやURLは必ず変化するため非現実的。", "opt": ["正解。既存のCI/CDとDockerイメージを使ってCloud Runにデプロイし、環境が変わることで必要になる設定やエンドポイントだけを更新する。", "Cloud FunctionsはDockerイメージを直接デプロイする機能を持たないため、既存のコンテナ資産をそのまま移行する手段として成立しない。", "既存コードベースを個別のCloud Functionsとして分解し直す作業は書き直しの手間が大きく、「最小限の変更」という要件に反する。", "個別のCloud Runに分解し直す作業も書き直しが発生する上、環境が変わるのに「オンプレと同じ設定」をそのまま使う想定は非現実的。"]}'::jsonb),
  ('m2q38', '{"asked": "オンプレの分析バイナリ群を毎晩短時間だけメモリ上で処理する仕組みを、最小の手間とコストでGCPへ移すにはどうすべきかを問うている。", "point": "コンテナ化や書き直しが不要な既存バイナリの移行はリフト＆シフトが最小の手間。毎晩短時間しか動かさないならインスタンススケジュールで起動・停止すればコストも最小に抑えられる。", "why_asked": "「GCPに移行する＝サーバーレス化やコンテナ化」という思い込みで飛びつきやすいが、既存バイナリをそのまま動かしたいだけなら手間の少ないリフト＆シフトの方が適切というケースがACEでは問われる。", "kid": "今ある機械（バイナリ）を分解して作り直す（コンテナ化）のではなく、そのままトラックで運んで新しい工場（Compute Engine）に置くだけ（リフト＆シフト）。工場は毎晩45分だけ電源を入れて、終わったら消す。", "eg": "引っ越しに例えると、家具を全部バラして新しい規格に合わせて作り直す（コンテナ化・書き直し）のではなく、そのままトラックで運んで新居に置く（リフト＆シフト）方が圧倒的に手間が少ない。夜だけ使う部屋の電気を、使う時間だけつけて消す（インスタンススケジュール）ようにすればコストも抑えられる。", "terms": [["リフト＆シフト", "既存のアプリやバイナリをほとんど変更せず、そのままクラウドの仮想マシンに移す移行方式。作り直しの手間がない"], ["インスタンススケジュール", "VMを決まった時刻に自動で起動・停止する設定。使わない時間帯は課金を止められる"], ["Cloud Functions", "1つの関数として動く小さなコードを実行するサービス。既存のバイナリ実行ファイル群をそのまま動かす用途には向かない"]], "think": "まず「最小の手間」という要件から、既存の分析バイナリ群をコンテナ化したり、コードをFaaS向けに書き直したりする作業が必要な選択肢は外れる。バイナリをコンテナ化する案はDockerイメージ作成という追加作業が発生し、Cloud Functionsへのアップロードという案も、実行ファイル形式のバイナリ群をFaaSの実行モデルに合わせて作り直す必要があり、どちらも「最小の手間」に反する。既存バイナリをそのまま動かしたいだけなら、Compute Engineへのリフト＆シフト（変更なしでVM上にそのまま置く）が最も手間がかからない。次に「最小のコスト」を満たすには、このバッチが毎晩45分だけ動けばよいという特性を活かし、インスタンススケジュールで必要な時間だけVMを自動起動・自動停止させれば、動いていない時間は課金されず無駄がない。", "vs": "コンテナ化やGKEへのデプロイは、バイナリをコンテナイメージに詰め直す追加作業が発生し「最小の手間」に反する。Cloud Functionsは実行ファイル形式のバイナリ群をそのまま動かす実行モデルではないため、コード自体の作り直しが必要になり不適切。", "opt": ["バイナリのコンテナ化とCloud Runジョブへの移行は、コンテナイメージを作る追加作業が発生し「最小の手間」という要件に反する。", "GKE Standardへのデプロイはコンテナ化に加えクラスタのノード管理という運用の手間も増え、要件に合わない。", "Cloud Functionsは1つの関数として動くコードを想定した実行モデルで、既存の分析バイナリ群をそのまま動かす用途には向かない。", "正解。既存バイナリをそのままCompute Engine VMへリフト＆シフトし、インスタンススケジュールで毎晩45分だけ起動・停止させれば、手間もコストも最小になる。"]}'::jsonb),
  ('m2q39', '{"asked": "複数のGKEクラスタがある環境で、まだ操作したことのない別クラスタのノードをkubectlで確認するには、事前にどんな準備が必要かを問うている。", "point": "新しいクラスタを操作するには、まずgcloud container clusters get-credentialsでそのクラスタの認証情報をkubeconfigに登録し、コンテキストを切り替えてから通常のkubectlコマンドを使う。", "why_asked": "kubectlはkubeconfigに登録済みのクラスタしか操作できないという前提を見落とし、「コンテキストを切り替えるだけ」で済むと誤解しやすい。get-credentialsとset-contextの役割の違いが典型的に狙われる。", "kid": "kubectlは「連絡先に登録した相手」としか話せない電話のようなもの。dev-clusterとまだ話したことがなければ、まず連絡先に登録する（get-credentials）作業が必要で、登録済みの相手を選ぶだけ（set-context）では話せない。", "eg": "新しい取引先とやり取りするには、まず名刺交換をして連絡先を登録する（get-credentials）必要がある。すでに連絡先にある相手を選んで電話をかける（set-context）だけでは、まだ交換していない相手とはつながらない。", "terms": [["kubeconfig", "kubectlがどのクラスタに接続できるかの認証情報・接続先をまとめて保存しているローカルの設定ファイル"], ["get-credentials", "指定したGKEクラスタの認証情報をkubeconfigに登録し、そのクラスタを操作できる状態にするgcloudコマンド"], ["kubectl config set-context", "kubeconfigにすでに登録済みの複数クラスタの中から、操作対象を切り替えるためのコマンド"]], "think": "kubectl get nodesがprod-clusterのノードしか表示していないという状況から、kubectlは現在prod-clusterにしか接続できる状態になっていないと分かる。kubectlはkubeconfigというローカルの設定ファイルに登録されているクラスタとしか通信できないため、dev-clusterをまだ一度も操作していないなら、そのクラスタの接続情報はkubeconfigに存在しない。この状態でkubectl config set-contextを使っても、そもそも登録されていないクラスタへは切り替えられない。まず必要なのは、gcloud container clusters get-credentials dev-clusterを実行してdev-clusterの認証情報をkubeconfigに新規登録することで、これによりコンテキストも自動的にdev-clusterへ切り替わる。その後にkubectl get nodesを実行すれば、dev-clusterのノードが表示される。", "vs": "kubectl config set-contextは、すでにkubeconfigに登録済みの複数クラスタを切り替えるためのコマンドであり、まだ登録されていないクラスタへの接続には使えない。updateコマンドでパスワードを再生成する操作はクラスタ自体の設定変更であり、kubectlからの接続に必要な認証情報の登録とは別の話。", "opt": ["正解。get-credentialsでdev-clusterの認証情報をkubeconfigに登録すれば接続できる状態になり、kubectl get nodesでノードを確認できる。", "クラスタのパスワード再生成はクラスタ側の設定変更であり、kubectlからdev-clusterに接続するための認証情報登録にはならない。", "set-contextはkubeconfigにすでに登録済みのクラスタを切り替えるコマンドで、まだ登録されていないdev-clusterには使えない。", "set-credentialsも同様に、まだkubeconfigに登録されていないクラスタの接続情報を新規に用意する手段としては不適切。"]}'::jsonb),
  ('m2q4', '{"asked": "あるサブネットのDBサーバーに対して、別サブネットの決まったアプリサーバーからのDB通信だけを許可するファイアウォールルールをどう設計すべきかを問うている。", "point": "受信側（DB）を守るならイングレスルール。送信元・ターゲットの指定はIPではなくサービスアカウントで行うのがベストプラクティス。", "why_asked": "FWルールの方向（イングレス/エグレス）をどちらの視点で考えるかで混乱しやすく、また対象の指定方法としてネットワークタグとサービスアカウントのどちらを使うべきかも狙われるポイント。", "kid": "「誰が誰に話しかけるのを許すか」を、家（DBサーバー）の玄関で決める（イングレス）。誰が話しかけてよいかを見分けるのに、住所（IP、変わりやすい）ではなく名札（サービスアカウント、VMに固定でつく）を使う。", "eg": "会社の受付（DBサーバー）で「経理部の社員証を持つ人だけ通す」というルールを作るときに、その人の顔（IPアドレス、日によって変わりうる）で判断するのではなく、常に身につけている社員証（サービスアカウント）で判断する方が確実、というイメージ。", "terms": [["イングレスルール", "外から自分（対象VM）へ入ってくる通信を許可・拒否するファイアウォールルール。DBサーバーを守るときはこちら"], ["エグレスルール", "自分から外へ出ていく通信を許可・拒否するルール。今回のようにDB側を守る目的には使わない"], ["サービスアカウント(SA)によるFWターゲット指定", "IPアドレスの代わりにVMに紐づくサービスアカウントを送信元・ターゲットに指定する方式。IPが変わっても影響を受けず管理がしやすい"]], "think": "「subnet-aのDBサーバーへの通信を制限したい」ということは、守りたい対象（DBサーバー）への「入ってくる」通信を制御する話であり、これはイングレスルールの役割になる。エグレスルールは自分から外へ出ていく通信を制御するものなので、DB側を守る今回の目的には合わない。次に、送信元・ターゲットの指定方法を考えると、IPアドレスはVMの再作成やスケールで変わりうるため、IPを直接指定する方式は管理が煩雑で壊れやすい。GCPのベストプラクティスでは、VMに紐づくサービスアカウントを送信元・ターゲットとして指定する方法が推奨されており、これならIPが変わっても設定を書き換える必要がない。アプリサーバー用にsa-app、DBサーバー用にsa-dbというサービスアカウントをそれぞれ作成・関連付けし、「sa-appからsa-dbへの通信を許可する」イングレスルールを作るのが最も堅牢な設計になる。", "vs": "エグレスルールで組む案は、守りたいDB側への「入ってくる」通信を制限するという目的の方向と逆になっており、成立しない。ネットワークタグとサービスアカウントを混在させる設計は、対象の指定方法が2種類混じることで管理が複雑になり、GCPのベストプラクティスとしても片方の方式に統一することが推奨される。", "opt": ["正解。sa-appとsa-dbのサービスアカウントを作成・関連付け、sa-appからsa-dbへの通信のみを許可するイングレスルールを作る。DB側への通信を守るのでイングレス、指定はIPより堅牢なサービスアカウントで行う。", "エグレスルールは自分から外へ出ていく通信を制御するもので、DBサーバーへの受信を守るという今回の目的の方向と逆になる。", "サービスアカウントとネットワークタグを混在させる設計は管理が複雑になり、片方の方式に統一するベストプラクティスに反する。", "タグとサービスアカウントを混在させた上にエグレスルールを使う設計は、方向・指定方法の両方で今回の目的からずれている。"]}'::jsonb),
  ('m2q43', '{"asked": "ノードの正当性を検証できる仕組みと、インターネットから到達できないノード、そしてクラスタ運用の手間の削減という3つの条件を同時に満たすGKEの構成はどれかを問うている。", "point": "シールドノードによる検証可能な整合性、インターネット遮断はプライベート構成、運用コスト削減はAutopilot。この3つを同時に満たせるのはプライベートAutopilotクラスタだけ。", "why_asked": "Standardクラスタでも個々の設定を積み上げれば同じ条件を満たせそうに見えるが、「運用コストの削減」まで含めるとAutopilotでなければ達成できない点が見落とされやすい。", "kid": "シールドノードは「このノードは本物で改ざんされていない」と証明できる仕組み。プライベートは「外から見えない・入れない」設定。Autopilotは「ノードの世話をGoogleに任せる」モード。この3つが全部揃っているのがプライベートAutopilot。", "eg": "空港の保安エリアに例えると、シールドノードは「本人確認済みの証明書付き通行証」、プライベートは「一般客が入れない立入禁止エリア」、Autopilotは「警備員の配置や巡回をすべて空港側（Google）が管理してくれる」体制。この3つが揃って初めて要件をすべて満たす。", "terms": [["シールドノード", "ノードの起動時の整合性（改ざんされていないこと）を検証できる仕組み。Autopilotクラスタではデフォルトで有効"], ["プライベートクラスタ", "ノードにパブリックIPを持たせず、インターネットから直接アクセスできないようにするGKEクラスタの構成"], ["GKE Autopilot", "ノードの作成・管理・スケーリングをGoogleが自動で行うGKEの運用モード。運用の手間を大幅に削減できる"], ["GKE Standard", "ノードプールの管理をユーザー自身が行うモード。柔軟性は高いが運用の手間はAutopilotより大きい"]], "think": "要件を1つずつ分解すると、まず「検証可能なノードのIDと整合性」が求めているのはシールドノードという機能で、これはAutopilotクラスタではデフォルトで有効になっている。次に「ノードはインターネットからアクセス不可」という条件は、ノードにパブリックIPを持たせないプライベートクラスタの構成で満たせる。最後に「クラスタ管理の運用コストを削減したい」という条件は、ノードの管理をGoogleに任せるAutopilotモードを選ぶことで満たせる。ここでStandardクラスタでシールドノードを個別に有効化する構成を考えると、シールドノードとプライベート構成の条件は満たせても、Standardではノードプールの管理という運用の手間がユーザー側に残るため「運用コストの削減」の条件を満たせない。したがって3つの条件をすべて同時に満たすのは、プライベート構成のAutopilotクラスタだけになる。", "vs": "パブリックなAutopilotクラスタは、Autopilotによる運用コスト削減とシールドノードは満たすが、ノードがインターネットからアクセス可能な構成になっており「アクセス不可」という条件に反する。Standardクラスタでのシールドノード有効化は、検証可能なIDとプライベート構成は満たせても、ノード管理の手間が残るため運用コスト削減の条件を満たさない。", "opt": ["正解。プライベートAutopilotクラスタなら、シールドノードによる検証可能な整合性、ノードのインターネット非公開、Autopilotによる運用コスト削減の3つを同時に満たせる。", "パブリックなAutopilotクラスタは、ノードがインターネットからアクセス可能な構成になっており「アクセス不可」という条件を満たさない。", "Standardパブリッククラスタは、ノードがインターネットに公開される構成な上、ノードプール管理の手間も残り、複数の条件を満たさない。", "Standardプライベートクラスタは検証可能なIDとインターネット非公開の条件は満たせるが、ノードプールの管理という運用の手間が残り、運用コスト削減の条件を満たさない。"]}'::jsonb),
  ('m2q44', '{"asked": "Webアプリ・バックエンドAPI・スケジュールされた長時間のETLバッチという3つの異なる性質のコンポーネントを、それぞれサーバーレスで運用コストを抑えて動かすには、どのサービスにどう振り分けるべきかを問うている。", "point": "コード資産の性質ごとに使い分ける。フレームワークのコードをそのまま渡すだけならApp Engine、HTTPサーバーとして動くコンテナならCloud Run、時間のかかるバッチはCloud Tasksでスケジューリングし実処理はCloud Run上のジョブとして実行する。", "why_asked": "3つの異なる性質のワークロードを1つのサービスに無理に統一しようとしたり、静的ファイル配信専用のCloud Storageに動的なPythonアプリを乗せようとしたりする誤りが典型的に狙われる。", "kid": "Webアプリは「コードだけ渡せばGoogleが動かしてくれる」お任せ便（App Engine）、APIは「コンテナごと渡すお弁当箱」宅配（Cloud Run）、時間のかかるバッチは「予約表（Cloud Tasks）を見ながら決まった時間に厨房（Cloud Run）で調理する」仕組み。", "eg": "レストランの厨房に例えると、日替わりメニューを毎日出す係（Flaskウェブアプリ）はお店専属のシェフ（App Engine）、注文が来たら都度対応するデリバリー係（API）は箱ごと持ち込む出張シェフ（Cloud Run）、月末にまとめて仕込む大量調理（長時間ETL）は予約表（Cloud Tasks）でスケジュールしてから厨房を使う、という役割分担。", "terms": [["App Engine", "PythonなどのWebフレームワークのコードをそのままアップロードするだけで、サーバー管理なしに動かせるサーバーレスサービス"], ["Cloud Run", "Dockerコンテナを渡してHTTPサーバーとして動かすサーバーレスサービス。バッチ処理をジョブとして実行する使い方もできる"], ["Cloud Tasks", "処理の実行タイミングをスケジューリング・キューイングする仕組み。実際の処理自体は別のサービス（今回はCloud Run）が行う"], ["ETL", "データを抽出(Extract)・変換(Transform)・書き込み(Load)する一連のバッチ処理"]], "think": "3つのコンポーネントをそれぞれの性質に合わせて考える。まずFlaskのWebアプリは、Pythonのフレームワークで書かれたコードをそのままGoogleに渡せば動かしてくれるApp Engineが最も自然な移行先で、コードの書き直しがほとんど要らない。次にバックエンドAPIは、既にDockerコンテナ化されているかどうかに関わらずHTTPサーバーとして動く性質のワークロードなので、コンテナをそのまま動かせるCloud Runが適している。最後に長時間のETLバッチは、決まったタイミングで実行したいという性質から、実行タイミングの管理をCloud Tasksに任せ、実際の重い処理はCloud Run（ジョブとして）で実行する組み合わせが適切になる。Cloud StorageはHTMLやCSSなどの静的ファイルを配信するだけの仕組みであり、Pythonのコードを実行する機能を持たないため、動的なFlaskアプリの実行場所にはなり得ない。またCompute Engineでバッチを実行する案は、VM自体の管理が必要になりサーバーレスの運用コスト削減という要件に反する。", "vs": "Cloud Storageは静的ファイル配信専用で、Pythonコードの実行環境を持たないためFlaskアプリは動かない。Compute Engineでバッチを実行する構成は、VMの管理という運用コストが発生し、サーバーレスで運用コストを抑えるという目的に反する。", "opt": ["ウェブとAPIの振り分けは正しいが、バッチをCloud TasksでCompute Engineで実行する構成はVM管理の手間が発生し、サーバーレスで運用コストを抑える目的に反する。", "正解。FlaskウェブアプリはApp Engine、バックエンドAPIはCloud Run、長時間バッチはCloud Tasksでスケジューリングしつつ実処理はCloud Runのジョブとして実行する組み合わせが、3つの性質に最も合う。", "Cloud StorageはHTMLやCSSなどの静的ファイル配信専用のサービスで、動的なPythonコードを実行する機能がないためFlaskアプリは動かせない。", "ウェブの配置場所がCloud Storageで動かせない上、バッチをCompute Engineで実行する構成もVM管理が発生し、どちらも要件に反する。"]}'::jsonb),
  ('m2q46', '{"asked": "30日を超えてアクセスされなくなったファイルのストレージコストを、自動的に節約するにはどうすべきかを問うている。", "point": "「削除せず保持しつつコストだけ下げたい」なら、ライフサイクルルールでオブジェクトをより安いストレージクラス（Archiveなど）へ自動的に変更する。", "why_asked": "「コスト削減」と聞いて「削除すればいい」と早合点しやすいが、データ自体は消してはいけないという前提を見落とすと誤る。ストレージクラスの自動変更という機能の存在を知っているかが問われる。", "kid": "よく使う道具は手元の引き出し（Standard）に置き、しばらく使っていない道具は倉庫の奥（Archive）にしまうイメージ。捨てるわけではなく、置き場所を安い場所に移すだけ。", "eg": "図書館の本に例えると、最近借りられた本は入口近くの棚（Standardストレージ）に置き、長く借りられていない本は郊外の格安倉庫（Archiveストレージ）に移す。本を捨てるわけではなく、保管場所を変えるだけで維持コストが下がる。", "terms": [["ライフサイクルルール", "Cloud Storageのオブジェクトが一定の条件（経過日数など）を満たしたら、自動的にストレージクラスを変更したり削除したりする設定"], ["Archiveストレージ", "Cloud Storageの中で最も安価なストレージクラス。取り出し頻度が非常に低いデータ向けで、保存コストが最小になる"], ["保持ポリシー", "一定期間はオブジェクトを削除・上書きできないようにするロック機能。コスト削減の機能ではなく、消させないための機能"]], "think": "要件は「削除する」のではなく「アクセスされなくなったファイルのコストを節約する」ことである点に注意する。データを消してよいなら削除で解決できるが、今回はデータを保持したままコストだけ下げたいので、削除する案はそもそも目的とずれる。Cloud Storageにはライフサイクルルールという機能があり、「作成から30日を超えたオブジェクト」といった条件を満たしたファイルを、自動的により安価なストレージクラス（今回ならArchive、四半期〜年に一度程度のアクセス頻度を想定した最安クラス）へ変更できる。これによりファイルはそのまま残りつつ、保存コストだけが下がる。保持ポリシーは「一定期間は削除・上書きできないようにする」ロック機能であり、コストを下げる機能ではないため今回の目的には合わない。バージョニングと組み合わせて非現行バージョンを期限切れにする案も、今回問われているのはファイル本体のアクセス頻度によるコスト削減であり、バージョン管理の話ではない。", "vs": "Cloud SchedulerとCloud Functionsで毎日ファイルを削除する案は、データそのものを消してしまいコスト削減という目的を超えて要件（アプリは過去30日以内のファイルにアクセスする、それ以外は保持したい）を壊してしまう。保持ポリシーはむしろ「削除できなくする」機能であり、コスト削減とは無関係。", "opt": ["正解。ライフサイクルルールで30日を超えたオブジェクトを自動的にArchiveストレージクラスへ変更すれば、データを保持したまま保存コストを下げられる。", "毎日ファイルを削除する構成はデータそのものを消してしまい、単なるコスト削減を超えてデータを失う結果になる。", "保持ポリシーは一定期間オブジェクトを削除・上書きできなくするロック機能であり、コストを下げる機能ではない。", "バージョニングと非現行バージョンの期限切れ設定は、複数バージョンの管理が目的の機能で、ファイル本体のアクセス頻度に基づくコスト削減とは別の話。"]}'::jsonb),
  ('m2q47', '{"asked": "リソース要件が不明で変動するワークロードに対して、常に機能する可用性の確保と、費用対効果の高いCPU/メモリの推奨値提示を両立させるには、どの自動化機能をどの役割で使い分けるべきかを問うている。", "point": "「常時安定して機能する可用性」はHPAが担当。「適正なCPU/メモリの提案」はVPAの推奨モードが担当。この役割分担を逆にしない。", "why_asked": "HPAとVPAはどちらも「オートスケーリング」という名前でくくられがちだが、片方はPod数の増減、もう片方はPod1つあたりのリソース量の調整という別の軸を担っており、この違いが繰り返し問われる。", "kid": "HPAは「人数（Podの数）を増やしたり減らしたりする係」、VPAは「1人あたりの持ち物（CPU・メモリの量）をどれくらいにすべきか教えてくれる係」。今回は「安定して働ける人数」をHPAに、「ちょうどいい持ち物の量の提案」をVPAに任せる。", "eg": "レストランの営業に例えると、忙しさに応じてホールスタッフの人数を増減する（HPA）のが安定した営業（可用性）を支え、一方で「一人あたりどれくらいの食器や道具を持たせるべきか」を分析して提案する（VPAの推奨モード）のが効率化のヒントになる。両方揃って初めて「安定していて、かつ無駄がない」運営になる。", "terms": [["HPA(Horizontal Pod Autoscaler)", "負荷に応じてPodの数を自動的に増減させる仕組み。可用性の確保に使う"], ["VPA(Vertical Pod Autoscaler)", "Pod1つあたりのCPU・メモリの割り当て量を分析し、適正な値を推奨（または自動調整）する仕組み"], ["Cluster Autoscaler", "クラスタ全体のNode（VM）の数を自動的に増減させる仕組み。Podのリソース量やPod数の推奨とは別のレイヤーの機能"]], "think": "要件を2つに分けて考える。1つ目は「あらゆる状況で一貫して機能する」可用性の確保で、これは負荷の変動に応じてPodの数そのものを増減させるHPAの役割になる。2つ目は「CPU/メモリの費用対効果の高い推奨事項」で、これは各Podに割り当てるCPU・メモリの量が適正かどうかを分析するVPAの役割になる。ここで重要なのは、VPAには実際に値を自動変更する「Auto」モードと、値を提案するだけで自動変更はしない「推奨（Recommendation）」モードがあることで、今回は「推奨事項」を求めているのでVPAの推奨モードを使う。もしVPAのAutoモードを可用性の確保に使おうとすると、Pod単体のリソース量変更のためにPodの再作成が発生し、HPAほど滑らかにトラフィックの増減へ追従できない。Cluster Autoscalerは、クラスタ全体のNode数を増減させる機能であり、Pod単位のリソース推奨やPod数の調整とは別のレイヤーの話なので、今回の2つの要件のどちらにも直接対応しない。", "vs": "Cluster Autoscalerを推奨事項の提示役に使う案は、Node数の増減はできてもCPU/メモリの適正値そのものを推奨する機能ではないため、役割が合っていない。VPAを可用性確保の役割に使う案は、リソース量の変更にはPodの再作成を伴うため、負荷変動へのなめらかな追従という点でHPAに劣る。", "opt": ["Cluster AutoscalerはNode数の増減を行う機能であり、CPU/メモリの適正値そのものを提案する役割は担えない。", "正解。HPAで負荷変動に応じたPod数の増減による可用性を確保し、VPAの推奨モードでCPU/メモリの適正値を提案してもらう組み合わせが要件に合う。", "VPAをリソース量の変更で可用性確保に使う案は、Podの再作成を伴うためHPAほど滑らかに負荷変動へ追従できない。", "VPAを可用性確保、HPAを推奨事項の役割に当てる組み合わせは、それぞれの機能の役割を入れ替えてしまっており成立しない。"]}'::jsonb),
  ('m2q48', '{"asked": "請求書のリビジョン履歴を一定数まで保存しつつ、古いデータは自動的に安いストレージ層へ移し、期限が来たら削除する仕組みを、運用・開発コストを抑えてどう組むべきかを問うている。", "point": "複数バージョンの保持はバージョニング、ストレージクラスの自動変更・バージョン数の制限・古いファイルの自動削除は全部ライフサイクルルールの組み込み機能でまかなえる。カスタムのFunctions/Schedulerは不要。", "why_asked": "「複雑な要件だから自前で仕組みを作らないといけない」と考えがちだが、Cloud Storageの標準機能（バージョニング＋ライフサイクルルール）だけで全部完結する組み合わせを知っているかが問われる。", "kid": "バージョニングは「上書きしても古いバージョンを何世代か残しておく」機能。ライフサイクルルールは「古くなったら安い場所に移す・古すぎる世代は消す」というルールを自動で見てくれる係。この2つを設定するだけで、自分でプログラムを書く必要はない。", "eg": "会社の書類保管に例えると、バージョニングは「同じ請求書を上書きしても、直近5回分の履歴を捨てずに取っておく」仕組み。ライフサイクルルールは「1年を過ぎた書類は安い倉庫に移し、古すぎる履歴は自動で処分する」係で、これを一度設定しておけば、あとは何もしなくても自動で回り続ける。", "terms": [["バージョニング", "同じファイル名で上書き保存しても、古いバージョンを一定数まで残しておく機能"], ["ライフサイクルルール", "経過日数やバージョン数といった条件に応じて、ストレージクラスの変更や削除を自動的に行う設定"], ["保持ポリシー", "一定期間はオブジェクトの削除・上書きを禁止するロック機能。今回のように能動的にクラス変更や削除を行いたい要件には使えない"]], "think": "要件を3つに分解する。「5リビジョンまで保存」はファイルの複数バージョンを残す話なのでバージョニングの機能に対応する。「365日超は低コスト層へ移動」と「古いファイルを削除して運用コストを最小に」の2つは、いずれもCloud Storageのライフサイクルルールに組み込まれている機能（経過日数条件でのストレージクラス変更、バージョン数条件での古いバージョンの削除）でまかなえる。したがって、バージョニングを有効化してライフサイクルルールで「365日経過でクラス変更」「保持するバージョン数を5に制限」「条件を満たした古いファイルの削除」を設定すれば、自前でCloud FunctionsやCloud Schedulerを書かなくても要件を満たせる。保持ポリシーは「削除・上書きを禁止する」ロック機能であり、今回のように能動的にクラスを変えたり古いものを消したりしたい要件とは方向が逆になるため使えない。", "vs": "保持ポリシーは削除・上書きを禁止するロック機能であり、直近5リビジョンだけを残すといった世代管理の機能は持たない。リビジョン保持にはバージョニングが必要。カスタムのFunctions/Schedulerでの自前実装も、すでにある組み込み機能で足りる分だけ開発コストが余分にかかる。", "opt": ["保持ポリシーは複数バージョンを世代管理する仕組みではなく、5リビジョンの保持には使えない。またクラス変更や削除をCloud FunctionsとSchedulerで自前実装するのは、組み込みのライフサイクルルールで足りる分だけ開発コストが余分にかかる。", "保持ポリシーは削除・上書きを禁止するロック機能であり、直近5リビジョンだけを残すといった世代管理の機能は持たない。リビジョン保持にはバージョニングが必要。", "バージョニングは正しいが、クラス変更や削除をCloud FunctionsとSchedulerで自前実装する必要はなく、ライフサイクルルールの組み込み機能で完結でき、開発コストが余分にかかる。", "正解。バージョニングでリビジョンを保持しつつ、ライフサイクルルールでストレージクラスの変更・保存バージョン数の制限・古いファイルの削除を全て組み込み機能でまかなえる。"]}'::jsonb),
  ('m2q49', '{"asked": "gcloud CLIのプロキシ認証情報が、コマンドのログに記録されてしまうのを防ぐには、どうやって認証情報を渡すべきかを問うている。", "point": "機密情報はコマンドライン引数や設定ファイルに直書きせず、環境変数として渡せばコマンド実行のログやファイルに残らない。", "why_asked": "「設定ファイルに書いておけば安全」という誤解や、パスワードをハッシュ化すれば使えると考える誤りが典型的に狙われる。認証情報の受け渡し方法ごとの露出リスクの違いが問われる。", "kid": "gcloud config setでパスワードを設定すると、その操作自体がログに残ってしまう。環境変数は「その場限りでこっそり渡す」方法なので、コマンドの記録には残らない。", "eg": "買い物のレシートに例えると、店員に暗証番号を大声で伝えて会計する（config setやコマンドライン引数）とレシートや記録に残ってしまうが、あらかじめ財布に忍ばせておいたメモ（環境変数）を自分だけで参照する形なら、会計の記録そのものには残らない。", "terms": [["環境変数", "OS上で一時的に設定できる値。コマンドの実行ログや設定ファイルに残らずにプログラムへ値を渡せる"], ["gcloud config set", "gcloud CLIの設定値を恒久的に構成ファイルへ書き込むコマンド。実行したこと自体がログに記録されうる"], ["CLOUDSDK_PROXY_USERNAME/PASSWORD", "gcloud CLIがプロキシ経由で通信する際に参照する、ユーザー名・パスワード用の環境変数"]], "think": "「ログに記録されることを防ぎたい」という要件から、認証情報を渡す方法のうち、コマンド実行や設定ファイルという「記録が残る経路」を避ける必要があると分かる。gcloud config setでプロキシのユーザー名・パスワードを設定する方法は、その設定コマンド自体がgcloudのログに記録されうるため、目的に反する。構成ファイルに直接書き込む方法も、平文の認証情報がファイルとして残ってしまい、ファイルの閲覧やバックアップを通じて漏洩するリスクがある。これに対し環境変数として認証情報を渡す方法は、シェルの実行時にのみ値が参照され、gcloudのコマンドライン自体や恒久的な設定ファイルには値が記録されないため、ログへの記録を避けられる。sha256のようなハッシュ関数は不可逆変換であり、元のパスワードに戻せないため、認証情報を実際の通信に使う値としてはそもそも使えない。", "vs": "config setによる設定は、設定操作自体がgcloudのログとして記録される可能性があるため「ログに記録されることを防ぐ」という目的と相反する。構成ファイルへの直接記述も、平文の認証情報がファイルという形で永続的に残ってしまう点でリスクが高い。", "opt": ["gcloud config setで設定する方法は、設定コマンド自体がログに記録されうるため、認証情報の露出を防ぐという目的に反する。", "sha256は不可逆なハッシュ関数であり、元のパスワードに戻せないため、そもそも実際の認証に使う値としては機能しない。", "構成ファイルに直接記述する方法は、平文の認証情報がファイルとして永続的に残ってしまい、漏洩のリスクが高い。", "正解。環境変数として認証情報を渡せば、コマンドの実行ログや恒久的な設定ファイルに値が記録されず、露出を防げる。"]}'::jsonb),
  ('m2q5', '{"asked": "特定のCMSソリューションをできるだけ迅速かつ簡単にデプロイ・インストールするには、どの方法を選ぶべきかを問うている。", "point": "「迅速かつ簡単」という条件なら、Cloud Marketplaceのウェブ画面からクリック操作で直接デプロイするのが一番の近道。", "why_asked": "CLIやTerraformでも技術的にはMarketplaceのソリューションをデプロイできるが、「簡単さ・速さ」という条件を重視すると、GUIからの直接デプロイに軍配が上がるという判断力が問われる。", "kid": "Cloud Marketplaceは「欲しいソフトを選んでボタンを押すだけで用意してくれるお店」のようなもの。CLIやTerraformを使う方法は、同じお店の商品を自分でコマンドを打って注文するようなもので、手間がかかる。", "eg": "家電量販店に例えると、店頭で欲しい商品（CMS）を選んでその場で配送設定まで済ませてもらう（Marketplaceから直接デプロイ）のが一番早い。同じ商品を注文書に細かくコードで書いて発注する（CLIやTerraform）方法は、確実だが手間と時間がかかる。", "terms": [["Cloud Marketplace", "GCP上で使える様々なソフトウェア（CMSなど）を、事前構成済みの形でカタログから選んですぐデプロイできるサービス"], ["Terraform", "インフラの構成をコードで記述し、それをもとにリソースを作成するツール。柔軟だがコードを書く手間がかかる"]], "think": "要件は「特定のCMSソリューションを迅速かつ簡単に」デプロイすることであり、機能面での正確さより速さと手軽さが優先されている。Cloud MarketplaceにはCMSを含む様々なソフトウェアのカタログがあり、ウェブ画面から検索してクリック操作だけで事前構成済みの環境をそのままデプロイできる。gcloud CLIやTerraformを使ってMarketplaceのソリューションをデプロイすることも技術的には可能だが、コマンドやコードを書く手間がかかる分、「簡単」という点でウェブ画面からの直接デプロイに劣る。CMSプロバイダの手順書に従って構成管理システムで自前インストールする方法は、環境構築やソフトウェアのインストール作業を自分で行う必要があり、最も時間と手間がかかる。", "vs": "CLIでのデプロイやTerraformでのデプロイは技術的に可能で再現性も高いが、コマンドやコード記述という追加の手間が発生する分、「迅速かつ簡単」という条件では画面からの直接デプロイに劣る。自前インストールの手順書に従う方法は、環境構築から全て自分で行うことになり、最も時間がかかる。", "opt": ["gcloud CLIでのデプロイは技術的には可能だが、コマンドを組み立てる手間がかかり、画面からの直接デプロイほど「簡単」ではない。", "正解。Cloud Marketplaceでカタログから検索し、ウェブ画面から直接クリック操作でデプロイするのが最も迅速かつ簡単。", "Terraformでのデプロイは再現性が高い反面、コードを記述する手間がかかり、「迅速かつ簡単」という条件では画面操作に劣る。", "CMSプロバイダの手順書に従って自前でインストールする方法は、環境構築から全て自分で行う必要があり、最も時間と手間がかかる。"]}'::jsonb),
  ('m2q50', '{"asked": "同じGKEクラスタ内で、常時稼働が必要なクリティカルな部分と、ダウンタイムを許容できる部分が混在するとき、コストを最適化するノードプールの構成をどう分けるべきかを問うている。", "point": "クリティカルな部分はStandard VMのノードプールに、ダウンタイムを許容できる部分はスポットVMのノードプールに乗せる。この組み合わせを絶対に逆にしない。", "why_asked": "スポットVMは大幅に安い代わりにいつでも強制終了されうるため、「安いから」という理由だけでクリティカルな部分に使ってしまう誤りが典型的に狙われる。ワークロードの性質に応じたノードプールの使い分けが問われる。", "kid": "常時稼働してほしい大事な仕事は、いつ席を立たされるか分からない安い座席（スポットVM）には座らせない。多少中断しても平気な仕事だけを、その安い座席に座らせる。", "eg": "引っ越し作業に例えると、絶対に落としてはいけない大事な荷物（クリティカルな部分）は信頼できる専用の運搬車（Standard VM）に乗せ、多少遅れても困らない荷物（ダウンタイムを許容できる部分）だけを、安いけれど途中で入れ替わるかもしれない便乗トラック（スポットVM）に乗せる。", "terms": [["Standard VMノードプール", "通常料金だが、Googleの都合で強制終了されることのない安定したノードプール。常時稼働が必要なワークロード向け"], ["スポットVMノードプール", "最大91%安い代わりに、Googleの都合でいつでも強制終了されうるノードプール。中断されても困らないワークロード向け"], ["ノードプール", "GKEクラスタ内で、同じ設定（マシンタイプや購入オプションなど）を持つノードのグループ。用途ごとに複数のノードプールを分けて使い分けられる"]], "think": "混在する2種類のワークロードを、同じ性質の場所にまとめて置くとどちらかに無理が生じる。まず単一のノードプールだけで構成する案を考えると、スポットVM単一プールにすればクリティカルな部分まで強制終了のリスクにさらされてしまい、逆にStandard VM単一プールにすればダウンタイムを許容できる部分まで割高な料金を払い続けることになり、コスト最適化にならない。したがって、性質の異なる2種類のワークロードにはそれぞれ別のノードプールを用意する必要がある。常時稼働が必要なクリティカルな部分は、強制終了されないStandard VMのノードプールに配置し、可用性を確保する。一方ダウンタイムを許容できる部分は、いつ終了されても業務に支障がないため、大幅に安いスポットVMのノードプールに配置してコストを削減できる。この対応関係を逆にしてしまうと、安さを取った側でクリティカルな部分が突然止まるリスクを抱えることになるため、絶対に逆にしてはならない。", "vs": "単一のノードプールだけで構成する案は、性質の異なる2種類のワークロードを同じ扱いにせざるを得ず、クリティカルな部分の可用性かコスト最適化のどちらかを犠牲にする。クリティカルな部分をスポットVMに、ダウンタイムを許容できる部分をStandard VMに割り当てる組み合わせは、対応関係が逆になっており、最も守りたいクリティカルな部分が中断リスクにさらされてしまう。", "opt": ["単一のStandard VMノードプールにラベルを付けるだけでは、実際にVMがスポットVMとして稼働するわけではなく、ダウンタイムを許容できる部分のコストも下がらない。ノードプール自体を分ける必要がある。", "単一のスポットVMノードプールにラベルを付けるだけでは、クリティカルな部分も実際にはスポットVM上で稼働し続けることになり、いつ強制終了されるか分からない状態のままになってしまう。", "対応関係が逆になっており、常時稼働が必要なクリティカルな部分をスポットVMに乗せてしまうと、いつ強制終了されるか分からず可用性の要件を満たせない。", "正解。クリティカルな部分はStandard VMのノードプールに、ダウンタイムを許容できる部分はスポットVMのノードプールに分けて配置すれば、可用性を保ちながらコストを最適化できる。"]}'::jsonb),
  ('m3q1', '{"asked": "aptでCloud SDKをインストールした環境で、Cloud Datastoreを使うアプリをローカルでテストするための追加コンポーネントを、どう入れるべきかを問うている。", "point": "SDK本体をどの方法でインストールしたかに、追加コンポーネントのインストール方法も合わせる。aptで入れたならコンポーネント追加もapt-get。", "why_asked": "gcloud components installはtar.gz形式でSDKを手動インストールした場合専用のコマンドであり、apt経由のSDKでは正しく機能しないという、インストール方法ごとの管理経路の違いが問われる。", "kid": "SDKを「アプリストアからダウンロードした」なら、追加機能もそのアプリストアから入れる。「手動でファイルをダウンロードして入れた」なら、追加機能も手動の仕組み（gcloud components）で入れる。入れ方を途中で混ぜない。", "eg": "スマホのアプリに例えると、公式ストア（apt）からインストールしたアプリの追加機能は同じ公式ストアから入れるのが自然で、非公式にファイルを直接コピーして入れた（tarball手動インストール）アプリだけが、専用の更新ツール（gcloud components）を使う仕組みになっている。", "terms": [["Cloud SDK", "gcloudなどGCPを操作するコマンドラインツール一式。aptパッケージまたはtarballファイルの手動展開のどちらかでインストールできる"], ["gcloud components install", "tarball形式で手動インストールしたSDKに対して、追加コンポーネントを入れるための専用コマンド"], ["Datastoreエミュレータ", "本番のCloud Datastoreに接続せずに、ローカル環境だけでDatastoreの動作をテストできる仕組み"], ["apt-get", "Debian/Ubuntu系Linuxで使われるパッケージ管理コマンド。パッケージのインストール・更新・削除を行う"]], "think": "ローカルでCloud Datastoreを使うアプリをテストするには、実際のクラウド上のDatastoreに接続せずに動作確認できるDatastoreエミュレータが必要になる。ここで重要なのは、Cloud SDKのインストール方法には大きく分けてaptパッケージ経由とtarballの手動展開の2種類があり、追加コンポーネントの入れ方もそれぞれの経路に対応させる必要があるという点。今回はUbuntuのパッケージリポジトリ（apt）からCloud SDKをインストールしているため、追加のエミュレータコンポーネントもapt-get installコマンドで、対応するパッケージ（google-cloud-sdk-datastore-emulator）をインストールするのが正しい方法になる。gcloud components installはtarball形式で手動インストールしたSDK専用のコンポーネント管理コマンドであり、aptで管理されているSDKに対して実行しても正しく機能しない。", "vs": "gcloud datastore exportやindexes createはDatastoreの運用コマンドであり、ローカルテスト環境そのものを用意するための手段ではない。gcloud components installはtarball手動インストールのSDK専用の管理コマンドで、apt経由でインストールしたSDKには使えない。", "opt": ["gcloud datastore exportはデータのエクスポート用コマンドであり、ローカルでテストするための実行環境を用意するものではない。", "gcloud datastore indexes createはインデックスを作成するコマンドであり、ローカルテスト用のエミュレータを用意する手段ではない。", "正解。aptでSDKを入れたなら、追加コンポーネントもapt-get installで対応するエミュレータパッケージを入れるのが、インストール経路に合った正しい方法。", "gcloud components installはtarball形式で手動インストールしたSDK専用のコマンドで、apt経由でインストールされたSDKには使えない。"]}'::jsonb),
  ('m3q10', '{"asked": "重要ワークロードのブートディスクを定期的にバックアップし、災害時には迅速に復元でき、古いバックアップは自動的に片付けたいとき、どの機能を使うべきかを問うている。", "point": "定期作成・保持期間による自動削除・迅速な復元をまとめて満たす組み込み機能がスナップショットスケジュール。自前でCronやFunctionsを組む必要はない。", "why_asked": "複数の要件（定期実行・保持管理・迅速復元）が並ぶと自作の仕組みで対応したくなるが、Compute Engineに標準搭載された機能だけで完結するケースを見極められるかが問われる。", "kid": "ディスクの「定期的に写真（スナップショット）を撮って、古い写真は自動的に処分してくれるカメラ」のような組み込み機能を、ディスクに設定するだけでいい。自分でカメラマンを雇う（自前のスクリプト）必要はない。", "eg": "家の防犯カメラに例えると、決まった時間ごとに自動で録画し、一定期間より古い映像は自動で消してくれる設定（スナップショットスケジュール）を最初にしておけば、あとは何もしなくても回り続ける。わざわざ人を雇って毎日録画・消去させる（Cronスクリプトや自前のジョブ）必要はない。", "terms": [["永続ディスクのスナップショット", "ディスクのある時点の状態を保存するバックアップ。差分のみを保存するため効率的で、これから新しいディスクを復元できる"], ["スナップショットスケジュール", "ディスクに対して、スナップショットの作成間隔・時刻・保持期間（自動削除のタイミング）をまとめて設定できる組み込み機能"], ["Cloud Tasks", "処理の実行タイミングをキューイング・スケジューリングする仕組み。今回のようなディスクバックアップの定期実行には、より専用のスナップショットスケジュールがある"]], "think": "要件を分解すると「定期的なバックアップ」「迅速な復元」「古いバックアップの自動クリーンアップ」の3つになる。永続ディスクのスナップショットスケジュールという機能は、この3つをまとめて満たす組み込み機能で、ディスクに対してスナップショットを作成する間隔・時刻を設定でき、さらに保持期間を過ぎたスナップショットは自動的に削除される設定も含まれている。スナップショットからは新しいディスクを迅速に作成・アタッチできるため、災害時の復元にも対応できる。これに対しCloud FunctionsやCronジョブを使って自前でスナップショット作成・削除の処理を実装する案は、すでに存在する組み込み機能をわざわざ再実装することになり、開発・運用の手間が余分にかかる。Cloud Tasksでイメージを作成しCloud Storageにエクスポートする案も、イメージ化とエクスポートという余分な手順が入り、スナップショットスケジュールほど簡潔ではない。", "vs": "Cloud Functionsでインスタンステンプレートを作る案は、そもそもディスクのバックアップという目的と直接結びつかない。Cronジョブで新しいディスクを都度作成する方式は、スケジュールされたバックアップの作成はできても、保持期間に応じた自動クリーンアップの仕組みを別途自分で作る必要があり、組み込み機能より手間がかかる。", "opt": ["Cloud Functionsでインスタンステンプレートを作成する操作は、ディスクのバックアップという目的と直接結びつかない。", "正解。永続ディスクに対してスナップショットスケジュールを設定すれば、定期的な作成・迅速な復元・保持期間に応じた自動削除を全て組み込み機能でまかなえる。", "Cronジョブでの新規ディスク作成は、定期的なバックアップの作成はできても、古いバックアップの自動クリーンアップの仕組みを別途自分で作る必要があり手間がかかる。", "Cloud Tasksでイメージを作成しCloud Storageにエクスポートする方式は、イメージ化とエクスポートという余分な手順が入り、組み込みのスナップショットスケジュールより手間がかかる。"]}'::jsonb),
  ('m3q11', '{"asked": "外部監査人に監査ログとデータアクセスログをレビューしてもらう権限を用意するには、どのロールを割り当て、どう案内すべきかを問うている。", "point": "監査ログとデータアクセスログの両方を閲覧できる事前定義ロールがroles/logging.privateLogViewer。ログエクスプローラで直接レビューできるので、わざわざエクスポートする必要はない。", "why_asked": "データアクセスログは通常の閲覧権限では見られない特別に保護されたログであり、専用のロールが必要だという前提を知らないと、より広いロールを選んでしまったり、不要なエクスポート作業を挟んでしまったりする。", "kid": "監査ログの中でも「誰が何のデータを見たか」という特に重要な記録（データアクセスログ）は、鍵のかかった特別な棚にしまわれている。その棚を開けられる専用の鍵がprivateLogViewer。", "eg": "病院のカルテ室に例えると、一般的な診療記録（普通のログ）は通常のスタッフ証で見られるが、「誰がどの患者のカルテを閲覧したか」という特に機微な記録（データアクセスログ）は、専用の鍵（privateLogViewer）を持つ人だけが見られる仕組みになっている。", "terms": [["監査ログ", "GCPで誰が何をしたかを記録するログ。管理アクティビティログとデータアクセスログなど複数の種類がある"], ["データアクセスログ", "データの読み取り・書き込みといった、リソースの中身へのアクセスを記録する監査ログの一種。デフォルトでは閲覧に特別な権限が要る"], ["roles/logging.privateLogViewer", "監査ログとデータアクセスログの両方を閲覧できる、Google Cloudの事前定義ロール"], ["ログエクスプローラ", "Cloud Logging上でログを検索・閲覧できる画面。privateLogViewerがあればここで直接レビューできる"]], "think": "外部監査人に求められているのは「監査ログとデータアクセスログのレビュー」であり、これらは通常のログとは別に、閲覧に特別な権限が必要な保護されたログになる。roles/logging.privateLogViewerは、まさにこの監査ログとデータアクセスログの両方を閲覧できるよう設計された事前定義ロールで、このロールを割り当てれば、監査人はログエクスプローラの画面上で直接ログをレビューできる。したがってログをわざわざCloud Storageにエクスポートする作業は不要で、むしろ余分な手順になる。カスタムロールで同等の権限（logging.privateLogEntries.list）を新たに作る案も、目的に合う事前定義ロールがすでに存在するため不要な手間になる。加えて、監査という目的を考えると、単にログを見られるだけでなく、権限昇格などの不正な操作がなかったかを確認する意味で、IAMポリシーの変更履歴（誰が誰にどんな権限を与えたか）もあわせてレビューするよう案内しておくことが実務上重要になる。", "vs": "ログをGCSにエクスポートする作業は、privateLogViewerがあればログエクスプローラで直接見られるため不要な追加手順になる。カスタムロールを新規作成する案は、同等の権限を持つ事前定義ロールがすでに存在する場合には避けるべきで、GCPのベストプラクティス（事前定義ロールの優先利用）に反する。", "opt": ["privateLogViewerがあればログエクスプローラで直接レビューできるため、GCSへのエクスポートは不要な追加手順になる。", "正解。privateLogViewerを割り当てれば監査ログ・データアクセスログの両方を直接レビューでき、加えてIAMポリシー変更ログのレビューも案内しておくのが実務上望ましい。", "目的に合う事前定義ロール(privateLogViewer)がすでに存在するため、同等の権限を持つカスタムロールをわざわざ新規作成する必要はない。", "カスタムロールが不要な上、GCSへのエクスポートも直接レビューできるため不要な追加手順になる。"]}'::jsonb),
  ('m3q12', '{"asked": "複数プロジェクトにまたがる過去60日分のログすべてに素早くアクセスし、内容を探索・分析したいとき、Googleが推奨する方法はどれかを問うている。", "point": "Cloud Loggingの標準保持期間は30日なので60日分を確保するにはエクスポートが必須。「探索・素早い分析」にはSQLが使えるBigQueryへのエクスポートが最適。", "why_asked": "Cloud Loggingのデフォルト保持期間（30日）を知らないと、エクスポートなしで検索すればいいと考えてしまう。また分析目的にはCloud StorageよりBigQueryが向いているという使い分けも問われる。", "kid": "Cloud Loggingは「最近30日分のメモしか自動では取っておいてくれない掲示板」のようなもの。60日分をちゃんと残して調べたいなら、あらかじめコピーを取っておく（エクスポート）必要がある。コピー先が計算が得意な倉庫（BigQuery）なら、後から素早く集計・分析できる。", "eg": "図書館の新着コーナーに例えると、Cloud Loggingは「直近30日分の新聞しか置いていない」新着棚のようなもの。60日分を残して調べたいなら、記事を専用のデータベース（BigQuery）に複製しておけば、あとからキーワード検索や集計がすぐにできる。ただ倉庫（Cloud Storage）に紙のまま保管しただけでは、検索や集計に手間がかかる。", "terms": [["Cloud Loggingのデフォルト保持期間", "Cloud Loggingが自動的にログを保持してくれる期間。標準では30日で、それを超えると自動的に消えていく"], ["Logging Export(ログシンク)", "Cloud Loggingのログを、BigQueryやCloud Storageなど別の保存先へ継続的にコピーし続ける設定"], ["BigQuery", "SQLでデータを検索・集計できる分析用のデータウェアハウス。ログを溜めて素早く分析する用途に強い"], ["テーブル有効期限", "BigQueryのテーブルに設定できる、一定期間を過ぎたデータを自動的に削除する設定"]], "think": "まず「過去60日分の全ログにアクセスしたい」という要件から考えると、Cloud Loggingは標準では30日分しかログを保持しないため、何も設定していない状態では60日分のログはすでに一部消えてしまっている可能性が高い。したがって60日分を確保するには、ログを外部の保存先へ継続的にコピーするLogging Export（シンク）の設定が必須になる。次に「内容を探索し迅速に分析したい」という要件を考えると、SQLでの検索・集計が得意なBigQueryが最も適した保存先になる。Cloud Storageも長期保管の保存先にはなるが、生ファイルとして貯まるだけでSQLのような柔軟な検索・分析には向かず、「迅速な分析」という条件では劣る。BigQueryへエクスポートする際、テーブルの有効期限を60日に設定しておけば、必要な期間を過ぎた古いデータは自動的に削除され、無駄なストレージコストも抑えられる。", "vs": "resource.labels.project_id=\"*\"のような検索だけでは、Cloud Loggingの30日という保持期間の壁自体は超えられず、60日分のログを確保する解決にはならない。Cloud Storageへのエクスポートは長期保管には向くが、SQLのような柔軟な探索・分析には不向きで「迅速に分析」という条件に劣る。Cloud Schedulerで自前の読み取り・保存処理を組む案は、すでにLogging Exportという組み込み機能があるのにわざわざ開発することになり非効率。", "opt": ["ワイルドカードでの検索を行っても、Cloud Loggingの30日という保持期間の壁自体は超えられず、60日分のログを確保できない。", "正解。BigQueryをシンク先とするLogging Exportを設定してテーブル有効期限を60日にすれば、60日分のログを確保しつつSQLで素早く探索・分析できる。", "Cloud Storageへのエクスポートは長期保管には向くが、生ファイルのままではSQLのような柔軟な探索・分析がしづらく「迅速な分析」という条件に劣る。", "Logging Exportという組み込みの仕組みがすでにあるため、Cloud SchedulerとBigQueryへの自前の読み取り保存処理をわざわざ実装する必要はない。"]}'::jsonb),
  ('m3q14', '{"asked": "web-applicationsプロジェクトのVMが、別プロジェクト(crm-databases-proj)のBigQueryデータセットへアクセスする権限を、どちらのプロジェクトにどう設定すべきかを問う。", "point": "権限は「データが実際に置いてある側のプロジェクト」に付与する。閲覧だけなら最小権限のbigquery.dataViewerで足りる。", "why_asked": "複数プロジェクトをまたぐ権限設計は、GCPを使い始めた人がまず迷うところ。「アクセスする側」に権限を盛りたくなるが、IAMは「リソース側」で許可を出す仕組みなので逆に考えると失敗する。加えてBigQueryはクエリを実行する側の課金・実行権限も別に要るという、うっかり見落としやすい二段構えになっている。", "kid": "データを見に行きたい側(web-applications)ではなく、データが置いてある側(crm-databases-proj)に「このVMは見てよい」という許可証を貼る。それだけで閲覧できるようになる。", "eg": "図書館の本を借りたいとき、自分の家に「入館証」を置いても意味がない。入館証は図書館(データがある側)の受付に登録してもらう必要がある。", "terms": [["IAMロール", "「誰が」「何に」「何をしてよいか」をひとまとまりにした許可証"], ["bigquery.dataViewer", "BigQueryのデータセットを読み取り専用で見られる最小権限のロール"], ["サービスアカウント", "人間ではなくVMやプログラムに割り当てる、専用のGoogleアカウント"], ["ジョブ", "BigQueryでSQLを実行する処理の単位。実行した側のプロジェクトに課金される"]], "think": "まずIAMの大原則を押さえる。権限は「アクセスしたい側」ではなく「リソースが置いてある側」に設定する。今回データセットがあるのはcrm-databases-projなので、そこにこのVMのサービスアカウントを登録し、閲覧だけなら最小権限のbigquery.dataViewerを付与する。オーナーロールのような強い権限を渡すと削除や設定変更までできてしまい過剰。ただしこれだけでは終わらない。BigQueryでSQLを実行すると、その処理(ジョブ)はクエリを投げた側のプロジェクト、つまりweb-applicationsに課金・記録される。ジョブを実行する権限はデータを読む権限とは別物なので、web-applications側にもジョブ実行に必要な適切なロールを付与しておく必要がある。データを読む許可はデータ側、処理を実行する許可は実行側、と役割が分かれている。", "vs": "「両方のプロジェクトにオーナーを付与」は権限が過剰で最小権限の原則に反する。「アクセスする側(web-applications)のオーナーに権限を渡す」は、そもそも権限を置く場所が逆。「データ側にオーナー、実行側にdataViewer」は付与するロールと場所が逆転している。", "opt": ["web-applicationsのプロジェクトオーナーに権限を渡しても、データがあるcrm-databases-proj側の許可にはならない。権限は付与する場所を間違えている。", "両方のプロジェクトにオーナーロールを渡すのは強すぎる。閲覧だけならデータを削除・変更できるオーナーは不要で、最小権限の原則に反する。", "データ側(crm-databases-proj)にオーナーロールを渡すのは過剰。逆にVM側(web-applications)にdataViewerを渡しても、データがあるのはcrm-databases-proj側なので意味がない。", "正解。データが置いてあるcrm-databases-projに閲覧用の最小権限bigquery.dataViewerを付与し、クエリを実行する側のweb-applicationsにも実行に必要な適切なロールを付与する。権限の置き場所と粒度がどちらも正しい。"]}'::jsonb),
  ('m3q15', '{"asked": "退職者が退職後に機密データへアクセスしていないかを確認するには、どのログをどう検索すればよいかを問う。", "point": "「データを見たかどうか」を調べたいなら、見た記録が残るのはデータアクセス監査ログ。人物の特定はメールアドレス(principalEmail)で行う。", "why_asked": "Cloud Loggingには似た名前のログ種別が複数あり、「何を記録するログか」を混同しやすい。特にセキュリティ監査の場面では正しいログ種別を選べないと調査自体が成立しないため、GCPの実務・試験の両方で問われやすい。", "kid": "「誰が何を見たか」の記録と「誰が何を設定変更したか」の記録は別の帳簿に分かれている。今回知りたいのは「見たかどうか」なので、その専用の帳簿を見る。", "eg": "マンションの記録に例えると、管理アクティビティログは「管理人室の設定を変えた記録」、データアクセス監査ログは「誰の部屋に誰が入ったかの記録」。今回知りたいのは後者。", "terms": [["監査ログ", "GCPが自動で残す「誰が・いつ・何をしたか」の記録の総称"], ["管理アクティビティログ", "リソースの作成・削除・権限変更など構成変更の記録。常時有効"], ["データアクセス監査ログ", "データの読み書きそのものの記録。BigQuery以外は既定で無効、明示的に有効化が必要"], ["principalEmail", "ログの中で「誰が行ったか」を示すフィールド。メールアドレスで人物を特定する"]], "think": "まず「何を知りたいか」から逆算する。今回知りたいのは「機密データを見たかどうか」というデータの読み取り行為そのものなので、対象になるログ種別は最初から一つに絞られる。管理アクティビティログは「設定やリソースをいじった記録」であり、データを読んだだけでは記録されない。システムイベントログはGoogle側が自動で行う操作(メンテナンスなど)の記録で、人間のユーザーの行動は残らない。残るのはデータアクセス監査ログで、これがデータの読み取り・書き込みそのものを記録する唯一のログ種別。次に「誰が」を特定する方法。GCPのログでは、行為者はサービスアカウントのIDではなく、実際にログインしたユーザーのメールアドレス(principalEmail)として記録されるので、退職者本人を追うにはこのメールアドレスで検索する。", "vs": "管理アクティビティログは「設定変更」の記録であり「データの中身を見た」記録ではない。システムイベントログはGoogle側の自動処理の記録で、人の操作は載らない。「SAを検索する」は今回の主体が人間のユーザーである以上、遠回りな探し方になる。", "opt": ["システムイベントログはGoogle側が自動で行う操作の記録で、退職者本人が手動でデータを見た記録は載らない。ログ種別の選択が誤り。", "システムイベントログである時点で対象外。加えてユーザーがデータを見た行為を追うなら、間に挟まるSAではなく本人のメールアドレスで直接検索する方が確実。", "正解。データを見たかどうかを調べるにはデータアクセス監査ログを見る。行為者の特定は退職者本人のメールアドレス(principalEmail)で検索する。", "管理アクティビティログは構成変更の記録であり、データを閲覧しただけの行為は記録されない。ログ種別を間違えている。"]}'::jsonb),
  ('m3q16', '{"asked": "作成したばかりのカスタムIAMロールについて、権限自体は本番利用に適したものだけを使いつつ、組織には「これはまだ初版」と明確に伝えたい場合、どの設定を選ぶべきかを問う。", "point": "権限のサポートレベル(supported/testing)とロールのステージ(ALPHA/BETA/GA)は別軸。「権限は本番品質」ならsupported、「初版であることを明示」ならALPHA、という組み合わせが決め手。", "why_asked": "カスタムロールを作るとき、「本番で使う=GA」だと早合点しやすい。実際にはロールの成熟度を示すステージと、個々の権限がGoogleにいつまで保証されるかを示すサポートレベルは独立した設定で、この2軸を混同すると誤った組み合わせを選んでしまう。", "kid": "カスタムロールには2つの別々のラベルが付けられる。1つは「中身の各権限がどれだけ安定しているか」のラベル、もう1つは「ロールという商品自体が今どの段階か」のラベル。この2つを別々に選ぶ必要がある。", "eg": "新商品の開発に例えると、「材料(権限)は市場に出せる品質のものだけ使う」ことと、「商品(ロール)自体はまだ試作第1弾だと社内に伝える」ことは両立する。材料の品質と商品の発売段階は別の話。", "terms": [["サポートレベル(supported/testing)", "カスタムロールに含める個々の権限が、Googleによって将来も安定して提供されるかを示す品質ラベル。testingは将来変更・廃止されうる"], ["ロールのステージ(ALPHA/BETA/GA)", "ロールという単位そのものが、組織内でどの開発段階にあるかを示すラベル。ALPHAは初期段階の意味"], ["カスタムロール", "既定のロールでは細かすぎ・粗すぎるときに、必要な権限だけを組み合わせて自作するロール"]], "think": "この問題は「権限の品質」と「ロールの成熟度」という独立した2つの軸を正しく組み合わせられるかを見ている。まず権限のサポートレベルを考える。「全権限は本番使用に適している必要がある」と明記されているので、Googleが本番運用で安定して保証するsupportedを選ぶ。testingはGoogleが将来仕様変更や廃止をする可能性がある権限なので、本番前提の条件と矛盾する。次にロールのステージを考える。「最初のバージョン」であり「組織にステータスを明確に共有したい」とあるので、これは権限の品質とは別問題で、ロール自体の成熟度をALPHAとして宣言する。ALPHAは「まだ育成中の初版である」という組織内向けの意思表示であり、権限そのものが本番品質かどうかとは無関係に選べる。ここで「本番で使うのだからGAにすべきでは」と考えると誤りで、GAはロールが組織内で十分に使い込まれ安定したと判断された後につけるステージであり、作成直後のロールに付けるものではない。", "vs": "「supportedかつBETA」はステージを進めすぎている。BETAは初版よりも運用が進んだ段階を示すラベルで、「最初のバージョン」という条件に合わない。「testing」を選ぶ組み合わせは、権限自体がGoogleに将来変更されうる不安定なものを含むことになり、「本番使用に適している必要がある」という条件そのものに反する。", "opt": ["正解。権限は本番品質のsupportedを使い、ロール自体は初版であることを示すALPHAステージにする。品質の軸と成熟度の軸をそれぞれ正しく選んでいる。", "権限のサポートレベルはsupportedで正しいが、ステージのBETAは「最初のバージョン」という条件より進んだ段階を表す。初版を明確に示すにはALPHAが適切。", "権限にtestingを選ぶと、Googleが将来変更・廃止しうる不安定な権限が本番ロールに混ざることになり、「全権限が本番使用に適している」という条件に反する。", "権限がtestingである時点で本番品質の条件を満たさない。さらにステージのBETAも「最初のバージョン」を示すにはALPHAより進みすぎている。"]}'::jsonb),
  ('m3q18', '{"asked": "複数のGCPプロジェクトを行き来しながら作業するとき、できるだけ少ない手数でgcloud CLIの対象プロジェクトを切り替えるにはどう構成すべきかを問う。", "point": "プロジェクトごとに名前付きの構成(configuration)をあらかじめ作っておき、切り替えはactivateの一発だけにする。", "why_asked": "gcloud initは「初期セットアップ用の対話ウィザード」であり、切り替えのたびに使うものではない。この使い分けを知らないと、毎回initを回して余計な質問に答え続けることになり、「最小の手数で」という条件を満たせなくなる。", "kid": "プロジェクトごとに「設定のセット」を名前を付けて保存しておける機能がgcloudにはある。作業するプロジェクトを変えたいときは、その名前を呼び出す(activateする)だけで切り替わる。", "eg": "複数の職場を掛け持ちする人が、職場ごとに「制服一式」を用意しておくようなもの。出勤先を変えるたびに服を一から選んで着替える(gcloud initし直す)のではなく、あらかじめ用意した制服(構成)にさっと着替える(activateする)方が速い。", "terms": [["gcloud configurations", "プロジェクトIDやデフォルトゾーンなど、gcloudの設定一式に名前を付けて保存・切り替えできる仕組み"], ["activate", "保存済みの構成を呼び出して、現在の作業対象として有効にするコマンド"], ["gcloud init", "gcloudを初めて使うとき、または設定を最初から作り直すときに使う対話式の初期設定ウィザード"]], "think": "「複数プロジェクトを最小の手数で行き来したい」という条件から逆算する。もしプロジェクトを切り替えるたびに毎回設定をゼロから聞かれるツールを使うと、切り替えの回数だけ手間が増えてしまう。gcloud initは対話形式で一からアカウントやプロジェクトを選ばせる初期セットアップ用のコマンドで、繰り返しの切り替えには向いていない。一方gcloud config configurationsを使えば、プロジェクトごとの設定一式(プロジェクトID・デフォルトゾーンなど)をあらかじめ名前を付けて保存しておける。作業するプロジェクトを変えたいときはactivateコマンドで名前を指定するだけで、一瞬で設定一式が切り替わる。あらかじめ準備しておく手間はあるが、日常的な切り替えの手数は最小になる。", "vs": "1つのデフォルト構成だけを使い回してactivateする方法は、そもそも構成が1つしかないため切り替えの意味をなさない。プロジェクトごとに構成は作るが、切り替えのたびにgcloud initで値を更新する方法は、切り替え1回ごとに対話ウィザードを回すことになり、手数が最小にならない。", "opt": ["正解。プロジェクトごとにgcloud configurationsで名前付き構成を作っておけば、切り替えはactivateコマンド一発で済み、手数が最小になる。", "構成を分けて作るところまでは正しいが、切り替えのたびにgcloud initを使うと毎回対話式の質問に答え直すことになり、手数が最小にならない。", "構成が1つしかないため、そもそも「切り替える対象」が存在せずactivateしても意味がない。プロジェクトごとに構成を分けていない時点で条件を満たさない。", "構成が1つしかない上に、切り替えのたびにgcloud initで値を更新するのは最も手数がかかる方法。プロジェクトごとの構成もactivateによる高速切り替えも使えていない。"]}'::jsonb),
  ('m3q20', '{"asked": "複数の開発チームに、隔離されたCassandraの開発環境をそれぞれ用意したい。管理側のサポート作業をできるだけ増やさずに、素早く実現するにはどうすべきかを問う。", "point": "事前構成済みのイメージをセルフサービスで各自が起動できるCloud Marketplaceを案内すれば、管理側の作業はほぼゼロで済む。", "why_asked": "「複数チームに同じような環境を素早く配る」という要件は、手順書を配って各自にインストールさせる発想に流れがちだが、それは環境構築の失敗・問い合わせ対応という形で結局管理側の負担に跳ね返ってくる。Marketplaceのようなセルフサービスの仕組みを知っているかどうかで、運用コストが大きく変わる。", "kid": "一からインストール手順を教えるのではなく、あらかじめ用意された「Cassandra入りの箱」をボタン一つで各自に起動してもらう。箱を作る手間もインストールの失敗対応も要らない。", "eg": "家具を一から木材を買って組み立てさせるのではなく、完成品の家具をカタログから選んでもらうようなもの。カタログ(Marketplace)から選べば、組み立て説明書(手順書)を配って質問攻めに遭う必要がない。", "terms": [["Cloud Marketplace", "OSやミドルウェアなどを事前構成済みのイメージやテンプレートとして提供し、数クリックでデプロイできるカタログ"], ["インスタンス", "Compute Engine上で実際に動いている仮想マシンの実体"]], "think": "条件を分解すると「複数チーム」「隔離された環境」「迅速」「最小限のサポート作業」の4つがある。手順書を作って配布する方法は、各開発者が手作業でインストールを行うため、環境ごとのミス・質問対応が発生しやすく、「最小限のサポート」という条件に反する。Cassandra VMを1つ構築してスナップショットを取り、そこから開発者用インスタンスを都度作る方法は、管理者(または誰か)がスナップショット取得・インスタンス作成の作業を毎回代行することになり、チーム数が増えるほど手間が積み上がる。Cloud Marketplaceは、Cassandraのような一般的なソフトウェアを事前構成済みのイメージとして提供しており、開発者自身がカタログから選んでボタン操作だけで自分専用のインスタンスを起動できる。各チームが自分の作業として完結するのでチームごとに隔離され、管理者が個別に手を動かす必要がない。これが「迅速」かつ「サポート作業最小」を同時に満たす唯一の選択肢になる。", "vs": "手順書配布はインストール作業そのものを開発者に押し付けるだけで、失敗時の問い合わせという形で結局サポート作業が発生する。スナップショットからの複製は、複製作業そのものを誰かが都度行う必要があり、開発者のセルフサービスにならない。", "opt": ["手順書を配ってインストールさせる方法は、開発者ごとの作業ミスや質問対応が発生しやすく、「最小限のサポート作業」という条件に反する。", "正解。Cloud Marketplaceの事前構成済みイメージを案内すれば、開発者が自分でボタン操作だけで環境を起動でき、管理側の作業がほぼ発生しない。", "スナップショットからインスタンスを作る作業を誰かが都度行う必要があり、チーム数が増えるほど管理側の手間が積み上がる。セルフサービスになっていない。", "スナップショットをGCSに置いた上で手順書まで作るのは、むしろ準備・保守の手間が最も大きい方法。迅速さもサポート最小化も満たしにくい。"]}'::jsonb),
  ('m3q23', '{"asked": "プロジェクト内に複数アプリが混在する状況で、特定のVM(Apacheサーバー)のネットワーク送信(Egress)コストだけを対象に、月100ドルを超えたらメール通知したい場合どうすべきかを問う。", "point": "予算アラートはプロジェクトや請求アカウント全体の合計額しか見られない。特定リソース・特定費用項目(SKU)単位で監視したいなら、請求データをBigQueryにエクスポートしてSQLで集計し、自作の通知処理を組む。", "why_asked": "「コスト通知」と聞くと反射的に予算アラートを思い浮かべがちだが、予算アラートは粒度が粗く、対象を絞った監視には対応できない。この「予算アラートでできること・できないこと」の境界線を知らないと、実現できない構成を選んでしまう。", "kid": "予算アラートは「プロジェクト全体でいくら使ったか」しか見てくれない。特定の1台のVMの、特定の費用項目だけを監視したいなら、詳しい請求データを取り出してきて自分で集計・通知の仕組みを作る必要がある。", "eg": "家計簿アプリの「今月の総支出が10万円を超えたら通知」機能だけでは、「子どものおやつ代だけが3000円を超えたら通知」という細かい条件には対応できない。細かく見たいなら、レシートの明細データを自分で集計し直す必要がある。", "terms": [["予算アラート", "プロジェクトや請求アカウント単位の合計コストに対して、しきい値超えをメール通知する組み込み機能。合計額のみが対象"], ["請求データのBigQueryエクスポート", "日々の詳細な請求明細(リソース単位・SKU単位)をBigQueryのテーブルへ自動で書き出す機能"], ["SKU", "課金項目を識別する単位。同じVMでもCPU・ディスク・ネットワーク送信などSKUごとに別の費用として記録される"], ["Cloud Scheduler", "指定した間隔で処理(この場合Cloud Functions)を自動的に起動する定期実行の仕組み"]], "think": "まず予算アラートで実現できることの範囲を確認する。予算アラートはプロジェクト全体、または請求アカウント全体の合計コストに対してしきい値を設定する機能であり、「このVMだけの」「Egressだけの」という絞り込みには対応していない。プロジェクトに複数アプリが同居している今回のケースでは、プロジェクト全体の予算アラートを設定しても、Apache VMのEgressだけが100ドルを超えたかどうかは判別できない。次に、実現するには何が必要かを考える。詳細な費用項目(SKU)単位でコストを追いたいなら、日次の詳細な請求データが要る。それを提供するのが請求データのBigQueryエクスポートで、リソース単位・SKU単位の明細がテーブルとして蓄積される。あとはそのテーブルに対してSQLでEgressに該当するSKUだけを絞り込んで集計し、100ドルを超えたかを判定するロジックをCloud Functionsに書き、Cloud Schedulerで毎時実行させれば、細かい条件でのメール通知が実現できる。", "vs": "予算アラートをプロジェクト単位・請求アカウント単位のどちらで設定しても、粒度がプロジェクト全体の合計額止まりで、特定のVM・特定のSKUだけを抜き出すことはできない。ApacheログのHTTPレスポンスサイズから概算する方法は、実際の課金額(GCPが計算する正確なEgress料金)と一致する保証がなく、正確なコスト監視としては不確か。", "opt": ["予算アラートはプロジェクト全体の合計コストしか見られない機能で、特定のVMのEgressだけを切り出して判定することができない。", "請求アカウント単位の予算アラートは、プロジェクト単位よりさらに粗い合計額しか扱えず、特定VMのEgressのような細かい条件には対応できない。", "正解。請求データのBigQueryエクスポートで詳細な明細を取得し、SQLでEgressのSKUだけを集計、Cloud FunctionsとCloud Schedulerで定期的にチェックしてメール送信する構成なら、特定VM・特定費目の監視が実現できる。", "Apacheログのレスポンスサイズから独自に金額を計算する方法は、GCPが実際に課金する正確なEgress料金と一致する保証がなく、正確なコスト監視にはならない。"]}'::jsonb),
  ('m3q25', '{"asked": "SSLで暗号化された非HTTPのTCPトラフィックを、世界中のクライアントから受け、かつレイテンシを最小化するにはどの種類のロードバランサーを選ぶべきかを問う。", "point": "「非HTTPのTCP」「SSL終端が必要」「世界中からグローバルに最短経路で」の3条件が同時に揃うのはSSLプロキシロードバランサーだけ。", "why_asked": "GCPのロードバランサーは対応するプロトコル層(L4かL7か)とスコープ(グローバルかリージョンかVPC内部か)で細かく種類が分かれており、この2軸を正しく組み合わせないと選択を誤る。実務でも「HTTPSロードバランサー=SSLの全部を受け持つ」と誤解しやすい落とし穴がある。", "kid": "この通信は「HTTPではないけど、鍵をかけて(SSLで)守られたTCPの通信」で、世界中から来る。だから「HTTP専用の窓口」ではなく、「SSLの鍵を開ける専用の、世界中どこからでも一番近い窓口につながる」ロードバランサーを選ぶ。", "eg": "空港の入国審査に例えると、HTTPSロードバランサーは「特定の書式のパスポート(HTTP)専用の窓口」。今回は書式が違う(非HTTP)封書付きの荷物(SSL暗号化TCP)なので、その荷物を開封できる専用窓口かつ、世界中どの空港からでも最寄りの窓口に案内してくれる仕組みが要る。", "terms": [["SSLプロキシロードバランサー", "非HTTPのTCPトラフィックに対応し、SSLの暗号化をロードバランサー側で終端(復号)できる、世界規模で最寄りの拠点に振り分けるロードバランサー"], ["ネットワークロードバランサー", "TCP/UDPをそのまま中継するリージョン単位のロードバランサー。SSLを終端する機能は持たない"], ["レイテンシ", "通信の要求から応答までにかかる遅延時間。拠点が近いほど短くなる"], ["グローバルロードバランサー", "単一のIPアドレスで世界中のクライアントを受け、地理的に最も近いバックエンドへ自動的に振り分けられる仕組み"]], "think": "条件を1つずつ絞り込んでいく。まず「HTTPSロードバランサー」はHTTP(S)というアプリケーション層のプロトコルを前提にした機能を多く持つ仕組みで、非HTTPのTCPトラフィックは扱えないため対象外になる。次に「ネットワークロードバランサー」は、TCP/UDPをそのまま中継するだけのリージョン単位(1つの地域内)の仕組みで、SSLの暗号化を代わりに終端する機能を持たず、かつ世界中のクライアントに対して最短経路を提供するグローバルな仕組みでもないため、レイテンシ最小化の条件を満たさない。「内部TCP/UDPロードバランサー」はそもそもVPCの内部だけを対象にした仕組みで、外部の世界中のクライアントを受けることができないため最初から候補から外れる。残るSSLプロキシロードバランサーは、非HTTPのTCPトラフィックに対応しつつSSLの暗号化をロードバランサー側で終端でき、かつグローバルな仕組みとして世界中のクライアントを地理的に最も近い拠点で受けられる。3つの条件をすべて満たすのはこれだけになる。", "vs": "HTTPSロードバランサーはHTTP専用でプロトコルの前提が合わない。ネットワークロードバランサーはリージョン単位でグローバルなレイテンシ最小化ができず、SSL終端の機能もない。内部TCP/UDPロードバランサーはVPC内部限定で外部クライアントを受けられない。", "opt": ["HTTPSロードバランサーはHTTPのトラフィックを前提にした仕組みで、非HTTPのSSL暗号化TCPトラフィックには対応していない。", "ネットワークロードバランサーはリージョン単位でSSLの終端機能も持たないため、世界中からのSSL暗号化トラフィックをグローバルに最短で処理する要件を満たさない。", "正解。SSLプロキシロードバランサーは非HTTPのSSL暗号化TCPトラフィックに対応し、世界規模で最寄りの拠点に振り分けてレイテンシを最小化できる。", "内部TCP/UDPロードバランサーはVPCの内部通信専用であり、世界中の外部クライアントからのトラフィックはそもそも受けられない。"]}'::jsonb),
  ('m3q26', '{"asked": "350GBのゾーンSSD永続ディスクで読み取りのスロットリング(速度制限)が発生している場合、コストを抑えつつ最大限のスループットを得るにはどうすべきかを問う。", "point": "SSD永続ディスクの性能はディスクサイズに比例して決まるので、サイズを上げるだけで追加のハードウェアを増やさずに性能を底上げできる。", "why_asked": "永続ディスクの性能が「容量に連動して自動的に決まる」という仕様を知らないと、「性能が足りないならCPUを増やす」「性能が足りないなら高価なローカルSSDに乗り換える」という遠回りで割高な対策に流れてしまう。コスト最小という条件を満たせるかどうかがこの仕様の理解にかかっている。", "kid": "永続ディスクは「容量を大きくするほど、読み書きの速度も一緒に速くなる」という決まりがある。だから遅いと感じたら、まず容量を増やしてみるのが一番安い解決策。", "eg": "水道管の太さと水量の関係に近い。細い水道管(小さいディスク)では水(データ)の流れる量に上限があるが、太い水道管(大きいディスク)に変えるだけで、蛇口(CPU)や別の給水設備(ローカルSSD)を増やさなくても流量が増える。", "terms": [["永続ディスク(Persistent Disk)", "Compute Engineのインスタンスに接続する、ネットワーク経由のストレージ。SSD版とHDD版がある"], ["スロットリング", "性能の上限に達し、それ以上の速度が出ないよう制限がかかっている状態"], ["ローカルSSD", "VMに物理的に直結された高速だが揮発性のストレージ。インスタンス停止でデータが消える"], ["リージョンSSD", "2つのゾーンに同期複製される高可用性向けのSSD。単一ゾーンSSDより高コスト"]], "think": "まず「なぜ容量を増やすだけで速度が上がるのか」を押さえる。GCPのSSD永続ディスクは、容量が大きいほどIOPS(1秒あたりの読み書き回数)とスループット(1秒あたりの転送量)の上限が線形に大きくなる仕様になっている。つまり350GBのディスクは350GB分の性能上限しか持っておらず、それを超える読み取り要求が来るとスロットリングがかかる。ここでディスクを1TBまで拡張すると、容量に連動して性能上限そのものが引き上げられ、スロットリングが解消する。しかも料金はディスクの容量に対してのみかかるので、追加のVMやハードウェアを増やす他の手段より安価。CPUを増やす方法は、ボトルネックがそもそもディスク側の性能上限にあるため、CPU性能を上げても解消しない。ローカルSSDへの移行は高いスループットを持つが、VMに直結されているためインスタンスの停止・再起動でデータが失われるリスクがあり、かつ料金も割高。リージョンSSDは複数ゾーンへの同期複製によって可用性を高める仕組みであり、目的が性能ではなく耐障害性なので、今回のスループット不足の解決にはならない上にコストも上がる。", "vs": "CPUを増やす対策はボトルネックの所在(ディスクの性能上限)を取り違えている。ローカルSSDは性能は出るがデータ揮発性とコストの面で「コスト最小」の条件に合わない。リージョンSSDは可用性向上が目的の機能で、スループット不足の解決策としては的外れな上にコストも増える。", "opt": ["正解。SSD永続ディスクの性能は容量に比例するので、1TBに拡張するだけで追加コストを抑えたまま読み取りスループットの上限を引き上げられる。", "スロットリングの原因はディスク側の性能上限であり、インスタンスのCPUを増やしても解消しない。ボトルネックの場所を取り違えている。", "ローカルSSDは高性能だがVM直結の揮発性ストレージでインスタンス停止時にデータが消え、料金も高い。コスト最小という条件に合わない。", "リージョンSSDは複数ゾーンへの複製で可用性を高める機能であり、スループット不足を解決する目的の機能ではない上にコストも上がる。"]}'::jsonb),
  ('m3q29', '{"asked": "事業買収でトラフィックが増える見込みのため、カスタム設定を施したCompute Engine VMを、今後何度も複製できる形で用意するにはどうすべきかを問う。", "point": "量産・スケールが前提なら、スナップショットから直接ではなく、いったん再利用可能なテンプレートである「カスタムイメージ」を作り、そこからインスタンスを作る。", "why_asked": "スナップショットとカスタムイメージはどちらも「複製の元」として使えるため混同しやすいが、想定する複製の回数・目的によって適切な方が変わる。試験ではこの使い分けの判断軸(1〜2台の一時対応かスケールを見越した量産か)が問われる。", "kid": "スナップショットは「今の状態を1回だけ写した写真」。カスタムイメージは「その写真をもとに作った、何度でも使えるハンコ」。何台も同じVMを増やしたいなら、写真そのものより何度も押せるハンコを作っておいた方が便利。", "eg": "料理のレシピに例えると、スナップショットは「今日作った1皿の写真」。カスタムイメージは「その写真をもとに書き起こした、繰り返し使えるレシピ書」。買収でお客さんが急増して同じ料理を何度も作る(VMを何台も増やす)なら、写真より使い回せるレシピ書を用意しておく方が効率的。", "terms": [["スナップショット", "ディスクのある時点の状態をまるごと保存したバックアップ。差分ベースで容量効率よく保存される"], ["カスタムイメージ", "OS・ソフトウェア・設定込みで、新しいインスタンスを何度でも作成できる再利用可能なテンプレート"], ["インスタンステンプレート", "マシンタイプやイメージなど、インスタンス作成に必要な設定一式を定義したひな形。カスタムイメージと組み合わせて使うことが多い"]], "think": "まず「今後何が起きるか」を確認する。事業買収によってトラフィックが増える見込みがあり、同じ設定のVMを複数台、繰り返し増やしていく必要が生じる可能性が高い状況になっている。スナップショットは特定の時点のディスクの状態を保存したバックアップであり、そこから直接インスタンスを作ることもできるが、これは1〜2台を一時的に複製するような場面に向いた手軽な方法で、量産を前提にした運用には向いていない。一方、スナップショットから一度カスタムイメージを作っておくと、そのイメージは何度でもインスタンス作成の元として使い回せる正式なテンプレートになる。トラフィック増に応じて何台も同じ構成のVMを素早く増やしていく今回のような場面では、量産の元になるカスタムイメージをまず用意しておき、そこからインスタンスを作る流れが最も効率的で拡張性が高い。", "vs": "スナップショットから直接インスタンスを作る方法は、1回限りの複製には手軽だが、何度も繰り返す量産用途には向かない。イメージからさらにイメージを作る(イメージの複製をもう一段作る)ことは通常の量産フローに不要な余分な手順で、目的(インスタンスを増やすこと)に直接つながらない。", "opt": ["スナップショットからイメージを作るところまでは正しいが、そのあと直接インスタンスを作らずスナップショットから作るという記述になっており、量産の元になるイメージが活用されていない。", "スナップショットから直接インスタンスを作る方法は1〜2台の一時的な複製には向くが、トラフィック増に備えた繰り返しの量産には非効率。", "カスタムイメージを作ったあと、さらにそのイメージから別のイメージを作るのは不要な手順で、本来の目的であるインスタンスの作成につながっていない。", "正解。スナップショットからカスタムイメージという再利用可能なテンプレートを作り、そこから複数のインスタンスを作成する流れが、トラフィック増に備えた量産に最も適している。"]}'::jsonb),
  ('m3q3', '{"asked": "会社が持つSAML対応のSSO基盤(IdP)を使って、Cloud Identity上に既に存在するユーザーをそのSSO経由で認証させたい場合、どう設定すべきかを問う。", "point": "認証を代行させたい側(会社のSSOシステム)をIdP、認証結果を受け取って使う側(Google)をSPとして構成する。この向きを間違えると成立しない。", "why_asked": "IdPとSPという2つの役割、そしてSAML(認証のプロトコル)とOAuth(認可のプロトコル)という2つの概念が同時に絡み、どちらも取り違えやすい。ACE試験ではこの「向き」と「用途」の取り違えを狙った選択肢が定番で出る。", "kid": "「あなたは本物です」と証明してくれる相手(会社のSSO)と、その証明書を受け取って使わせてくれる相手(Google)の役割を、正しい向きで設定する必要がある。", "eg": "会社の入館証(SSOでの認証)を見せれば、そのビルにあるカフェテリア(Googleのサービス)を使えるようにする仕組みを作るようなもの。入館証を発行するのは会社側(IdP)で、それを受け取ってサービスを提供するのがカフェテリア側(SP、この場合Google)。この向きを逆にしてしまうと、そもそも会社の入館証で入れる仕組みにならない。", "terms": [["IdP(Identity Provider)", "「この人は本物である」と証明する認証の発行元。今回は会社のSSOシステム"], ["SP(Service Provider)", "IdPが発行した証明を受け取って、サービスの利用を許可する側。今回はGoogle(Cloud Identity)"], ["SAML", "「誰であるか」を証明する認証のためのプロトコル。SSOのフェデレーションに使われる"], ["OAuth 2.0", "「誰が・何に・どこまでアクセスしてよいか」を扱う認可のためのプロトコル。認証そのものの証明には使わない"]], "think": "まず登場人物の役割を整理する。今回「認証させたい」相手は会社の既存のSSOシステムであり、これが「あなたは本物です」と証明する側、つまりIdPになる。証明を受け取ってサービスを使わせる側は、Cloud Identityを持つGoogleであり、これがSPになる。したがって設定すべきは、Cloud Identity側でサードパーティのIdP(会社のSSOシステム)を使うSSOをセットアップし、GoogleをSPとして構成する、という向きになる。「GoogleをIdPとしてカスタムSAMLアプリを設定する」という選択肢は、この向きが逆になっており、Googleが証明する側になってしまうため、会社のSSOで認証させるという要件を満たせない。またOAuth2.0を使う選択肢は、そもそも扱っているプロトコルの種類が違う。OAuthは「誰が何にアクセスしてよいか」という認可のためのプロトコルであり、「この人は誰であるか」を証明する認証には向いていない。モバイル/デスクトップ向けかウェブサーバー向けかという違い以前に、認証の要件に対してOAuthというプロトコル自体が不適合になる。", "vs": "「GoogleをIdPとする」設定は証明する側と受け取る側の向きが逆で、会社のSSOを主体にした認証にならない。OAuth2.0を使う2つの選択肢は、認可のプロトコルを認証の目的に使おうとしている点で、そもそも解決したい課題(認証のフェデレーション)とプロトコルの種類が噛み合っていない。", "opt": ["GoogleをIdPとして設定すると、証明する側と証明を受け取る側の向きが逆になり、会社のSSOシステムで認証させるという要件を満たせない。", "正解。会社のSSOシステムをIdP、GoogleをSPとして構成すれば、会社のSSO経由でCloud Identityのユーザーを認証させる仕組みが正しい向きで成立する。", "OAuth2.0は「誰が何にアクセスしてよいか」を扱う認可のプロトコルであり、「誰であるか」を証明する認証のフェデレーションには使えない。プロトコルの種類が要件と合っていない。", "モバイル/デスクトップ向けかウェブサーバー向けかという違いを問う前に、OAuth2.0自体が認証ではなく認可のためのプロトコルなので、今回の要件に合わない。"]}'::jsonb),
  ('m3q30', '{"asked": "VMにデプロイしたアプリがログをディスク上のファイルに書き出している状況で、エラー報告を受けて問題を診断したいとき、どうログを確認すべきかを問う。", "point": "ディスク上のログファイルは、そのままではCloud Loggingに現れない。Ops Agent(旧Loggingエージェント)をインストール・構成して初めて送信され、その後Cloud Loggingで見られるようになる。", "why_asked": "「Cloud LoggingにVMのログが自動的に集まる」と誤解しやすいが、実際にはエージェントという橋渡し役を挟まないと、ディスク上のファイルのログはGCP側に届かない。この前提を知らないと、Cloud Loggingを開いても何も表示されず診断が止まってしまう。", "kid": "ディスクに書かれたログは、そのままではGoogleのクラウド側には送られない。まず「ログを送る係(エージェント)」をVMに入れて働かせて、初めてCloud Loggingという場所でログが見られるようになる。", "eg": "会社の各部署(VM)が紙の日誌(ディスク上のログ)をつけているだけでは、本社(Cloud Logging)には情報が届かない。日誌の内容を本社に転送する係(エージェント)を各部署に配置して初めて、本社で一括して日誌を確認できるようになる。", "terms": [["Ops Agent(Cloud Loggingエージェント)", "VM上で動き、指定したログファイルの内容をCloud Loggingへ転送するソフトウェア"], ["Cloud Logging", "GCP上の各種ログを一箇所に集約して検索・閲覧できるサービス"], ["シリアルコンソール", "VMのOS起動画面などを直接のぞける低レベルな接続手段。アプリのログファイルの内容を見る用途には向かない"], ["ヘルスチェック", "VMやサービスが正常に応答しているかを定期的に確認する仕組み。ログの内容自体は見られない"]], "think": "まず「今何が起きているか」を確認する。アプリはログをディスク上のファイルに書き込んでいるだけで、Cloud Loggingへ送信する仕組みはまだ設定されていない。Cloud Loggingは、VM上で稼働するエージェント(Ops Agent)が指定したログファイルを読み取って転送して初めて、その内容が集約される仕組みになっている。したがって「Cloud Loggingに移動してアプリログを表示する」だけでは、そもそも転送されていないログはそこに存在せず、診断ができない。まずエージェントをインストールし、どのログファイルを転送するか構成する作業が先に必要で、その後にCloud Loggingを開けば内容が確認できるようになる。シリアルコンソールはOSの起動プロセスなど低レベルな出力を見る手段であり、アプリケーションが独自に書き出しているログファイルの中身を追う用途には向かない。ヘルスチェックのしきい値を調整する方法は、正常/異常の判定条件を変えるだけで、ログの内容そのものを見る手段ではないため、診断の役に立たない。", "vs": "「Cloud Loggingに移動して表示するだけ」は、エージェントによる転送という前提の工程が抜けている。シリアルコンソールは低レベルな起動ログ向けで、アプリ独自のログファイルの中身は見られない。ヘルスチェックの調整は異常検知の設定変更であり、ログの内容を確認する手段にならない。", "opt": ["エージェントによる転送が構成されていない状態では、ディスク上のログファイルの内容はそもそもCloud Loggingに存在せず、そこを見ても診断できない。", "シリアルコンソールはOSの起動時などの低レベルな出力を見る手段で、アプリが独自にディスクへ書き出しているログファイルの中身を確認する用途には向かない。", "ヘルスチェックのしきい値を変えても、正常/異常の判定条件が変わるだけでログの内容自体は見られず、エラーの原因診断にはつながらない。", "正解。Cloud Loggingエージェント(Ops Agent)をインストール・構成してディスク上のログをCloud Loggingへ転送させ、そのうえでCloud Loggingから内容を確認する。転送の前提が満たされている。"]}'::jsonb),
  ('m3q32', '{"asked": "開発用PC上でApplication Default Credentials(ADC)を使って認証していたアプリを、Compute Engine VMへ移行するとき、最小限の変更で認証を成立させるにはどうすべきかを問う。", "point": "VM上のADCは、そのVMに自動的にアタッチされているサービスアカウントをそのまま使う。だからコードは変えず、既存のVM用サービスアカウントに必要な権限を与えるだけで済む。", "why_asked": "開発PCでのADCは「開発者個人のユーザーアカウント」を裏側で使っているため、VMに移行する際に「新しいサービスアカウントを用意しないといけないのでは」と誤解しやすい。ADCが実行環境ごとに自動で異なる認証情報源を探しにいく仕組みだと理解していないと、不要な作業や危険な回避策(認証情報ファイルの同梱)に走ってしまう。", "kid": "ADCというのは「今どこで動いているかに応じて、勝手に一番適切な身分証を探して使う」仕組み。VM上で動くときは、そのVMに最初からくっついている専用の身分証(サービスアカウント)を自動で使ってくれるので、コードを書き換える必要がない。", "eg": "社員証で入退室するオフィスに例えると、自分のデスク(開発PC)にいるときは自分の社員証を使うが、別の部署のブース(VM)に移動したら、そのブースに備え付けの入館証(VMのサービスアカウント)を自動的に使うようなもの。備え付けの入館証に必要な権限さえ付けておけば、持ち物(コード)を変える必要はない。", "terms": [["ADC(Application Default Credentials)", "コードを変更せずに、実行されている環境ごとに適切な認証情報を自動的に探して使うGoogleのライブラリの仕組み"], ["サービスアカウント", "人間ではなくVMやアプリケーションに割り当てられる専用のGoogleアカウント。Compute Engine VMには既定で1つアタッチされている"], ["最小権限の原則", "必要な操作に必要な権限だけを与え、それ以上を与えない考え方"]], "think": "まずADCが何をしているかを理解する。ADCはコードの中で「今どの環境で動いているか」を意識させず、環境ごとに適切な認証情報を自動的に探しに行くライブラリの仕組みで、開発PC上ではローカルにログインしたユーザーの認証情報を、Compute Engine VM上ではそのVMにアタッチされているサービスアカウントの認証情報を、それぞれ自動的に使う。今回VMへ移行するので、ADCは自動的にVMのサービスアカウントを使うようになり、アプリのコードは一切変更する必要がない。Compute Engine VMには作成時点で既定のサービスアカウントが既にアタッチされているため、新しいサービスアカウントをわざわざ作る必要もなく、そのサービスアカウントに必要な権限(アクセス権)を割り当てるだけで認証が成立する。サービスアカウントの認証情報やユーザーアカウントの認証情報をファイルとしてVMに保存してデプロイする方法は、鍵ファイルが漏洩した場合にそのまま不正利用されるリスクがあり、しかもVMには既にADCで自動的に使えるサービスアカウントがあるため、そもそも不要な手間でありセキュリティ上も避けるべき方法になる。", "vs": "新しいサービスアカウントを作る方法は、VMに既にアタッチされているサービスアカウントを使わず余計な手間を増やしている。認証情報をファイルに保存してデプロイする2つの方法は、いずれも鍵の漏洩リスクを抱え、かつADCが自動で解決してくれる問題をわざわざ手動でやり直している。", "opt": ["正解。VM上のADCはVMにアタッチされたサービスアカウントを自動的に使うので、そのサービスアカウントに必要な権限を割り当てるだけでコード変更なしに認証が成立する。", "VMには既にサービスアカウントがアタッチされているため、新しいサービスアカウントを作る必要はなく、アプリでの構成変更も不要な手間になる。", "サービスアカウントの認証情報をファイルに保存してデプロイする方法は、鍵の漏洩リスクを抱える上、ADCが自動で解決できる問題をわざわざ手動で行っている。", "ユーザーアカウントの認証情報をVMに保存する方法は、個人の認証情報をサーバー上に置く点でセキュリティリスクが大きく、ADCの自動解決が使える場面には不要。"]}'::jsonb),
  ('m3q34', '{"asked": "月1回・約30時間ほどかかるバッチ処理で、オフラインでも実行可能だが途中で中断されると最初からやり直しになる場合、コストを最小に抑えつつクラウドへ移行するにはどうすべきかを問う。", "point": "「中断されたら最初からやり直し」というジョブには、いつ止められるか分からないプリエンプティブル(Spot)VMは使えない。月1回だけ通常VMを起動し、終わったら止める運用がコスト最小かつ確実。", "why_asked": "プリエンプティブル(Spot)VMは「安い」というイメージだけで飛びつきやすいが、Googleの都合でいつでも強制停止されるという制約がある。ジョブの性質(中断に強いか弱いか)を確認せずに安さだけで選ぶと、30時間分の処理が無駄になるという実害が出る。ACE試験ではこの「安さ」と「中断耐性」のトレードオフが頻出。", "kid": "「安いけど途中で急に止められることがある」VMと「多少高いけど止められない」VMの2種類がある。今回のジョブは途中で止められると最初からやり直しになるので、安いけど止められる方は選べない。多少高くても止められない普通のVMを、必要なときだけ動かすのが正解。", "eg": "一発勝負の実験に例えると、「いつ電源を切られるか分からないが安い実験室」を使って30時間かかる実験を走らせるのは危険。途中で電源を切られたら実験は最初からやり直し。多少コストがかかっても「電源が保証された実験室」を、必要な月1回だけ借りるのが確実で結果的に安上がり。", "terms": [["プリエンプティブルVM(Spot VM)", "通常より大幅に安いが、Googleの都合で最大24時間以内、または需要が高まったタイミングでいつでも強制停止されうるVM"], ["MIG(マネージドインスタンスグループ)", "同じ設定のVMを複数まとめて管理し、自動スケーリングや自動修復を行う仕組み"], ["バッチ処理", "データをまとめて一括で処理する実行形式。今回のように長時間かかり途中終了に弱いジョブもある"]], "think": "まず「中断されたら最初からやり直し」という制約を最優先で満たさなければならない。プリエンプティブル(Spot)VMは通常のVMより大幅に安い代わりに、Googleの都合でいつ強制停止されるか分からないという性質を持つ。もし30時間のジョブの途中、例えば29時間目で強制停止されたら、それまでの処理はすべて無駄になり、また30時間かけてやり直すことになる。これでは結果的にコストが余計にかさむ可能性があり、「コストを最小に」という目的自体を損なう。したがって、途中終了に弱いジョブにはプリエンプティブルVMを使わないことが大前提になる。次に、月1回・約30時間という実行パターンを踏まえると、常時VMを起動しておく必要はなく、実行するタイミングだけ通常のCompute Engine VMを起動し、処理が終わったら停止すればよい。起動している時間分だけ課金されるので、月のほとんどの時間は停止しておくことでコストを抑えつつ、通常VMなので処理の途中で強制停止される心配もない。", "vs": "プリエンプティブルVMを使う2つの選択肢(Compute Engine版・GKE版のどちらも)は、いずれも「中断されたら最初からやり直し」という条件と根本的に相容れない。プリエンプティブルVMのMIGでCPU使用率に応じてオートスケーリングする方法も同様に中断のリスクを抱えており、しかも今回は「月1回のバッチ」という単発の実行パターンに対してオートスケーリングという仕組み自体が過剰。", "opt": ["プリエンプティブルVMはGoogleの都合でいつでも強制停止されうる。途中で止められると最初からやり直しになるこのジョブでは、その強制停止のリスクが致命的。", "GKEのプリエンプティブルノードも同様にいつ停止されるか分からない性質を持ち、「中断されたら最初からやり直し」というジョブの制約と相容れない。", "正解。通常のCompute Engine VMを実行が必要な月1回のタイミングだけ起動し、終わったら停止すれば、強制停止のリスクなく、稼働時間分だけの課金でコストも最小に抑えられる。", "プリエンプティブルVMを使っている時点で強制停止のリスクを抱えており、さらに月1回だけの単発ジョブにオートスケーリングという仕組みは過剰で噛み合っていない。"]}'::jsonb),
  ('m3q36', '{"asked": "ほとんどのVMが特定のゾーン(europe-west1-d)で稼働している状況で、CLIコマンドを打つたびにゾーンを指定する手間を省くにはどうすべきかを問う。", "point": "gcloud configのサブコマンドでデフォルトのゾーンをあらかじめ設定しておけば、以降のコマンドではゾーン指定を省略できる。", "why_asked": "「よく使う値をデフォルト化する」という発想自体はシンプルだが、それをどこで設定するか(gcloudのローカル設定か、コンソールの画面か、VM側のメタデータか)を混同しやすい。特にVMのメタデータはVM自身が参照する情報であり、手元のCLIの挙動には影響しないという区別が問われる。", "kid": "毎回「ヨーロッパのこの場所で」と言わなくて済むように、CLIに「特に指定がなければここを使ってね」というデフォルトの場所を教えておく設定がある。", "eg": "いつも同じ最寄り駅から電車に乗る人が、乗換案内アプリに「出発駅はいつもこの駅」と登録しておくようなもの。毎回駅名を入力し直さなくても、アプリ側のデフォルト設定を見てくれる。", "terms": [["gcloud config", "gcloud CLIの既定値(プロジェクト・ゾーン・リージョンなど)を設定・確認するためのサブコマンド群"], ["compute/zone", "gcloud configで設定できるプロパティの1つ。Compute Engine関連コマンドの既定のゾーンを指定する"], ["メタデータ", "VMインスタンス自身に付与される情報(起動スクリプトや設定値など)。VM自身が参照するものであり、手元のCLIの動作には影響しない"]], "think": "まず「何が省略したいのか」を確認する。省略したいのは、手元の端末で打つgcloudコマンドに毎回付けているゾーン指定である。gcloudにはプロジェクトやゾーンなど頻繁に使う値をあらかじめ登録しておけるconfigというサブコマンド群があり、compute/zoneというプロパティにデフォルトのゾーンを設定しておけば、以降のコマンドでゾーンを省略した場合に自動的にそのゾーンが使われる。Compute Engineのコンソール画面(ブラウザ上のGUI)に「デフォルトロケーション」という設定項目は存在せず、そもそもCLIコマンドの挙動には影響しない。CLIのインストールディレクトリにdefault.confのような設定ファイルを作成してゾーンを制御する仕組みはgcloudには存在しない。VMのメタデータにcompute/zoneというキーを設定する方法も、メタデータはVM自身が起動時などに参照する情報であり、手元の端末から打つCLIコマンドの既定値には一切影響しない。", "vs": "コンソールの「デフォルトロケーション」設定は実在せず、そもそもCLIの挙動と無関係。default.confという設定ファイルの仕組みはgcloudに存在しない。メタデータのcompute/zoneキーはVM自身が参照する情報であり、手元のCLIコマンドの既定値には影響しない。", "opt": ["正解。gcloud configサブコマンドでcompute/zoneプロパティにデフォルトゾーンを設定すれば、以降のコマンドでゾーン指定を省略できる。", "Compute Engineのコンソール画面にそのような「デフォルトロケーション」設定項目は存在せず、手元のCLIコマンドの挙動にも影響しない。", "CLIのインストールディレクトリにdefault.confを作成してゾーンを制御するような仕組みはgcloudには存在しない。", "メタデータのcompute/zoneキーはVM自身が参照する情報であり、手元の端末で打つCLIコマンドの既定のゾーンには影響しない。"]}'::jsonb),
  ('m3q38', '{"asked": "プロジェクトA・B・Cにまたがるアプリのパフォーマンス(CPU・メモリ・ディスク)を、1つの画面でまとめて監視したい場合どうすべきかを問う。", "point": "複数プロジェクトをまたいだ統合監視には、ホストとなるプロジェクトの下にCloud Monitoringのワークスペースを作り、そこに他のプロジェクトを監視対象として追加する。", "why_asked": "「同じ画面で見たい」という要望に対して、単にロールを付与すれば見られるようになると誤解しやすい。実際にはIAMのロールは「誰が見てよいか」というアクセス権の話であり、「複数プロジェクトのデータを1つの画面に統合する」という仕組みそのものは別の機能(ワークスペース)が担っている。", "kid": "それぞれのプロジェクトの数字を別々の画面で見て回るのではなく、複数のプロジェクトのデータを1か所に集めて表示してくれる「監視専用の作業スペース」を作る。", "eg": "複数の支店(プロジェクト)の売上を、支店ごとに別々の帳簿を見て回るのではなく、本部(ワークスペース)に全支店のデータを集約して1枚のボードで見られるようにするようなもの。", "terms": [["Cloud Monitoringワークスペース", "1つのホストプロジェクトを起点に、複数のGCPプロジェクトの監視データを集約して1つの画面で扱えるようにする仕組み"], ["metrics.reader", "監視データを閲覧できるIAMロール。誰が見てよいかというアクセス権の話であり、複数プロジェクトの統合表示そのものを実現する機能ではない"], ["デフォルトダッシュボード", "1つのプロジェクトに標準で用意されている監視ダッシュボード。プロジェクトをまたいだ統合表示はできない"]], "think": "まず何が課題かを確認する。プロジェクトA・B・Cはそれぞれ独立したプロジェクトであり、既定では監視データもプロジェクトごとに別々に存在する。これを1つの画面にまとめるには、複数プロジェクトのデータを横断的に集約する仕組みそのものが必要になる。それを提供するのがCloud Monitoringワークスペースで、ホストとなる1つのプロジェクト(ここではプロジェクトA)の下にワークスペースを作成し、そこに監視したい他のプロジェクト(BとC)を監視対象として追加することで、3つのプロジェクトのCPU・メモリ・ディスクなどの指標を1つの画面で横断的に見られるようになる。「各プロジェクトにmetrics.readerロールを付与する」という方法は、そのプロジェクトのデータを見てよいという権限を与えるだけであり、複数プロジェクトのデータを1つの画面に統合する仕組みそのものではないため、権限があっても画面はプロジェクトごとに分かれたままになる。「デフォルトダッシュボードで各プロジェクトを順番に表示する」方法は、結局プロジェクトを切り替えながら別々の画面を見ることになり、「単一ビューで」という条件を満たさない。「各プロジェクトからグラフを共有する」方法も、個別のグラフを寄せ集めるだけで統合された監視の仕組みにはならない。", "vs": "ロールの付与はアクセス権の話であり、複数プロジェクトを1画面に統合する機能そのものではない。デフォルトダッシュボードを順番に表示する方法は、画面が統合されておらずプロジェクトを切り替える手間が残る。", "opt": ["APIを有効にしてグラフを個別に共有する方法は、バラバラのグラフを寄せ集めるだけで、1つの統合されたビューにはならない。", "metrics.readerロールの付与はそのプロジェクトを見てよいという権限の話であり、複数プロジェクトのデータを1画面に統合する仕組みそのものではない。", "デフォルトダッシュボードを順番に表示する方法は、結局プロジェクトを切り替えながら別々の画面を見ることになり、単一ビューという条件を満たさない。", "正解。ホストとなるプロジェクトの下にCloud Monitoringワークスペースを作り、他のプロジェクトを監視対象として追加すれば、複数プロジェクトの指標を1つの画面で横断的に見られる。"]}'::jsonb),
  ('m3q39', '{"asked": "異なる請求アカウントにひもづく複数プロジェクトの全コストを、1つの視覚的な表現で確認したい。かつ新しいコストデータをできるだけ早く反映したい場合、どうすべきかを問う。", "point": "「なるべく早く反映」「視覚化」の両方を満たすのは、請求データのBigQueryエクスポート＋Looker Studio(Data Studio)による可視化。エクスポートはほぼリアルタイムでデータが追加される。", "why_asked": "コスト可視化の手段はいくつもあるが、それぞれ「反映の速さ」と「対応できる範囲・粒度」が異なる。料金計算ツールは未来の見積もり用、CSVエクスポートは手作業で反映が遅い、というように用途を混同すると要件を満たせない。", "kid": "請求データをリアルタイムに近い形でBigQueryという表計算の巨大版に流し込んでおき、それをグラフ化ツール(Looker Studio)で見やすく描く。手作業でファイルをダウンロードして加工する方式より、ずっと早くて自動的。", "eg": "家計簿をつけるとき、レシートを毎回手で入力する(CSVエクスポート)よりも、キャッシュレス決済の履歴が自動的に家計簿アプリに同期される(BigQueryエクスポート)方が、最新の支出がすぐ反映される。", "terms": [["請求データのBigQueryエクスポート", "日々の詳細な請求明細をほぼリアルタイムでBigQueryのテーブルへ自動的に書き出す機能"], ["Looker Studio(旧Data Studio)", "BigQueryなどのデータソースをグラフやダッシュボードとして可視化する無料の可視化ツール"], ["料金計算ツール(Pricing Calculator)", "これから使う予定のリソースを入力して、将来かかる見積もり額を試算するためのツール。過去の実績データの可視化には使わない"]], "think": "まず要件を2つに分解する。1つは「異なる請求アカウントにまたがる全コストを単一の視覚的表現で見たい」こと、もう1つは「新しいコストデータをできるだけ早く反映したい」こと。料金計算ツールは、これから使う予定のリソース構成を入力して将来の費用を見積もるためのツールであり、既に発生した実際のコストを追跡する用途には使えないため対象外になる。Cloud Billing Consoleのレポートビューは請求アカウント単位の閲覧が基本で、複数の異なる請求アカウントを横断してひとつの視覚表現にまとめる用途には向かない。CSVエクスポートしてLooker Studioで可視化する方法は、可視化自体はできるが、エクスポートとアップロードを都度手作業で行う必要があり、「新しいデータをできるだけ早く反映したい」という条件に対して反映が遅れる。請求データのBigQueryエクスポートは、詳細な請求明細をほぼリアルタイムにBigQueryのテーブルへ自動的に追加していく仕組みで、手作業を挟まない。そのテーブルをLooker Studioに接続すれば、異なる請求アカウントの明細も含めて横断的に集計・可視化でき、新しいデータの反映も速い。", "vs": "料金計算ツールは未来の見積もり用で、実績コストの可視化には使えない。CSVエクスポートは可視化はできても手作業の分だけ反映が遅れる。Cloud Billing Consoleのレポートビューは基本的に1つの請求アカウント単位の閲覧が中心で、異なる請求アカウントを横断した単一の視覚表現には向かない。", "opt": ["正解。請求データのBigQueryエクスポートはほぼリアルタイムで明細が蓄積され、Looker Studioに接続すれば異なる請求アカウントを横断した可視化を素早く反映できる。", "CSVエクスポートは可視化自体はできるが、都度手作業でダウンロード・取り込みを行う必要があり、新しいデータの反映が遅くなる。", "料金計算ツールはこれから使う予定のリソースの将来の見積もりを出すためのツールで、既に発生した実績コストの可視化には使えない。", "Cloud Billing Consoleのレポートビューは基本的に請求アカウント単位の閲覧が中心で、異なる請求アカウントをまたいだ単一の視覚表現としてまとめる用途には向かない。"]}'::jsonb),
  ('m3q40', '{"asked": "VPNでオンプレミス(WAN)とつながっているVPCに新しいVMを配置するとき、公開インターネットからのトラフィックがそのVMに届かないようにするにはどうすべきかを問う。", "point": "一番確実で単純な方法は、そもそもVMに外部からアクセスできる公開IPアドレスを持たせないこと。届く住所自体が存在しなければ、公開インターネットからの通信はそもそも成立しない。", "why_asked": "ファイアウォールルールやルーティングなど「通信を制御する」手段に目が行きがちだが、それらは「届いた通信をどう扱うか」を制御する仕組みであり、そもそも「届く経路(公開IP)を作らない」というもっと根本的な対策があることを見落としやすい。", "kid": "家に表札(公開IPアドレス)を出さなければ、郵便配達員(インターネット上の通信)はそもそもその家を見つけて届けることができない。ドアに鍵をかける(ファイアウォール)よりも前に、表札自体を出さない方が確実。", "eg": "電話番号を公開していなければ、知らない相手からの電話はそもそもかかってこない。着信拒否設定(ファイアウォールルール)をあれこれ設定するより、番号自体を非公開にしてしまう方がシンプルで確実。", "terms": [["公開IPアドレス(外部IP)", "インターネット上から直接アクセスできる住所にあたるアドレス。これがなければインターネットから直接到達できない"], ["プライベートGoogleアクセス", "外部IPを持たないVMが、Google Cloud側のAPI等へアウトバウンド(外向き)で通信できるようにする設定。インバウンド(内向き)の通信制御とは無関係"], ["エグレスファイアウォールルール", "VMから外部への通信(出ていく方向)を制御するルール。今回問題になっている「外から入ってくる」方向の制御ではない"]], "think": "まず「公開インターネットからのトラフィックが届かないようにする」というゴールから逆算する。そもそもインターネット上のどこかから通信が届くためには、届け先となる公開IPアドレスが必要になる。VMに公開IPアドレスを持たせなければ、インターネット上から見てそのVMへ直接到達する経路自体が存在しなくなり、届けようがなくなる。これが最もシンプルかつ確実な対策になる。プライベートGoogleアクセスは、外部IPを持たないVMからGoogleのAPIなどへアウトバウンド(VMから外へ向かう)通信を可能にする設定であり、インバウンド(外からVMへ向かう)方向の制御とは無関係なので、今回の目的には効果がない。「VPCで全てを拒否するエグレスファイアウォールルール」も、エグレス(出ていく方向)の通信を制御するルールであり、外から入ってくる方向(インバウンド)の制御にはならないため、目的と噛み合っていない。「全トラフィックをVPNトンネル経由でルーティングする」方法は、オンプレミス側との通信経路を変えるだけで、そもそも公開IPアドレスが存在すれば、それとは別にインターネットから直接アクセスされる経路自体は残ってしまう。", "vs": "プライベートGoogleアクセスとエグレスファイアウォールルールは、どちらも「VMから外へ出ていく」方向の制御であり、「外から入ってくる」インバウンドの制御にはならない。VPNルートの設定はオンプレミスとの通信経路の話であり、公開IPが存在する限りインターネットから直接届く経路は別に残る。", "opt": ["正解。公開IPアドレスを持たずにインスタンスを作成すれば、インターネット上からそのVMへ直接届く経路自体が存在せず、最も確実に公開トラフィックを遮断できる。", "プライベートGoogleアクセスはVMから外部のGoogle APIへ向かうアウトバウンド通信のための設定で、外部から入ってくるインバウンド通信の制御には関係ない。", "エグレスファイアウォールルールはVMから出ていく方向の通信を制御するルールで、外部から入ってくる方向の通信の制御にはならない。", "VPNトンネル経由のルーティングはオンプレミスとの通信経路を変えるだけで、公開IPアドレスが存在する限りインターネットから直接届く経路は別に残ってしまう。"]}'::jsonb),
  ('m3q42', '{"asked": "平日の日中だけ使うアプリのVMを毎日バックアップし、30日間保持したい。管理の手間とサービス数を最小にするにはどう構成すべきかを問う。", "point": "スナップショットスケジュールという組み込み機能を使えば、頻度・時刻・保持期間を設定するだけで自動バックアップが完結し、追加のサービスを組む必要がない。", "why_asked": "「バックアップを自動化したい」と考えると、Cloud FunctionsやCloud Schedulerを組み合わせて自作したくなるが、実はGCPには同じことをするための専用の組み込み機能がすでに用意されている。この「まず標準機能を確認する」という視点が抜けると、不要に複雑な構成を作ってしまう。", "kid": "毎日決まった時間にバックアップを取って、30日経ったら古いものを自動で消してくれる機能が、ディスクの設定画面に最初から用意されている。それを使うだけで済む。", "eg": "毎晩決まった時間に部屋の掃除をしてくれて、30日以上前のゴミは自動で処分してくれる「お掃除ロボット」の予約機能のようなもの。自分で掃除の手順書を書いてロボットを組み立てる(Cloud Functions＋Scheduler)必要はなく、最初から付いている予約タイマー機能を設定するだけでよい。", "terms": [["スナップショットスケジュール", "頻度(毎日など)・開始時刻・保持期間を設定するだけで、ディスクの自動バックアップと古いスナップショットの自動削除まで行ってくれる組み込み機能"], ["管理オーバーヘッド", "構築・運用・監視に継続的にかかる人手や手間のこと"], ["メタデータ", "VMインスタンスに付与されるキーと値のペアの情報。snapshot-scheduleのような予約実行を制御する仕組みではない"]], "think": "まず「何を最小化したいか」を確認する。条件は「管理オーバーヘッド」と「使うサービスの数」の両方を最小にすることであり、機能面だけでなく構成のシンプルさが重視されている。Cloud Functionsでスナップショットの作成・削除処理を書き、Cloud Schedulerでそれを定期実行する方法は実現はできるが、コードの作成・保守、2つのサービスの管理が必要になり、オーバーヘッドとサービス数のどちらも増えてしまう。ディスクの内容をGCSにコピーするbashスクリプトをcrontabで実行する方法も同様に、スクリプトの保守とcron管理という手間が発生し、しかも30日後の自動削除のような保持期間の管理まで自分で書く必要が出てくる。一方、GCPのディスクには最初からスナップショットスケジュールという機能が組み込まれており、コンソールの画面上で頻度・開始時刻・保持日数を設定するだけで、日々の自動バックアップと期限切れスナップショットの自動削除までを追加のコードなしに完結できる。インスタンスのメタデータにsnapshot-schedule/snapshot-retentionのようなキーを追加してスケジュールを制御する仕組みはGCPには存在しない。", "vs": "メタデータでの設定という方法自体がGCPに存在しない。Cloud Functions＋Schedulerやbashスクリプト＋crontabは実現可能ではあるが、コード・複数サービスの保守という管理オーバーヘッドを追加で背負うことになり、「最小限」という条件に反する。", "opt": ["インスタンスのメタデータにsnapshot-schedule/snapshot-retentionを追加してバックアップを制御する仕組みはGCPには存在しない。", "正解。ディスクのスナップショットスケジュール機能で頻度・時刻・保持期間を設定すれば、自動バックアップと期限切れの自動削除までを追加のコードなしに完結でき、管理オーバーヘッドもサービス数も最小になる。", "Cloud FunctionsとCloud Schedulerを組み合わせる方法は実現できるが、コードの作成・保守と2つのサービスの管理が必要になり、オーバーヘッドとサービス数の両方が増えてしまう。", "bashスクリプトとcrontabによる方法は、スクリプトの保守や30日保持のロジックを自分で書く必要があり、標準機能を使う場合より管理の手間が大きい。"]}'::jsonb),
  ('m3q44', '{"asked": "Cloud Storage上にあるSpannerのバックアップデータと、Bigtableに残るイベントログを、特定ユーザーについて1回限りの調査として結合したい場合、どうするのが最も効率的かを問う。", "point": "1回限り(アドホック)の調査でデータを結合したいだけなら、データを動かさずにBigQueryの外部テーブルとして両方を参照し、SQLで直接結合するのが最も効率的。", "why_asked": "「複数のデータソースを結合する」と聞くとDataflowやDataprocのようなデータパイプライン基盤を反射的に思い浮かべがちだが、それらは繰り返し実行する本格的なパイプライン向けの重い構成。1回限りの調査という条件では、むしろ軽量で即座に使えるBigQueryの外部テーブルの方が効率的という判断が問われる。", "kid": "データをわざわざコピーして1か所に集める(パイプラインを組む)のではなく、元の場所にあるデータをBigQueryから「外部の棚を見に行く」ような形でそのまま参照して、SQLで突き合わせる。", "eg": "一度きりの調査のために、離れた2つの倉庫(Cloud StorageとBigtable)の在庫を1か所に運び込む(Dataflow/Dataprocでコピー・変換する)のは大掛かりすぎる。倉庫はそのままにして、両方の在庫リストを机の上で見比べる(BigQuery外部テーブルでSQL結合する)方が、1回きりの調査には手早い。", "terms": [["BigQuery外部テーブル", "Cloud StorageやBigtableなど、BigQueryの外にあるデータをコピーせずに、そのままSQLでクエリできるようにする仕組み"], ["Dataflow", "ストリーミング/バッチのデータ処理パイプラインを構築・実行するサービス。繰り返し使う本格的な変換処理に向く"], ["Dataproc", "Hadoop/Sparkのクラスタをマネージドで動かすサービス。既存のSpark資産の移行や大規模処理に向く"], ["アドホッククエリ", "定型化されたパイプラインではなく、その場限り・1回限りで行う問い合わせ"]], "think": "まず「1回限りの調査」という条件から必要な構成の重さを判断する。DataflowやDataprocは、繰り返し実行される変換処理や大規模なデータ移動を前提にしたパイプライン基盤であり、ジョブの設計・実行環境の構築といった準備が必要になる。今回のように「特定ユーザーについて1回だけ突き合わせて調べたい」という軽いアドホック分析には、準備の手間に見合わない重さになる。BigQueryには、Cloud StorageやBigtableのような外部のデータソースを、コピーせずにそのまま参照できる外部テーブルという仕組みがある。SpannerのバックアップはCloud Storage上にエクスポートされた形で存在し、BigtableのイベントログもBigtableのまま、それぞれ外部テーブルとして定義すれば、あとは通常のSQLでユーザーフィールドをキーに結合するだけで、必要なデータをその場で取り出せる。データを別の場所へ移動・コピーする手間がなく、1回限りの調査という目的に対して最も準備の少ない効率的な方法になる。", "vs": "DataflowもDataprocも、繰り返し使うパイプラインやクラスタベースの大規模処理に向いた重量級の構成であり、1回限りのアドホックな突き合わせには準備コストが見合わない。BigQuery外部テーブルはデータを動かさずその場でクエリできる点で、これらと対照的に軽量。", "opt": ["Dataflowジョブの作成はパイプラインの設計・実行という準備が必要な重い構成で、1回限りのアドホックな突き合わせには見合わない。", "対象データソースの組み合わせに関わらず、Dataflowジョブという構成自体が繰り返し利用を前提にした重い仕組みで、1回限りの調査には非効率。", "Dataprocクラスタを立ててSparkジョブを書く方法は、クラスタの構築・管理まで必要になり、1回限りの調査に対しては最も準備コストが大きい部類に入る。", "正解。Cloud StorageとBigtableをそれぞれBigQueryの外部テーブルとして定義すれば、データを動かさずにSQLでその場で結合でき、1回限りの調査に最も効率的。"]}'::jsonb),
  ('m3q45', '{"asked": "単一のゾーン(us-central1-a)だけでVMがアプリをホストしている状況で、そのゾーンで障害が起きても耐えられるようにし、ダウンタイムをなくし、かつコストを最小に抑えるにはどうすべきかを問う。", "point": "ゾーン障害に耐えるには、最低でも2つ目のゾーンにもリソースを用意し、両ゾーンに負荷を分散させておく。1つのゾーンにしかリソースがない構成では、そのゾーンが落ちた瞬間に必ず全滅する。", "why_asked": "「ダウンタイムを排除したい」と聞くと、ロードバランサーやヘルスチェックといった個別の機能強化に目が向きがちだが、そもそも稼働しているリソースが単一のゾーンにしか存在しなければ、そのゾーン自体の障害には何をどう強化しても耐えられない。「まずリソースを複数ゾーンに分散する」という一番土台の対策が抜けていないかが問われる。", "kid": "1つの街(ゾーン)にしかお店(VM)がないと、その街で災害が起きたらお店は全部止まってしまう。もう1つ別の街にも同じお店を用意しておき、両方の街のお店にお客さんを振り分けておけば、片方の街が止まってももう片方が営業を続けられる。", "eg": "発電所が1か所しかない街は、その発電所が止まると街全体が停電する。もう1つ別の場所にも発電所を作り、普段から両方で電力を分け合っておけば、片方が止まってももう片方でしのげる。", "terms": [["ゾーン", "1つのリージョン内にある独立した障害ドメイン(データセンター群)。あるゾーンの障害が別のゾーンに影響しないよう設計されている"], ["MIG(マネージドインスタンスグループ)", "同じ設定のVMをまとめて管理し、異常なインスタンスを自動的に置き換える(自動修復)仕組み。ただし対象ゾーンが1つだけならそのゾーン全体の障害には無力"], ["ヘルスチェック", "個々のインスタンスが正常に応答しているかを確認する仕組み。ゾーン全体が落ちた場合、正常なインスタンス自体が存在しなくなる"]], "think": "まず「単一ゾーン障害に耐える」という条件から考える。今のリソースはus-central1-aという1つのゾーンにしか存在しない。もしこのゾーン自体で障害が起きれば、そのゾーンの中にあるものは全て道連れで止まる。ここでus-central1-aの中だけでMIGを作り、ヘルスチェックの間隔を短くする対策を取っても、異常なインスタンスを置き換える(自動修復)機能はゾーン内のインスタンス単位の障害には有効だが、ゾーンそのものが丸ごと機能停止した場合は置き換える先すら存在しないため無力になる。HTTPSロードバランサーとグローバル転送ルールを作るだけの対策も、振り分け先のバックエンドがus-central1-aの1ゾーンしかなければ、そのゾーンが落ちた瞬間に振り分け先自体が消えてしまい意味をなさない。定期バックアップとアラート、障害時の手動復元という対策は、そもそも「手動で」「復元する」までの間に必ずダウンタイムが発生してしまい、「ダウンタイムを排除する」という条件そのものに反する。残る方法は、us-central1-bのような別のゾーンにも同じリソースを用意し、平常時から両方のゾーンに負荷を分散しておくこと。これなら片方のゾーンで障害が起きても、もう片方のゾーンが処理を引き受け続けられるため、ダウンタイムなく単一ゾーン障害に耐えられる。追加するのは最小限のリソース(2つ目のゾーン分)だけなので、コストの増加も必要最小限に抑えられる。", "vs": "単一ゾーン内だけのMIGやロードバランサーは、いずれもバックエンドがそのゾーン1つに依存しており、ゾーン全体の障害には対応できない。手動復元による対策は、復元が完了するまでの間のダウンタイムを避けられず、条件そのものに反する。", "opt": ["正解。us-central1-bにもリソースを用意し、両ゾーンに負荷を分散しておけば、片方のゾーンで障害が起きてももう片方が処理を引き受け続けられ、ダウンタイムなく単一ゾーン障害に耐えられる。", "us-central1-a内だけでMIGを作っても、バックエンドがそのゾーン1つに依存したままなので、ゾーン全体が機能停止した場合には自動修復の対象となるインスタンス自体が存在しなくなり無力。", "HTTPSロードバランサーを作っても、振り分け先がus-central1-aの1ゾーンしかない限り、そのゾーンが落ちれば振り分け先ごと失われ、ロードバランサーがあっても意味をなさない。", "定期バックアップと障害時の手動復元は、復元が完了するまでの間に必ずダウンタイムが発生する構成であり、「ダウンタイムを排除する」という条件を満たさない。"]}'::jsonb),
  ('m3q46', '{"asked": "引き継いだプロジェクトについて、現在プロジェクトオーナーのロールが付与されているユーザーを一覧で確認したい場合、どうすべきかを問う。", "point": "「今この瞬間、誰にどのロールが付いているか」を直接見たいなら、gcloud projects get-iam-policyでIAMポリシーそのものを取得するのが最も直接的。", "why_asked": "「誰が何をできるか調べたい」というとき、ログを掘り返して過去の履歴から推測しようとしがちだが、それは遠回り。IAMには「現在の設定そのもの」を直接返してくれるコマンドがあり、まずそれを使うべきという判断軸が問われる。", "kid": "誰が今どんな権限を持っているかを知りたいなら、過去の記録を遡って調べる必要はない。「今の権限の一覧表を出して」と直接聞けるコマンドがある。", "eg": "今このマンションの鍵を誰が持っているか知りたいとき、過去の鍵の受け渡し記録を全部さかのぼって調べる(監査ログ)よりも、管理会社に「今の鍵の所持者一覧をください」と直接聞く(get-iam-policy)方がずっと早い。", "terms": [["IAMポリシー", "あるリソース(プロジェクトなど)に対して、誰にどのロールが付与されているかをまとめた設定そのもの"], ["get-iam-policy", "指定したリソースの現在のIAMポリシー(ロール割り当て一覧)をそのまま取得するgcloudコマンド"], ["監査ログ", "過去に行われた操作の記録。現在の設定状態そのものではなく、変更の履歴を追うためのもの"]], "think": "まず「知りたいことは何か」を確認する。知りたいのは「現在、誰がオーナーロールを持っているか」という今この瞬間の状態であり、過去にどう変化してきたかという履歴ではない。SSH鍵の確認は、VMへのログイン用の鍵であり、IAMのプロジェクトオーナーロールの割り当てとは別物の情報なので今回の目的とは無関係。Identity-Aware Proxyは特定のリソースへのアクセスをアイデンティティベースで制御・保護する仕組みであり、プロジェクト全体のオーナーロールの一覧を出す機能ではない。全リソースの監査ログを有効にして結果を検証する方法は、過去の変更操作の記録を追うことはできるが、「今現在、誰がオーナーか」を知るには、過去のあらゆる付与・剥奪の履歴をすべて追跡して現在の状態を再構築するという遠回りな作業が必要になる。gcloud projects get-iam-policyコマンドは、指定したプロジェクトの現在のIAMポリシー、つまり今この瞬間の「誰にどのロールが付いているか」の一覧をそのまま返してくれるので、オーナーロールを持つユーザーを直接確認できる最も端的な方法になる。", "vs": "SSH鍵の確認はログイン鍵の話でIAMロールの割り当てとは別物。IAPはアクセス制御・保護の仕組みであってロール一覧を出す機能ではない。監査ログは過去の変更履歴を追うためのもので、現在の状態を知りたいだけなら遠回り。", "opt": ["SSH鍵はVMへのログインに使う鍵であり、プロジェクトオーナーロールの割り当てとは別の情報なので、今回の目的には結びつかない。", "Identity-Aware Proxyは特定のリソースへのアクセスを保護・制御する仕組みであり、プロジェクト全体のオーナーロールの一覧を確認する機能ではない。", "監査ログは過去に行われた変更操作の記録であり、現在誰がオーナーかを知るには、過去の付与・剥奪をすべて追跡して現在の状態を組み立て直す必要があり遠回り。", "正解。gcloud projects get-iam-policyコマンドは、現在のIAMポリシー(誰にどのロールが付いているか)をそのまま返すので、オーナーロールを持つユーザーを最も直接的に確認できる。"]}'::jsonb),
  ('m3q47', '{"asked": "同じサブネットを複数のVPCネイティブGKEクラスタで共有しており、ノードに割り当てるIPアドレスが枯渇してしまった場合、ノードを増やせるようにするにはどうすべきかを問う。", "point": "VPCネイティブクラスタのノードIPはサブネットのプライマリ範囲から割り当てられる。枯渇を解消するには、そのサブネットのプライマリ範囲(CIDR)を拡張する。", "why_asked": "GKEのIPアドレス設計では「ノード用」「Pod用」「Service用」でそれぞれ異なる範囲を使っており、この3種類を混同しやすい。ノードIPの枯渇に対してPod用のエイリアスIP範囲を増やしても解決しないという、範囲ごとの役割の違いが試験でも実務でも問われる。", "kid": "GKEのクラスタでは、ノード(VMそのもの)に配るIPアドレスと、その中で動くPod(コンテナの集まり)に配るIPアドレスが、別々の「名簿(IP範囲)」から割り当てられる。ノード用の名簿の枠が足りなくなったのだから、増やすべきはノード用の名簿であって、Pod用の名簿ではない。", "eg": "マンションの話に例えると、住民(ノード)の部屋番号を割り振る名簿と、各部屋にいる訪問客(Pod)用の受付番号を割り振る名簿は別々になっている。住民の部屋番号が足りなくなったのに、訪問客用の受付番号の枠を増やしても、住民は増やせない。", "terms": [["VPCネイティブクラスタ", "ノード・Pod・ServiceそれぞれのIPアドレスをVPCの正式なIP範囲(エイリアスIP含む)から割り当てるGKEクラスタの構成方式"], ["プライマリ範囲(プライマリCIDR)", "サブネットの基本となるIPアドレス範囲。ノードのIPアドレスはここから割り当てられる"], ["エイリアスIP範囲", "サブネットに追加で紐付ける、Pod用やService用のセカンダリなIP範囲。ノードのIPとは別枠"]], "think": "まずGKEのIPアドレスの割り当てルールを整理する。VPCネイティブクラスタでは、ノード(VM)のIPアドレスはサブネットのプライマリ範囲から割り当てられ、Pod用のIPアドレスはサブネットに追加されたエイリアスIP範囲(セカンダリレンジ)から割り当てられる、というように用途ごとに別の範囲が使われる。今回枯渇しているのは「ノードのIPアドレス」であり、これはプライマリ範囲の話になる。ここでエイリアスIP範囲を追加するという対策は、Pod用の枠を増やすだけであり、ノード用のプライマリ範囲の枠は増えないため、ノードのIP枯渇そのものは解消しない。同じリージョンに新しいサブネットを作る方法は、既存のクラスタが使っているサブネットとは別物になるため、既存クラスタのノードをそのまま増やす助けにはならない。新しいVPCを作って既存VPCとピアリングする方法も、既存クラスタのノードが使う既存サブネットの枠そのものを増やすわけではなく、遠回りな上に複雑さが増す。残るのは、クラスタが使っているサブネットのプライマリ範囲(CIDR)を拡張する方法で、GCPではサブネットのプライマリ範囲を後から拡張することが可能になっており、これによりノード用に使えるIPアドレスの枠そのものが直接増え、ノードを追加できるようになる。", "vs": "エイリアスIP範囲の追加はPod用の枠を増やすだけで、枯渇しているノード用のプライマリ範囲には影響しない。新しいサブネットの作成や新VPCとのピアリングは、既存クラスタが使っているサブネットの枠自体を増やすものではなく、根本解決にならない。", "opt": ["新しいサブネットを作成しても、既存のクラスタが使っているサブネットのプライマリ範囲自体は変わらず、既存クラスタのノードを増やす助けにはならない。", "エイリアスIP範囲はPod用のセカンダリな範囲であり、枯渇しているノード用のプライマリ範囲とは別枠なので、追加してもノードのIP不足は解消しない。", "新しいVPCを作ってピアリングしても、既存クラスタが使っているサブネットのプライマリ範囲そのものは増えず、根本的な解決にならない上に構成が複雑になる。", "正解。クラスタが使うサブネットのプライマリ範囲(CIDR)を拡張すれば、ノード用に割り当てられるIPアドレスの枠そのものが直接増え、ノードを追加できるようになる。"]}'::jsonb),
  ('m3q49', '{"asked": "データ流出を懸念するユーザーのために、外部への通信(egress)で開いているポートを必要最小限だけに絞りたい場合、ファイアウォールルールをどう組むべきかを問う。", "point": "ファイアウォールは番号が小さいほど優先度が高い。「原則すべて拒否、必要なものだけ許可」という許可リスト方式にするには、全拒否を優先度の低い番号(大きい数字)、必要なポートの許可を優先度の高い番号(小さい数字)にする。", "why_asked": "「優先度の高い/低い」という言葉と数字の大小(65534や1000など)の対応関係を逆に覚えやすい。この対応を取り違えると、拒否したいはずが許可になってしまう、あるいは意図した許可ルールが機能しないという致命的な設定ミスにつながる。", "kid": "ファイアウォールのルールには「順番」があり、数字が小さいルールほど先に効く。「まず全部だめ、と大きい数字(後回し)で決めておいて」「これだけはOK、と小さい数字(優先)で先に決めておく」と、結果的に「決められたものだけ通す」金庫のような仕組みになる。", "eg": "会社の出入り口に例えると、「基本は誰も通さない」という警備方針を最後の砦(優先度低)として敷いておき、「この人たちだけは通してよい」という許可証チェックを入口の一番手前(優先度高)に置く。手前のチェックで通った人はそのまま通れ、そうでない人は最後の「基本通さない」ルールで止められる。", "terms": [["ファイアウォールルールの優先度", "数字が小さいほど先に評価され優先される。0〜65535の範囲で設定でき、数字が大きいほど後回し(優先度が低い)"], ["エグレス(egress)", "VMやVPCから外部へ出ていく方向の通信"], ["許可リスト方式(ホワイトリスト)", "「原則すべて拒否」を土台にしておき、明示的に許可したものだけを通す設計方針"]], "think": "まずファイアウォールの優先度のルールを確認する。GCPのファイアウォールルールは数字が小さいほど優先度が高く、先に評価される。今回やりたいことは「開いているegressポートを最小限にする」ことなので、基本方針は「原則すべて拒否し、必要なポートだけを明示的に許可する」という許可リスト方式にする必要がある。この方式を実現するには、まず「全流出をブロックする」ルールを優先度の低い番号(65534のような大きい数字)に置いて土台とし、その上に「必要なポートだけを許可する」ルールを優先度の高い番号(1000のような小さい数字)で重ねる。すると、通信が来たときにまず優先度の高い許可ルールが先にチェックされ、許可されたポートの通信はそこで通り、それ以外の通信は最終的に優先度の低い全拒否ルールで止められる。もし逆に、全拒否ルールを優先度の高い番号(1000)に置き、許可ルールを優先度の低い番号(65534)に置いてしまうと、通信は先に評価される全拒否ルールで即座に止められてしまい、後から評価されるはずの許可ルールにたどり着く前にすべてブロックされる。これでは必要なポートの通信すら通らなくなってしまい、許可リスト方式が成立しない。", "vs": "受信ポートと流出ポートをペアにする方法は、優先度の使い分け自体が組み込まれておらず、許可リスト方式の土台(原則拒否)が作られていない。全拒否を優先度の高い番号に、許可を優先度の低い番号に置く組み合わせは、優先度の高低と数字の大小の対応が逆になっており、全拒否が先に評価されて許可ルールが機能しなくなる。", "opt": ["正解。全流出を拒否するルールを優先度の低い番号(65534)に、必要なポートだけを許可するルールを優先度の高い番号(1000)に置くことで、許可されたポートだけが通り、それ以外は最終的にブロックされる。", "受信ポートと流出ポートをペアにするだけの方法では、「原則すべて拒否してから必要なものだけ許可する」という優先度の構造が組み込まれておらず、開いているポートを最小限に絞る設計になっていない。", "全流出をブロックするルールを優先度の高い番号(1000)に置くと、そのルールが先に評価されて通信がすべて止められてしまい、後から評価される許可ルールにたどり着く前にブロックされてしまう。", "許可ルールだけを置いて全拒否の土台を作らない方法では、明示的に許可していないポートが暗黙的に許可されたままになりうる場合があり、「最小限に絞る」という許可リスト方式の設計にならない。"]}'::jsonb),
  ('m3q5', '{"asked": "データウェアハウスのアーカイブデータをCloud Storageに保存しており、規制要件で四半期に1回程度のアクセスがある場合、コスト効率が最も良いストレージクラスはどれかを問う。", "point": "アクセス頻度でストレージクラスを選ぶのが基本。「四半期に1回」というアクセス間隔にちょうど合うのはColdline。", "why_asked": "Cloud Storageのストレージクラスは「保存容量の料金」と「取り出し(アクセス)の料金」がトレードオフの関係にあり、アクセス頻度に対して適切なクラスを選ばないと、無駄にコストが高くなる。この対応表を正確に覚えているかが問われる。", "kid": "Cloud Storageには「よく出し入れするものを安く保管するクラス」と「めったに出し入れしないものを安く保管するクラス」がいくつかある。出し入れする頻度に合わせて選ぶと一番安くなる。", "eg": "家の収納に例えると、毎日使う調理器具(Standard)はすぐ手が届く場所に置く。季節ごとにしか使わない扇風機(Nearline)は少し奥にしまう。数年に一度しか使わない引っ越し用の道具(Archive)は屋根裏の奥に。四半期に一度使う季節行事の道具(Coldline)は、それらの中間くらいの位置にしまうと、取り出しやすさと保管効率のバランスが取れる。", "terms": [["Standardストレージ", "頻繁にアクセスするデータ向け。保存料金は高めだが取り出し料金は安い"], ["Nearlineストレージ", "月1回程度のアクセス頻度を想定したクラス。Standardより保存料金が安い"], ["Coldlineストレージ", "四半期(90日)に1回程度のアクセス頻度を想定したクラス。Nearlineよりさらに保存料金が安い代わりに取り出し料金が高め"], ["Archiveストレージ", "年1回以下のごくまれなアクセス頻度を想定した最も安い保存料金のクラス。取り出し料金は最も高い"]], "think": "Cloud Storageのストレージクラスは、保存料金と取り出し料金がアクセス頻度に応じてトレードオフになるよう設計されている。頻繁にアクセスするデータには保存料金が高めでも取り出しが安いStandardが向き、逆にめったにアクセスしないデータには保存料金が安く取り出し料金が高めのクラスが向く。この考え方に沿って、それぞれのクラスは想定アクセス頻度の目安を持っている。Nearlineは月1回程度、Coldlineは四半期(90日)に1回程度、Archiveは年1回以下という目安になっている。今回のデータは「規制要件で四半期に一度アクセスが必要」という条件が明示されており、これはColdlineが想定する頻度そのものに一致する。NearlineやRegional/Multi-Regionalのような頻繁アクセスを前提にしたクラスを選ぶと、四半期に一度しかアクセスしないデータに対して不必要に高い保存料金を払い続けることになる。逆にArchiveを選ぶと、90日より短い間隔でアクセスしたときに早期削除料金や割高な取り出し料金がかかる可能性がある。四半期という頻度にちょうど一致するColdlineが最もコスト効率が良い。", "vs": "Nearlineは月1回程度のアクセスを想定しており、四半期に1回というより低い頻度のデータに使うと保存料金を余分に払うことになる。Regional/Multi-Regionalは頻繁なアクセスを前提にした可用性重視のクラスで、アーカイブ用途にはそもそも保存料金が高すぎる。", "opt": ["正解。Coldlineは四半期(90日)に1回程度のアクセス頻度を想定したクラスで、今回の規制要件によるアクセス頻度にちょうど一致し、保存料金が最も抑えられる。", "Nearlineは月1回程度のアクセスを想定したクラスで、四半期に1回というより低い頻度のデータに使うと、Coldlineより保存料金が高くつく。", "Regionalストレージは頻繁なアクセスを前提にした可用性重視のクラスで、四半期に一度しかアクセスしないアーカイブ用途には保存料金が過剰に高い。", "Multi-Regionalストレージは複数リージョンでの高可用性を重視したクラスで、頻繁アクセス前提の料金体系のため、四半期に一度のアーカイブ用途には最もコスト効率が悪い部類に入る。"]}'::jsonb),
  ('m3q50', '{"asked": "Googleアカウントを持たない新しい運用パートナーに、Linux VMへのアクセスを許可したい場合どうすべきかを問う。", "point": "Linux VMの標準的な認証はSSHキーペアによるもの。Googleアカウントを前提にしないので、相手が公開鍵をVMに登録すれば、Googleアカウントなしでもアクセスを許可できる。", "why_asked": "GCPには複数のVMアクセス手段(IAP、SSHキー、VPN等)があり、それぞれが前提とする認証の仕組みが異なる。「Googleアカウントを持たない相手」という制約を見落として、Googleのアイデンティティを前提にする手段を選んでしまう典型的な誤りが起きやすい。", "kid": "GoogleのアカウントがなくてもLinuxのVMに入れる仕組みがある。相手に自分専用の鍵(SSHキーペア)を作ってもらい、その鍵に対応する「鍵穴」の情報(公開鍵)をVM側に登録しておけば、相手はその鍵でログインできる。", "eg": "マンションの合鍵に例えると、住民登録(Googleアカウント)をしていない訪問業者でも、合鍵(SSH公開鍵)を作ってドアの鍵穴情報として登録しておけば、その合鍵で出入りできるようにする仕組み。住民登録の有無とは関係なく成立する。", "terms": [["SSHキーペア", "秘密鍵(自分だけが持つ)と公開鍵(相手に渡す・登録する)のペアで本人確認を行う仕組み。パスワードなしでも安全にログインできる"], ["Cloud IAP(Identity-Aware Proxy)", "Googleのアイデンティティ(Googleアカウント)を前提に、VMへのアクセスを制御・保護する仕組み。Googleアカウントがない相手には使えない"], ["ネットワークタグ", "VMに付けるラベルで、ファイアウォールルールの適用範囲を絞り込むのに使う。認証そのものの手段ではない"]], "think": "まず制約条件を確認する。今回のパートナーはGoogleアカウントを持っていない。Cloud IAPはGoogleのアイデンティティ(Googleアカウントによるログイン)を前提にアクセスを制御・保護する仕組みなので、Googleアカウントがない相手にはそもそも使えない。ネットワークタグとポート22を許可するファイアウォールルールを設定する方法は、通信が届く経路(誰でもSSHのポートに到達できる状態)を作るだけであり、「誰であるか」を確認する認証の手段そのものではないため、これだけではセキュリティ上不十分。Cloud VPNはネットワーク同士を接続する経路の仕組みであり、個人の認証手段ではない。残るのはSSHキーペアによる認証で、Linux VMの標準的な認証方式はSSHの公開鍵暗号方式であり、Googleアカウントの有無とは関係なく機能する。パートナーに自分の秘密鍵・公開鍵のペアを生成してもらい、公開鍵の方だけをVM側の許可された鍵の一覧に追加すれば、パートナーは自分の秘密鍵を使って安全にログインできるようになる。この方式はGoogleのアイデンティティを一切前提にしないため、Googleアカウントを持たない相手にもそのまま使える。", "vs": "Cloud IAPはGoogleアカウントによる認証を前提にした仕組みで、Googleアカウントを持たない相手には使えない。ネットワークタグとFWルールは通信の経路を開けるだけで、本人確認(認証)の手段ではない。Cloud VPNはネットワーク同士の接続の仕組みで、個人の認証には使わない。", "opt": ["Cloud IAPはGoogleのアイデンティティ(Googleアカウント)を前提にアクセスを制御する仕組みで、Googleアカウントを持たないパートナーにはそもそも適用できない。", "ネットワークタグとポート22を許可するファイアウォールルールは通信が届く経路を開けるだけで、「誰であるか」を確認する認証の手段にはならない。", "Cloud VPNはネットワーク同士を接続するための経路の仕組みであり、個人を認証してVMへのログインを許可する手段ではない。", "正解。SSHキーペアはGoogleアカウントを前提にしない認証方式。パートナーに鍵ペアを作ってもらい公開鍵をVMに登録すれば、Googleアカウントなしで安全にログインを許可できる。"]}'::jsonb),
  ('m3q6', '{"asked": "データサイエンティストのチームが不定期にGPUを使い、しかも一度始めたら再起動できない長時間ジョブを走らせる場合、GKEでコストを最小限に抑えるにはどうすべきかを問う。", "point": "「不定期に必要」で「常時起動は無駄」、かつ「再起動できないのでSpotは危険」の両方を同時に満たすのは、GPUが必要になったときだけ自動でノードプールを作り、不要になったら消してくれるノードの自動プロビジョニング(NAP)。", "why_asked": "「不定期利用でコストを抑えたい」と聞くとプリエンプティブル(Spot)VMに飛びつきたくなるが、「再起動できない」という制約と両立しない。逆に「常にノードプールを立てておく」方式は安全だが無駄なコストがかかる。この2つの制約を同時に満たす仕組みを知っているかが問われる。", "kid": "GPUが欲しいときだけ、必要な分だけGPU付きのマシンを自動で用意してくれて、使い終わったら自動で片付けてくれる仕組みがある。しかも一度動き出したら勝手に止められることもないので、長い処理も安心して任せられる。", "eg": "たまにしか来ないお客さんのために、来客があったときだけ自動でテーブルと椅子(GPUノード)を用意し、帰ったら自動で片付ける会議室予約システムのようなもの。しかも会議中に予告なく追い出される(強制停止される)心配もない。", "terms": [["ノード自動プロビジョニング(NAP)", "GKEが必要なリソース(GPUなど)を要求するPodの出現に応じて、対応するノードプールを自動で作成し、不要になれば自動で削除する機能"], ["Vertical Pod Autoscaler", "1つのPodに割り当てるCPU/メモリの量を自動調整する機能。ノードプール自体の作成・削除は行わない"], ["プリエンプティブル(Spot)ノード", "安価だがGoogleの都合でいつでも強制停止されうるノード。再起動できないジョブには不向き"]], "think": "この問題には2つの制約が同時に課されている。1つは「不定期な利用」で、常にGPUノードを立てておくのはその間ずっと無駄な課金が発生するため避けたい。もう1つは「再起動できない長時間ジョブ」で、途中で強制停止されると処理がやり直しになってしまうため、プリエンプティブル(Spot)VMのような不安定なノードは使えない。ノード自動プロビジョニング(NAP)は、GPUを要求するPodが実際に投入されたときだけ自動的にGPU付きのノードプールを作成し、そのPodが終了すればノードプールも自動的に削除してくれる機能で、常時起動しておく必要がないため不定期利用によるコスト最小化を満たす。かつNAPが作るノードプールは通常のノードであり、Spotノードのように予告なく強制停止される心配がないため、再起動できない長時間ジョブとも両立する。Vertical Pod Autoscalerは既存のPodに割り当てるCPU・メモリ量を調整するだけの機能で、GPUノードプール自体の作成・削除は行わないため、「使うときだけ用意する」というコスト最小化にはつながらない。プリエンプティブル(Spot)VMとGPU付きノードプールを組み合わせる方法は、コストは安いがいつ強制停止されるか分からず、「再起動できない」という制約と正面から矛盾する。最小サイズ1でオートスケーリングを有効にする方法は、最小サイズ1という設定によって、利用がない時間帯もGPUノードが最低1台は起動し続けることになり、不定期利用にもかかわらず常に一定の課金が発生してしまう。", "vs": "Spot(プリエンプティブル)ノードの利用は、コストは安いが強制停止のリスクを抱えており、「再起動できない」という制約と矛盾する。最小サイズ1のノードプールは、利用がない時間も最低1台のGPUノードが起動し続け、不定期利用というコスト最小化の前提に反する。Vertical Pod Autoscalerはノードプール自体の増減を行わない別軸の機能。", "opt": ["正解。ノード自動プロビジョニング(NAP)は、GPUが必要なPodが来たときだけ自動でノードプールを作り、不要になれば自動で削除するので、不定期利用でも常時起動によるコスト無駄がなく、かつ強制停止のリスクもないため再起動できないジョブとも両立する。", "Vertical Pod Autoscalerは1つのPodに割り当てるCPU/メモリ量を調整するだけの機能で、GPUノードプール自体を自動で作成・削除する機能ではないため、不定期利用のコスト最小化にはつながらない。", "プリエンプティブル(Spot)ノードはGoogleの都合でいつでも強制停止されうるため、「再起動できない長時間ジョブ」という制約と正面から矛盾する。", "最小サイズ1でオートスケーリングを有効にすると、利用がない時間帯も最低1台のGPUノードが起動し続けることになり、不定期利用にもかかわらず常に一定のコストがかかってしまう。"]}'::jsonb),
  ('m3q8', '{"asked": "開発環境と同じプロジェクトに本番環境を構築する予定だったが、セキュリティチームから「開発環境と本番環境の間にネットワークルートが存在してはならない」という要件が出た場合、どうすべきかを問う。", "point": "GCPのプロジェクトはデフォルトでそれぞれ独立したVPC(ネットワーク)を持つので、本番用に新しいプロジェクトを分けて作るだけで、開発環境とのネットワーク的な分離が自動的に実現する。", "why_asked": "「ネットワークを分離したい」と聞くと、同じプロジェクト内でサブネットを分けたり、ファイアウォールルールで細かく制御したりする方向に発想しがちだが、それらは同じVPC内の話であり、ルート自体は依然として存在してしまう。「プロジェクトという単位そのものがネットワークの境界になる」という一番大きな粒度の切り分けを見落としやすい。", "kid": "同じ庭(プロジェクト)の中で柵(サブネットやファイアウォール)を立てても、庭そのものはつながったまま。本当に行き来できないようにしたいなら、そもそも別の庭(別のプロジェクト=別のVPC)を用意する。", "eg": "同じ建物の中で部屋を分ける(サブネット分け)だけでは、廊下(ネットワークルート)はつながったまま。本当に行き来を断ちたいなら、そもそも別の建物(別のプロジェクト)を建てる方が確実。", "terms": [["VPC(Virtual Private Cloud)", "GCPプロジェクトごとに存在する仮想的なネットワークの単位。既定では他のプロジェクトのVPCとはつながっていない"], ["ネットワークルート", "あるネットワーク内の通信がどこへ向かうかを決める経路情報。同じVPC内のサブネット同士には既定で経路が存在する"], ["共有VPC(Shared VPC)", "複数のプロジェクトから1つのVPCネットワークを共有して使う仕組み。むしろプロジェクト間の通信を可能にする方向の機能"]], "think": "まず要件を確認する。「開発環境と本番環境の間にネットワークルートが存在してはいけない」という制約は、通信の経路そのものを断つことを求めている。ここで、既存のVPC内に本番用のサブネットとCloud SQLを追加する方法を考えると、サブネットを分けても同じVPCの中である以上、サブネット同士をつなぐネットワークルートは既定で存在したままになり、要件に反する。既存のVPCを共有VPC化して新しいプロジェクトと共有する方法は、そもそも共有VPCが「複数のプロジェクトから1つのネットワークを共有して使えるようにする」ための仕組みであり、プロジェクトをまたいだ通信を可能にする方向の機能なので、ルートを無くしたい今回の目的とは正反対になる。GCPのプロジェクトは、作成した時点でそれぞれ独立したデフォルトVPCを持ち、他のプロジェクトのVPCとは既定でネットワーク的につながっていない。したがって本番環境用に新しいプロジェクトを作成し、必要なAPIを有効にして開発環境と同じ構成を作り直せば、開発環境のVPCとはそもそも別のネットワークになり、両者をつなぐルートは最初から存在しない状態が自動的に実現する。", "vs": "既存VPC内でサブネットを分ける方法は、同じVPCである以上ルートが残ってしまう。共有VPC化はプロジェクト間の通信を可能にする仕組みであり、遮断したい今回の目的とは逆方向。別部門の本番プロジェクトに間借りする方法は、そもそも自分たちの開発環境との分離という要件の対象外で、かつ他部門への依存という別の問題を生む。", "opt": ["正解。プロジェクトはデフォルトでそれぞれ独立したVPCを持つので、本番用に新しいプロジェクトを作成するだけで、開発環境とのネットワーク的な分離が自動的に実現し、ルートも存在しない。", "既存のVPC内にサブネットを分けて配置しても、同じVPCの中である以上サブネット同士をつなぐネットワークルートは既定で存在したままになり、要件に反する。", "共有VPCはむしろ複数のプロジェクトから1つのネットワークを共有し、プロジェクト間の通信を可能にする仕組みなので、ルートを無くしたいという今回の目的とは正反対の方向になる。", "別部門の本番プロジェクトに編集者ロールを依頼する方法は、そもそも開発環境とのネットワーク分離という要件と直接関係がなく、他部門への依存という別の懸念も生む。"]}'::jsonb),
  ('m3q9', '{"asked": "組織で「ドメイン制限共有」ポリシー(自社のCloud Identityドメインに属するアカウントしかリソースを共有できない設定)が有効になっている状況で、外部の監査人にプロジェクトの閲覧だけを許可したい場合どうすべきかを問う。", "point": "ドメイン制限共有ポリシーが有効だと外部のGoogleアカウントはそもそもIAMに追加できない。自社のCloud Identityに監査人用の一時アカウントを作り、そこに閲覧専用のviewerロールを与えるのが唯一の方法。", "why_asked": "「外部の人に見せたいだけならviewerロールを付ければよい」という発想は自然だが、組織ポリシーによって外部アカウント自体をそもそも登録できない状態になっていることを見落としやすい。「誰に付与するか(アカウントの所属)」と「何を付与するか(ロールの範囲)」の両方を正しく押さえないと解けない設問になっている。", "kid": "会社の決まりで「社員名簿にある人にしかカギを渡せない」ことになっているとき、外部の人にカギを渡したいなら、まずその人を一時的に社員名簿に載せる必要がある。名簿に載ったら、渡すカギは「見るだけ」の権限にする。", "eg": "社内限定の建物に外部の見学者を入れたいが、規則で社員証がない人は入館できないとき、まず見学者用の仮の社員証を発行し、その仮の社員証には「見学エリアのみ入室可」という権限だけを持たせるようなもの。", "terms": [["ドメイン制限共有(Domain Restricted Sharing)", "組織ポリシーの一種。指定したCloud Identityドメインに属するアカウント以外を、IAMのプリンシパルとして追加できないよう制限する"], ["Cloud Identity", "Googleのユーザー・グループを管理する基盤。ここにアカウントがあれば組織のドメインに属するプリンシパルとして扱える"], ["viewerロール(基本ロール)", "プロジェクト内のほぼ全リソースを読み取り専用で閲覧できる基本ロール"], ["Security Reviewerロール", "IAMポリシーやセキュリティ関連の設定を閲覧できる、範囲の狭い専用ロール。プロジェクト全体の閲覧用途には向かない"]], "think": "まず制約条件を確認する。ドメイン制限共有ポリシーが有効な組織では、自社のCloud Identityドメインに属さないアカウント(外部の監査人の個人Googleアカウントなど)は、そもそもIAMのプリンシパルとして追加すること自体ができない。したがって、監査人の既存のGoogleアカウントに直接どんなロールを付与しようとしても、ポリシーによってブロックされてしまう。この制約を回避するには、まず監査人を自社のCloud Identityドメインに属するアカウントにする必要があり、そのために監査人専用の一時アカウントをCloud Identity上に作成する。これでアカウントの所属という制約は解消される。次にロールの範囲を考える。「プロジェクトの閲覧のみ」という要件はプロジェクト内のリソースを広く読み取れることを求めており、これに対応するのはプロジェクト内のほぼ全リソースを読み取り専用で見られるviewerロールになる。Security Reviewerロールは、IAMポリシーなどセキュリティ関連の設定に閲覧範囲が限定された専用ロールであり、プロジェクト全体を見たいという今回の要件よりも狭い範囲しかカバーしない。", "vs": "監査人の既存のGoogleアカウントに直接ロールを付与する2つの方法は、ドメイン制限共有ポリシーによってそもそも外部アカウントの追加自体がブロックされるため成立しない。Security Reviewerロールはセキュリティ設定の閲覧に特化した狭い範囲のロールで、プロジェクト全体の閲覧という要件には範囲が不足する。", "opt": ["監査人の既存のGoogleアカウントは自社のCloud Identityドメインに属さないため、ドメイン制限共有ポリシーによってそもそもIAMへの追加自体がブロックされる。", "アカウントの所属の問題が解決していない上、Security Reviewerロールはセキュリティ設定閲覧に特化した狭い範囲のロールで、プロジェクト全体の閲覧という要件をカバーしきれない。", "正解。監査人用の一時アカウントを自社のCloud Identityに作成すればドメイン制限共有ポリシーの制約を満たし、そこに閲覧用のviewerロールを付与すればプロジェクト全体を読み取り専用で見せられる。", "一時アカウントを作りドメイン所属の問題は解決しているが、Security Reviewerロールはセキュリティ設定閲覧に特化した狭い範囲のロールで、プロジェクト全体の閲覧という要件には範囲が不足する。"]}'::jsonb)
) AS v(source_ref, value)
WHERE q.source_ref = v.source_ref
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'gcp-ace');

COMMIT;
